{
  "name": "Agendai - Sistema de Agendamento Inteligente",
  "description": "Uma plataforma completa para gestão de serviços e agendamentos com assistência de IA para criação de descrições e otimização de catálogo."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Service {
  id: string;
  name: string;
  description: string;
  duration: number; // in minutes
  price: number;
  category: string;
}

export interface Booking {
  id: string;
  serviceId: string;
  clientName: string;
  clientEmail: string;
  date: string; // ISO string
  time: string; // "HH:mm"
  status: 'pending' | 'confirmed' | 'cancelled';
}

export type ViewType = 'dashboard' | 'services' | 'bookings' | 'ai-assistant';

import { Service, Booking } from './types';

export const INITIAL_SERVICES: Service[] = [
  {
    id: '1',
    name: 'Corte de Cabelo Masculino',
    description: 'Corte clássico ou moderno com acabamento na navalha.',
    duration: 30,
    price: 45.00,
    category: 'Beleza'
  },
  {
    id: '2',
    name: 'Consultoria Financeira',
    description: 'Análise detalhada de gastos e planejamento de investimentos.',
    duration: 60,
    price: 250.00,
    category: 'Negócios'
  }
];

export const INITIAL_BOOKINGS: Booking[] = [
  {
    id: 'b1',
    serviceId: '1',
    clientName: 'João Silva',
    clientEmail: 'joao@email.com',
    date: new Date().toISOString().split('T')[0],
    time: '14:00',
    status: 'confirmed'
  }
];

export const CATEGORIES = ['Beleza', 'Negócios', 'Saúde', 'Educação', 'Limpeza', 'Outros'];

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateServiceDescription = async (serviceName: string, category: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Gere uma descrição curta e atraente para um serviço chamado "${serviceName}" na categoria "${category}". Foque nos benefícios para o cliente.`,
      config: {
        temperature: 0.7,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    return "Não foi possível gerar a descrição automaticamente no momento.";
  }
};

export const suggestPricing = async (serviceName: string, duration: number) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Dê uma sugestão de preço (em Reais R$) para um serviço de "${serviceName}" que dura ${duration} minutos. Retorne apenas o valor numérico médio estimado para o mercado brasileiro atual.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedPrice: { type: Type.NUMBER }
          },
          required: ["suggestedPrice"]
        }
      }
    });
    const data = JSON.parse(response.text || '{"suggestedPrice": 0}');
    return data.suggestedPrice;
  } catch (error) {
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X
} from 'lucide-react';
import { Service, Booking, ViewType } from './types';
import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES } from './constants';
import { generateServiceDescription, suggestPricing } from './geminiService';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [bookings, setBookings] = useState<Booking[]>(INITIAL_BOOKINGS);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Stats
  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const upcomingBookings = bookings.filter(b => new Date(b.date) >= new Date() && b.status !== 'cancelled');

  const addService = (newService: Service) => {
    setServices([...services, newService]);
  };

  const deleteService = (id: string) => {
    setServices(services.filter(s => s.id !== id));
  };

  const addBooking = (newBooking: Booking) => {
    setBookings([...bookings, newBooking]);
  };

  const cancelBooking = (id: string) => {
    setBookings(bookings.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out
        lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 px-2">
            <div className="p-2 bg-indigo-600 rounded-lg text-white">
              <CalendarDays size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-900">Agendai</h1>
          </div>

          <nav className="flex-1 space-y-1">
            <SidebarLink 
              icon={<LayoutDashboard size={20} />} 
              label="Dashboard" 
              active={activeView === 'dashboard'} 
              onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<Scissors size={20} />} 
              label="Serviços" 
              active={activeView === 'services'} 
              onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<CalendarDays size={20} />} 
              label="Agendamentos" 
              active={activeView === 'bookings'} 
              onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<Sparkles size={20} />} 
              label="Assistente IA" 
              active={activeView === 'ai-assistant'} 
              onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} 
            />
          </nav>

          <div className="mt-auto p-4 bg-slate-50 rounded-xl">
            <p className="text-xs text-slate-500 font-medium uppercase mb-2 tracking-wider">Status da Conta</p>
            <div className="flex items-center gap-3">
              <div className="w-2 h-2 rounded-full bg-green-500" />
              <span className="text-sm font-semibold text-slate-700">Plano Pro Ativo</span>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-slate-200 shrink-0">
          <button 
            className="lg:hidden p-2 hover:bg-slate-100 rounded-lg"
            onClick={() => setIsSidebarOpen(true)}
          >
            <Menu size={24} />
          </button>

          <div className="flex-1 max-w-xl mx-4 relative hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar agendamentos ou serviços..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-bold text-slate-900">Admin Agendai</p>
              <p className="text-xs text-slate-500">Gestor de Serviços</p>
            </div>
            <img 
              src="https://picsum.photos/seed/user/40/40" 
              alt="Avatar" 
              className="w-10 h-10 rounded-full border border-slate-200"
            />
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={totalRevenue} 
              upcomingCount={upcomingBookings.length}
              recentBookings={bookings.slice(-5).reverse()}
              services={services}
            />
          )}
          {activeView === 'services' && (
            <ServicesView 
              services={services} 
              onAdd={addService} 
              onDelete={deleteService} 
            />
          )}
          {activeView === 'bookings' && (
            <BookingsView 
              bookings={bookings} 
              services={services} 
              onAdd={addBooking} 
              onCancel={cancelBooking} 
            />
          )}
          {activeView === 'ai-assistant' && (
            <AIAssistantView services={services} setServices={setServices} />
          )}
        </div>
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ 
  icon: React.ReactNode; 
  label: string; 
  active?: boolean; 
  onClick: () => void 
}> = ({ icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`
      w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all text-sm font-medium
      ${active 
        ? 'bg-indigo-50 text-indigo-700' 
        : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'}
    `}
  >
    <span className={`${active ? 'text-indigo-600' : 'text-slate-400'}`}>{icon}</span>
    {label}
  </button>
);

// --- VIEW COMPONENTS ---

const DashboardView: React.FC<{ 
  revenue: number; 
  upcomingCount: number; 
  recentBookings: Booking[];
  services: Service[];
}> = ({ revenue, upcomingCount, recentBookings, services }) => (
  <div className="space-y-6 max-w-6xl mx-auto">
    <div className="flex items-center justify-between">
      <h2 className="text-2xl font-bold text-slate-900">Visão Geral</h2>
      <div className="flex gap-2">
        <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold text-slate-500">Hoje</span>
      </div>
    </div>

    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
      <StatCard 
        label="Receita Confirmada" 
        value={`R$ ${revenue.toFixed(2)}`} 
        icon={<DollarSign className="text-emerald-600" size={24} />} 
        color="emerald" 
      />
      <StatCard 
        label="Agendamentos Pendentes" 
        value={upcomingCount.toString()} 
        icon={<Clock className="text-amber-600" size={24} />} 
        color="amber" 
      />
      <StatCard 
        label="Total de Serviços" 
        value={services.length.toString()} 
        icon={<Scissors className="text-indigo-600" size={24} />} 
        color="indigo" 
      />
    </div>

    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <h3 className="font-bold text-slate-900 mb-4">Agendamentos Recentes</h3>
        <div className="space-y-4">
          {recentBookings.length === 0 ? (
            <p className="text-slate-500 text-sm">Nenhum agendamento registrado.</p>
          ) : (
            recentBookings.map(booking => {
              const service = services.find(s => s.id === booking.serviceId);
              return (
                <div key={booking.id} className="flex items-center justify-between p-3 rounded-xl bg-slate-50 border border-slate-100">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-white flex items-center justify-center border border-slate-200 font-bold text-indigo-600">
                      {booking.clientName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-slate-900">{booking.clientName}</p>
                      <p className="text-xs text-slate-500">{service?.name} • {booking.time}</p>
                    </div>
                  </div>
                  <span className={`
                    px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider
                    ${booking.status === 'confirmed' ? 'bg-green-100 text-green-700' : 
                      booking.status === 'cancelled' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}
                  `}>
                    {booking.status}
                  </span>
                </div>
              );
            })
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
        <div className="p-4 bg-indigo-100 rounded-full text-indigo-600 mb-4">
          <Sparkles size={32} />
        </div>
        <h3 className="font-bold text-slate-900 mb-2">Dica da IA</h3>
        <p className="text-sm text-slate-600 max-w-xs">
          "Você tem muitos horários vagos nas terças de manhã. Que tal criar uma promoção para esses períodos?"
        </p>
        <button className="mt-6 px-4 py-2 bg-indigo-600 text-white text-sm font-semibold rounded-lg hover:bg-indigo-700 transition-colors">
          Gerar Campanha
        </button>
      </div>
    </div>
  </div>
);

const StatCard: React.FC<{ label: string; value: string; icon: React.ReactNode; color: string }> = ({ label, value, icon }) => (
  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
    <div className="flex items-start justify-between">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{label}</p>
        <h4 className="text-2xl font-bold text-slate-900">{value}</h4>
      </div>
      <div className="p-3 bg-slate-50 rounded-xl">
        {icon}
      </div>
    </div>
  </div>
);

const ServicesView: React.FC<{ 
  services: Service[]; 
  onAdd: (s: Service) => void; 
  onDelete: (id: string) => void;
}> = ({ services, onAdd, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newService, setNewService] = useState<Partial<Service>>({
    name: '',
    category: CATEGORIES[0],
    duration: 30,
    price: 0,
    description: ''
  });
  const [isLoadingAI, setIsLoadingAI] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newService.name && newService.category) {
      onAdd({
        ...newService,
        id: Date.now().toString(),
      } as Service);
      setIsModalOpen(false);
      setNewService({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
    }
  };

  const handleSuggestAI = async () => {
    if (!newService.name) return;
    setIsLoadingAI(true);
    const desc = await generateServiceDescription(newService.name, newService.category || '');
    const price = await suggestPricing(newService.name, newService.duration || 30);
    setNewService(prev => ({ 
      ...prev, 
      description: desc,
      price: price || prev.price
    }));
    setIsLoadingAI(false);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Catálogo de Serviços</h2>
          <p className="text-slate-500 text-sm">Gerencie o que você oferece aos seus clientes.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold"
        >
          <Plus size={20} /> Adicionar Serviço
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {services.map(service => (
          <div key={service.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow group">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <span className="px-2 py-1 bg-indigo-50 text-indigo-700 text-[10px] font-bold uppercase rounded tracking-wider">
                  {service.category}
                </span>
                <button 
                  onClick={() => onDelete(service.id)}
                  className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 size={18} />
                </button>
              </div>
              <h3 className="text-lg font-bold text-slate-900 mb-1">{service.name}</h3>
              <p className="text-sm text-slate-500 line-clamp-2 mb-4 h-10">{service.description}</p>

              <div className="flex items-center gap-4 text-sm font-medium text-slate-700">
                <div className="flex items-center gap-1">
                  <Clock size={16} className="text-slate-400" />
                  <span>{service.duration} min</span>
                </div>
                <div className="flex items-center gap-1">
                  <DollarSign size={16} className="text-slate-400" />
                  <span>R$ {service.price.toFixed(2)}</span>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 px-6 py-3 border-t border-slate-100 flex justify-between items-center">
              <button className="text-indigo-600 text-sm font-semibold hover:text-indigo-800">Editar Detalhes</button>
              <ChevronRight size={18} className="text-slate-400" />
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
              <h3 className="text-xl font-bold text-slate-900">Novo Serviço</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Nome do Serviço</label>
                  <input 
                    type="text" 
                    required 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    value={newService.name}
                    onChange={e => setNewService({...newService, name: e.target.value})}
                    placeholder="Ex: Corte Degradê"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Categoria</label>
                  <select 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    value={newService.category}
                    onChange={e => setNewService({...newService, category: e.target.value})}
                  >
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Duração (min)</label>
                  <input 
                    type="number" 
                    required 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    value={newService.duration}
                    onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Preço (R$)</label>
                  <input 
                    type="number" 
                    step="0.01"
                    required 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                    value={newService.price}
                    onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-bold text-slate-500 uppercase">Descrição</label>
                  <button 
                    type="button"
                    onClick={handleSuggestAI}
                    disabled={isLoadingAI || !newService.name}
                    className="text-xs flex items-center gap-1 text-indigo-600 font-bold hover:text-indigo-800 disabled:opacity-50"
                  >
                    <Sparkles size={12} /> {isLoadingAI ? 'Gerando...' : 'Sugerir com IA'}
                  </button>
                </div>
                <textarea 
                  className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none h-24 resize-none"
                  value={newService.description}
                  onChange={e => setNewService({...newService, description: e.target.value})}
                  placeholder="Fale um pouco sobre o serviço..."
                />
              </div>
              <div className="pt-4 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 font-semibold"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-semibold"
                >
                  Criar Serviço
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const BookingsView: React.FC<{
  bookings: Booking[];
  services: Service[];
  onAdd: (b: Booking) => void;
  onCancel: (id: string) => void;
}> = ({ bookings, services, onAdd, onCancel }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [form, setForm] = useState({
    clientName: '',
    clientEmail: '',
    serviceId: services[0]?.id || '',
    date: new Date().toISOString().split('T')[0],
    time: '09:00'
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({
      ...form,
      id: `b${Date.now()}`,
      status: 'confirmed'
    });
    setIsModalOpen(false);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Agenda</h2>
          <p className="text-slate-500 text-sm">Visualize e gerencie todos os compromissos marcados.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold"
        >
          <Plus size={20} /> Novo Agendamento
        </button>
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
