import { GoogleGenAI, Type } from "@google/genai";

// Initialize the Google GenAI SDK with the API key from environment variables.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Function to generate a service description using the Gemini 3 Flash model.
export const generateServiceDescription = async (serviceName: string, category: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Gere uma descrição curta e atraente para um serviço chamado "${serviceName}" na categoria "${category}". Foque nos benefícios para o cliente.`,
      config: {
        temperature: 0.7,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    return "Não foi possível gerar a descrição automaticamente no momento.";
  }
};

// Function to suggest pricing for a service based on market trends.
export const suggestPricing = async (serviceName: string, duration: number) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Dê uma sugestão de preço (em Reais R$) para um serviço de "${serviceName}" que dura ${duration} minutos. Retorne apenas o valor numérico médio estimado para o mercado brasileiro atual.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedPrice: { type: Type.NUMBER }
          },
          required: ["suggestedPrice"]
        }
      }
    });
    // Extract the text safely and parse the JSON response.
    const jsonStr = response.text?.trim() || '{"suggestedPrice": 0}';
    const data = JSON.parse(jsonStr);
    return data.suggestedPrice;
  } catch (error) {
    console.error("Error suggesting price:", error);
    return null;
  }
};

// Function to consult the expert assistant on business management tasks.
export const askExpertAssistant = async (prompt: string, serviceNames: string[]) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Atue como um especialista em gestão de negócios. Com base no catálogo atual de serviços (${JSON.stringify(serviceNames)}), responda à seguinte dúvida/pedido: "${prompt}". Seja prático e direto.`
    });
    return response.text;
  } catch (error) {
    console.error("Error consulting AI assistant:", error);
    throw error;
  }
};

