const AIAssistantView: React.FC<{ 
  services: Service[]; 
  setServices: React.Dispatch<React.SetStateAction<Service[]>>;
}> = ({ services, setServices }) => {
  const [prompt, setPrompt] = useState("");
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState<string | null>(null);

  const handleAskAI = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      // Use the askExpertAssistant function from the geminiService to handle the AI logic.
      const responseText = await askExpertAssistant(prompt, services.map(s => s.name));
      setSuggestion(responseText || "Não foi possível gerar uma sugestão no momento.");
    } catch (error) {
      setSuggestion("Erro ao consultar a IA. Verifique sua conexão ou tente mais tarde.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="text-center space-y-2 mb-10">
        <div className="inline-flex p-4 bg-indigo-100 rounded-full text-indigo-600 mb-2">
