        <div className="space-y-2">
          <label className="text-sm font-bold text-slate-700">O que você deseja fazer?</label>
          <div className="relative">
            <textarea 
              className="w-full p-4 pr-12 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-100 outline-none min-h-[120px] resize-none text-slate-700 leading-relaxed"
              placeholder="Ex: Sugira 3 novos serviços de beleza para o verão com preços sugeridos..."
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
            />
            <button 
              onClick={handleAskAI}
