            >
              {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
            </button>
          </div>
        </div>

        {suggestion && (
          <div className="p-6 bg-slate-50 border border-slate-100 rounded-2xl animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-2 text-indigo-600 font-bold mb-3 text-sm">
              <Sparkles size={16} /> Resposta do Especialista
            </div>
            <div className="prose prose-slate max-w-none text-slate-600 leading-relaxed text-sm whitespace-pre-wrap">
              {suggestion}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <PromptSuggestion label="Sugerir Promoção Mensal" onClick={() => setPrompt("Sugira uma promoção atrativa para os meus serviços atuais este mês.")} />
          <PromptSuggestion label="Ideias de Novos Serviços" onClick={() => setPrompt("Com base no que eu já ofereço, quais 2 novos serviços complementares eu poderia adicionar?")} />
          <PromptSuggestion label="Otimizar Preços" onClick={() => setPrompt("Analise meus preços atuais e sugira reajustes com base no mercado de serviços premium.")} />
