const ServicesView: React.FC<{ 
  services: Service[]; 
  onAdd: (s: Service) => void; 
  onDelete: (id: string) => void;
}> = ({ services, onAdd, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newService, setNewService] = useState<Partial<Service>>({
    name: '',
    category: CATEGORIES[0],
    duration: 30,
    price: 0,
    description: ''
  });
  const [isLoadingAI, setIsLoadingAI] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newService.name && newService.category) {
      onAdd({
        ...newService,
        id: Date.now().toString(),
      } as Service);
      setIsModalOpen(false);
      setNewService({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
    }
  };

  const handleSuggestAI = async () => {
    if (!newService.name) return;
    setIsLoadingAI(true);
    const desc = await generateServiceDescription(newService.name, newService.category || '');
    const price = await suggestPricing(newService.name, newService.duration || 30);
    setNewService(prev => ({ 
      ...prev, 
      description: desc,
      price: price || prev.price
    }));
    setIsLoadingAI(false);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Catálogo Barber</h2>
          <p className="text-slate-500 text-sm">Gerencie os cortes e tratamentos que você oferece.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-amber-500 text-slate-950 rounded-lg hover:bg-amber-400 transition-colors font-black text-xs uppercase tracking-widest"
        >
          <Plus size={18} /> Adicionar Serviço
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {services.map(service => (
          <div key={service.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow group">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <span className="px-2 py-1 bg-amber-50 text-amber-700 text-[10px] font-black uppercase rounded tracking-wider border border-amber-100">
                  {service.category}
                </span>
                <button 
                  onClick={() => onDelete(service.id)}
                  className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 size={18} />
                </button>
              </div>
              <h3 className="text-lg font-black text-slate-900 mb-1 group-hover:text-amber-600 transition-colors italic">{service.name}</h3>
              <p className="text-sm text-slate-500 line-clamp-2 mb-4 h-10 leading-relaxed">{service.description}</p>

              <div className="flex items-center gap-4 text-xs font-bold text-slate-700 uppercase tracking-widest">
                <div className="flex items-center gap-1">
                  <Clock size={14} className="text-amber-500" />
                  <span>{service.duration} MIN</span>
                </div>
                <div className="flex items-center gap-1">
                  <DollarSign size={14} className="text-amber-500" />
                  <span>R$ {service.price.toFixed(2)}</span>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 px-6 py-3 border-t border-slate-100 flex justify-between items-center">
              <button className="text-amber-600 text-xs font-black uppercase tracking-widest hover:text-amber-800">Editar</button>
              <ChevronRight size={18} className="text-slate-300" />
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-900">
              <h3 className="text-xl font-black text-white italic">Novo Serviço <span className="text-amber-500">Barber</span></h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome do Serviço</label>
                  <input 
                    type="text" required 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-amber-500"
                    value={newService.name}
                    onChange={e => setNewService({...newService, name: e.target.value})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Categoria</label>
                  <select 
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-amber-500"
                    value={newService.category}
                    onChange={e => setNewService({...newService, category: e.target.value})}
                  >
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Duração (min)</label>
                  <input type="number" required className="w-full px-4 py-2 border border-slate-200 rounded-lg" value={newService.duration} onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})} />
                </div>
                <div className="space-y-1 col-span-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preço Sugerido (R$)</label>
                  <input type="number" step="0.01" required className="w-full px-4 py-2 border border-slate-200 rounded-lg" value={newService.price} onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})} />
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descrição Comercial</label>
                  <button type="button" onClick={handleSuggestAI} disabled={isLoadingAI || !newService.name} className="text-[10px] flex items-center gap-1 text-amber-600 font-black uppercase hover:text-amber-800 disabled:opacity-50">
                    <Sparkles size={12} /> {isLoadingAI ? 'Criando...' : 'IA Criar Texto'}
                  </button>
                </div>
                <textarea className="w-full px-4 py-2 border border-slate-200 rounded-lg min-h-[100px] resize-none" value={newService.description} onChange={e => setNewService({...newService, description: e.target.value})} />
              </div>
              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2 bg-slate-100 text-slate-600 rounded-lg font-bold text-xs uppercase">Cancelar</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-slate-900 text-white rounded-lg font-black text-xs uppercase tracking-widest hover:bg-slate-800">Salvar Serviço</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

