const AIAssistantView: React.FC<{ 
  services: Service[]; 
  setServices: React.Dispatch<React.SetStateAction<Service[]>>;
}> = ({ services, setServices }) => {
  const [prompt, setPrompt] = useState("");
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState<string | null>(null);

  const handleAskAI = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const responseText = await askExpertAssistant(prompt, services.map(s => s.name));
      setSuggestion(responseText || "Não foi possível gerar uma sugestão no momento.");
    } catch (error) {
      setSuggestion("Erro ao consultar a IA da Barbearia.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="text-center space-y-2 mb-10">
        <div className="inline-flex p-4 bg-slate-900 rounded-full text-amber-500 mb-2 border-2 border-amber-500 shadow-xl shadow-amber-500/10">
          <Sparkles size={40} />
        </div>
        <h2 className="text-3xl font-black text-slate-900 italic">ASSISTENTE <span className="text-amber-500 uppercase tracking-tighter">BARBER MARKETING</span></h2>
        <p className="text-slate-500 text-sm uppercase tracking-widest font-bold">Crie promoções, textos para instagram e novos combos com IA.</p>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-xl space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">O que você precisa hoje?</label>
          <div className="relative">
            <textarea 
              className="w-full p-6 pr-14 border border-slate-100 bg-slate-50 rounded-2xl focus:ring-4 focus:ring-amber-100 outline-none min-h-[140px] resize-none text-slate-900 font-medium leading-relaxed"
              placeholder="Ex: Crie um texto de promoção para o dia dos pais oferecendo Barba Terapia..."
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
            />
            <button onClick={handleAskAI} disabled={loading || !prompt} className="absolute bottom-6 right-6 p-4 bg-slate-900 text-amber-500 rounded-xl hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50">
              {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
            </button>
          </div>
        </div>

        {suggestion && (
          <div className="p-8 bg-slate-900 text-white rounded-2xl border-l-4 border-amber-500 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-2 text-amber-500 font-black mb-4 text-xs uppercase tracking-widest">
              <Sparkles size={16} /> Resposta do Consultor Barber
            </div>
            <div className="prose prose-invert max-w-none text-slate-300 leading-relaxed text-sm whitespace-pre-wrap font-medium italic">
              {suggestion}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <PromptSuggestion label="Promoção 'Tapa no Visual'" onClick={() => setPrompt("Crie uma promoção de combo Cabelo + Barba para dias de pouco movimento (segunda e terça).")} />
          <PromptSuggestion label="Script de Instagram Reels" onClick={() => setPrompt("Me dê 3 ideias de temas para gravar Reels mostrando os cortes da barbearia.")} />
          <PromptSuggestion label="Texto Boas-vindas WhatsApp" onClick={() => setPrompt("Crie uma mensagem automática amigável para enviar para clientes que agendaram pela primeira vez.")} />
          <PromptSuggestion label="Sugestão de Combo de Natal" onClick={() => setPrompt("Sugira um combo especial de final de ano que inclua um produto para levar para casa.")} />
        </div>
      </div>
    </div>
  );
};

