              placeholder="Ex: Crie um texto de promoção para o dia dos pais oferecendo Barba Terapia..."
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
            />
            <button onClick={handleAskAI} disabled={loading || !prompt} className="absolute bottom-6 right-6 p-4 bg-slate-900 text-amber-500 rounded-xl hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50">
              {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
            </button>
          </div>
        </div>

        {suggestion && (
          <div className="p-8 bg-slate-900 text-white rounded-2xl border-l-4 border-amber-500 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-2 text-amber-500 font-black mb-4 text-xs uppercase tracking-widest">
              <Sparkles size={16} /> Resposta do Consultor Barber
            </div>
            <div className="prose prose-invert max-w-none text-slate-300 leading-relaxed text-sm whitespace-pre-wrap font-medium italic">
              {suggestion}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <PromptSuggestion label="Promoção 'Tapa no Visual'" onClick={() => setPrompt("Crie uma promoção de combo Cabelo + Barba para dias de pouco movimento (segunda e terça).")} />
          <PromptSuggestion label="Script de Instagram Reels" onClick={() => setPrompt("Me dê 3 ideias de temas para gravar Reels mostrando os cortes da barbearia.")} />
          <PromptSuggestion label="Texto Boas-vindas WhatsApp" onClick={() => setPrompt("Crie uma mensagem automática amigável para enviar para clientes que agendaram pela primeira vez.")} />
          <PromptSuggestion label="Sugestão de Combo de Natal" onClick={() => setPrompt("Sugira um combo especial de final de ano que inclua um produto para levar para casa.")} />
        </div>
      </div>
    </div>
  );
};

const PromptSuggestion: React.FC<{ label: string; onClick: () => void }> = ({ label, onClick }) => (
  <button 
    onClick={onClick}
    className="px-4 py-3 text-left bg-white border border-slate-100 rounded-xl text-[10px] font-black text-slate-600 uppercase tracking-widest hover:border-amber-300 hover:bg-amber-50 hover:text-amber-700 transition-all flex items-center justify-between group"
  >
    {label}
    <Plus size={14} className="text-slate-300 group-hover:text-amber-400" />
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X,
  ArrowLeft,
  Edit2,
  Check,
  XCircle
} from 'lucide-react';
import { Service, Booking, ViewType } from './types';
import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES } from './constants';
import { generateServiceDescription, suggestPricing, askExpertAssistant } from './geminiService';
import LandingPage from './LandingPage';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [bookings, setBookings] = useState<Booking[]>(INITIAL_BOOKINGS);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Stats
  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const upcomingBookings = bookings.filter(b => new Date(b.date) >= new Date() && b.status !== 'cancelled');

  const addService = (newService: Service) => {
    setServices(prev => [...prev, newService]);
  };

  const updateService = (updatedService: Service) => {
    setServices(prev => prev.map(s => s.id === updatedService.id ? updatedService : s));
  };

  const deleteService = (id: string) => {
    if (window.confirm("Tem certeza que deseja excluir este serviço do catálogo?")) {
      setServices(prev => prev.filter(s => s.id !== id));
    }
  };

  const addBooking = (newBooking: Booking) => {
    setBookings(prev => [...prev, newBooking]);
    // Only redirect if it was from the client-booking view
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert("Agendamento realizado com sucesso! Aguardamos você.");
    }
  };

  const updateBooking = (updatedBooking: Booking) => {
    setBookings(prev => prev.map(b => b.id === updatedBooking.id ? updatedBooking : b));
  };

  const deleteBooking = (id: string) => {
    if (window.confirm("Tem certeza que deseja remover este agendamento permanentemente?")) {
      setBookings(prev => prev.filter(b => b.id !== id));
    }
  };

  const confirmBooking = (id: string) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'confirmed' } : b));
  };

  const cancelBooking = (id: string) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));
  };

  // Views switch
  if (activeView === 'landing') {
    return (
      <LandingPage 
        services={services} 
        onBookNow={() => setActiveView('client-booking')} 
        onAdminAccess={() => setActiveView('dashboard')}
      />
    );
  }

  if (activeView === 'client-booking') {
    return (
      <div className="bg-slate-950 min-h-screen flex items-center justify-center p-6">
        <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
          <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-400 hover:text-amber-500 mb-8 font-bold text-sm transition-colors">
            <ArrowLeft size={18} /> VOLTAR PARA O INÍCIO
          </button>
          <h2 className="text-3xl font-black text-white mb-2 italic">AGENDE SEU <span className="text-amber-500">HORÁRIO</span></h2>
          <p className="text-slate-400 text-sm mb-8">Preencha os dados abaixo e escolha seu serviço.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const formData = new FormData(e.currentTarget);
            addBooking({
              id: `b${Date.now()}`,
              clientName: formData.get('name') as string,
              clientEmail: formData.get('email') as string,
              serviceId: formData.get('service') as string,
              date: formData.get('date') as string,
              time: formData.get('time') as string,
              status: 'pending'
            });
          }} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input name="name" type="text" placeholder="Seu nome completo" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
              <input name="email" type="email" placeholder="Seu melhor e-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
            </div>
            <select name="service" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all appearance-none">
              {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price}</option>)}
            </select>
            <div className="grid grid-cols-2 gap-4">
              <input name="date" type="date" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
              <input name="time" type="time" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
            </div>
            <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all shadow-lg shadow-amber-500/10">
              CONFIRMAR AGENDAMENTO
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out
        lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 px-2 cursor-pointer" onClick={() => setActiveView('landing')}>
            <div className="p-2 bg-amber-500 rounded-lg text-slate-950">
              <Scissors size={24} />
            </div>
            <h1 className="text-xl font-black italic tracking-tighter text-slate-900">BARBER<span className="text-amber-500">PRO</span></h1>
          </div>

          <nav className="flex-1 space-y-1">
            <SidebarLink 
              icon={<LayoutDashboard size={20} />} 
              label="Dashboard" 
              active={activeView === 'dashboard'} 
              onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<Scissors size={20} />} 
              label="Serviços" 
              active={activeView === 'services'} 
              onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<CalendarDays size={20} />} 
              label="Agenda Admin" 
              active={activeView === 'bookings'} 
              onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} 
            />
            <SidebarLink 
              icon={<Sparkles size={20} />} 
              label="Assistente IA" 
              active={activeView === 'ai-assistant'} 
              onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} 
            />
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-100">
             <button onClick={() => setActiveView('landing')} className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:text-slate-600 font-bold text-xs uppercase transition-colors">
                <ArrowLeft size={16} /> Voltar para o Site
             </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-slate-200 shrink-0">
          <button 
            className="lg:hidden p-2 hover:bg-slate-100 rounded-lg"
            onClick={() => setIsSidebarOpen(true)}
          >
            <Menu size={24} />
          </button>

          <div className="flex-1 max-w-xl mx-4 relative hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar clientes..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-amber-500 transition-all outline-none"
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-bold text-slate-900">Admin Barbearia</p>
              <p className="text-xs text-slate-500">Gestor de Agendamentos</p>
            </div>
            <img 
              src="https://picsum.photos/seed/barber/40/40" 
              alt="Avatar" 
              className="w-10 h-10 rounded-full border-2 border-amber-500"
            />
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={totalRevenue} 
              upcomingCount={upcomingBookings.length}
              recentBookings={bookings.slice(-5).reverse()}
              services={services}
            />
          )}
          {activeView === 'services' && (
            <ServicesView 
              services={services} 
              onAdd={addService} 
              onEdit={updateService}
              onDelete={deleteService} 
            />
          )}
          {activeView === 'bookings' && (
            <BookingsView 
              bookings={bookings} 
              services={services} 
              onAdd={addBooking} 
              onEdit={updateBooking}
              onDelete={deleteBooking}
              onConfirm={confirmBooking}
              onCancel={cancelBooking} 
            />
          )}
          {activeView === 'ai-assistant' && (
            <AIAssistantView services={services} setServices={setServices} />
          )}
        </div>
      </main>
    </div>
  );
};

