      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-xl space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">O que você precisa hoje?</label>
          <div className="relative">
            <textarea 
              className="w-full p-6 pr-14 border border-slate-100 bg-slate-50 rounded-2xl focus:ring-4 focus:ring-amber-100 outline-none min-h-[140px] resize-none text-slate-900 font-medium leading-relaxed"
              placeholder="Ex: Crie um texto de promoção para o dia dos pais oferecendo Barba Terapia..."
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
