              {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
            </button>
          </div>
        </div>

        {suggestion && (
          <div className="p-8 bg-slate-900 text-white rounded-2xl border-l-4 border-amber-500 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center gap-2 text-amber-500 font-black mb-4 text-xs uppercase tracking-widest">
              <Sparkles size={16} /> Resposta do Consultor Barber
            </div>
            <div className="prose prose-invert max-w-none text-slate-300 leading-relaxed text-sm whitespace-pre-wrap font-medium italic">
              {suggestion}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <PromptSuggestion label="Promoção 'Tapa no Visual'" onClick={() => setPrompt("Crie uma promoção de combo Cabelo + Barba para dias de pouco movimento (segunda e terça).")} />
          <PromptSuggestion label="Script de Instagram Reels" onClick={() => setPrompt("Me dê 3 ideias de temas para gravar Reels mostrando os cortes da barbearia.")} />
          <PromptSuggestion label="Texto Boas-vindas WhatsApp" onClick={() => setPrompt("Crie uma mensagem automática amigável para enviar para clientes que agendaram pela primeira vez.")} />
