      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-xl space-y-6">
        <div className="relative">
          <textarea className="w-full p-5 pr-14 border border-slate-100 bg-slate-50 rounded-2xl focus:ring-4 focus:ring-amber-100 outline-none min-h-[140px] resize-none text-slate-900 font-medium text-sm md:text-base" placeholder="Ex: Crie um texto de promoção para o final de semana..." value={prompt} onChange={e => setPrompt(e.target.value)} />
          <button onClick={handleAskAI} disabled={loading || !prompt} className="absolute bottom-5 right-5 p-3 bg-slate-900 text-amber-500 rounded-xl hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50">
