// Iniciamos com a lista de agendamentos vazia, removendo os dados fictícios
export const INITIAL_BOOKINGS: Booking[] = [];

export const CATEGORIES = ['Cabelo', 'Barba', 'Combos', 'Estética', 'Infantil', 'Outros'];

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X,
  ArrowLeft,
  Edit2,
  Check,
  XCircle,
  Mail,
  User,
  Calendar
} from 'lucide-react';
import { Service, Booking, ViewType } from './types';
import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES } from './constants';
import { generateServiceDescription, suggestPricing, askExpertAssistant } from './geminiService';
import LandingPage from './LandingPage';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');

  // Inicialização de estado carregando do localStorage (nosso "banco de dados" local)
  const [services, setServices] = useState<Service[]>(() => {
    const saved = localStorage.getItem('barberpro_services');
    return saved ? JSON.parse(saved) : INITIAL_SERVICES;
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    const saved = localStorage.getItem('barberpro_bookings');
    return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Efeito para persistir serviços sempre que houver mudanças
  useEffect(() => {
    localStorage.setItem('barberpro_services', JSON.stringify(services));
  }, [services]);

  // Efeito para persistir agendamentos sempre que houver mudanças
  useEffect(() => {
    localStorage.setItem('barberpro_bookings', JSON.stringify(bookings));
  }, [bookings]);

  // Stats
  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const upcomingBookings = bookings.filter(b => {
    const bookingDate = new Date(b.date);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return bookingDate >= today && b.status !== 'cancelled';
  });

  const addService = (newService: Service) => {
    setServices(prev => [...prev, newService]);
  };

  const updateService = (updatedService: Service) => {
    setServices(prev => prev.map(s => s.id === updatedService.id ? updatedService : s));
  };

  const deleteService = (id: string) => {
    if (window.confirm("Tem certeza que deseja excluir este serviço do catálogo?")) {
      setServices(prev => prev.filter(s => s.id !== id));
    }
  };

  const addBooking = (newBooking: Booking) => {
    setBookings(prev => [...prev, newBooking]);
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert("Agendamento realizado com sucesso! Aguardamos você.");
    }
  };

  const updateBooking = (updatedBooking: Booking) => {
    setBookings(prev => prev.map(b => b.id === updatedBooking.id ? updatedBooking : b));
  };

  const deleteBooking = (id: string) => {
    if (window.confirm("Tem certeza que deseja remover este agendamento permanentemente?")) {
      setBookings(prev => prev.filter(b => b.id !== id));
    }
  };

  const confirmBooking = (id: string) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'confirmed' } : b));
  };

  const cancelBooking = (id: string) => {
    if (window.confirm("Deseja realmente cancelar este agendamento?")) {
      setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));
    }
  };

  if (activeView === 'landing') {
    return (
      <LandingPage 
        services={services} 
        onBookNow={() => setActiveView('client-booking')} 
        onAdminAccess={() => setActiveView('dashboard')}
      />
    );
  }

  if (activeView === 'client-booking') {
    return (
      <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4 md:p-6">
        <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-2xl md:rounded-3xl p-6 md:p-8 shadow-2xl">
          <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-400 hover:text-amber-500 mb-6 md:mb-8 font-bold text-xs md:text-sm transition-colors">
            <ArrowLeft size={18} /> VOLTAR PARA O INÍCIO
          </button>
          <h2 className="text-2xl md:text-3xl font-black text-white mb-2 italic">AGENDE SEU <span className="text-amber-500 uppercase">Horário</span></h2>
          <p className="text-slate-400 text-xs md:text-sm mb-6 md:mb-8">Escolha o serviço e a melhor data para você.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const formData = new FormData(e.currentTarget);
            addBooking({
              id: `b${Date.now()}`,
              clientName: formData.get('name') as string,
              clientEmail: formData.get('email') as string,
              serviceId: formData.get('service') as string,
              date: formData.get('date') as string,
              time: formData.get('time') as string,
              status: 'pending'
            });
          }} className="space-y-4">
            <input name="name" type="text" placeholder="Seu nome" required className="w-full bg-slate-800 border border-slate-700 text-white p-3 md:p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
            <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-3 md:p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
            <select name="service" required className="w-full bg-slate-800 border border-slate-700 text-white p-3 md:p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 appearance-none transition-all">
              {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
            </select>
            <div className="grid grid-cols-2 gap-4">
              <input name="date" type="date" required className="w-full bg-slate-800 border border-slate-700 text-white p-3 md:p-4 rounded-xl outline-none transition-all" />
              <input name="time" type="time" required className="w-full bg-slate-800 border border-slate-700 text-white p-3 md:p-4 rounded-xl outline-none transition-all" />
            </div>
            <button type="submit" className="w-full py-4 md:py-5 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all text-sm md:text-base shadow-xl shadow-amber-500/10">
              CONFIRMAR AGENDAMENTO
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out
        lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-lg text-slate-950"><Scissors size={20} /></div>
              <h1 className="text-lg font-black italic text-slate-900">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button className="lg:hidden" onClick={() => setIsSidebarOpen(false)}><X size={20} /></button>
          </div>

          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda Admin" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Sparkles size={20} />} label="Assistente IA" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-4 md:px-6 bg-white border-b border-slate-200 shrink-0">
          <button className="lg:hidden p-2 hover:bg-slate-100 rounded-lg" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="flex-1" />
          <div className="flex items-center gap-3">
            <div className="text-right hidden xs:block">
              <p className="text-xs font-bold text-slate-900">Admin</p>
            </div>
            <img src="https://picsum.photos/seed/barber/32/32" alt="Avatar" className="w-8 h-8 rounded-full border border-amber-500" />
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6">
          {activeView === 'dashboard' && <DashboardView revenue={totalRevenue} upcomingCount={upcomingBookings.length} recentBookings={bookings.slice(-5).reverse()} services={services} />}
          {activeView === 'services' && <ServicesView services={services} onAdd={addService} onEdit={updateService} onDelete={deleteService} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onAdd={addBooking} onEdit={updateBooking} onDelete={deleteBooking} onConfirm={confirmBooking} onCancel={cancelBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} setServices={setServices} />}
        </div>
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ icon: React.ReactNode; label: string; active?: boolean; onClick: () => void }> = ({ icon, label, active, onClick }) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all text-sm font-bold ${active ? 'bg-amber-500 text-slate-950' : 'text-slate-600 hover:bg-slate-50'}`}>
    {icon} {label}
  </button>
);

const DashboardView: React.FC<{ revenue: number; upcomingCount: number; recentBookings: Booking[]; services: Service[]; }> = ({ revenue, upcomingCount, recentBookings, services }) => (
  <div className="space-y-6 max-w-6xl mx-auto">
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
      <StatCard label="Receita Confirmada" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={20} />} />
      <StatCard label="Próximos Cortes" value={upcomingCount.toString()} icon={<Clock size={20} />} />
      <StatCard label="Total de Serviços" value={services.length.toString()} icon={<Scissors size={20} />} />
    </div>
    <div className="bg-white p-6 rounded-2xl border border-slate-200">
      <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-4">Agendamentos Recentes</h3>
      <div className="space-y-3">
        {recentBookings.length === 0 ? (
          <p className="text-slate-400 text-sm italic py-4">Nenhum agendamento registrado ainda.</p>
        ) : (
          recentBookings.map(b => (
            <div key={b.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
              <div className="flex flex-col">
                <span className="text-sm font-bold truncate pr-2">{b.clientName}</span>
                <span className="text-[10px] text-slate-400">{b.date.split('-').reverse().join('/')} às {b.time}</span>
              </div>
              <span className={`text-[10px] font-black uppercase px-2 py-1 rounded-full ${
                b.status === 'confirmed' ? 'bg-green-100 text-green-700' : 
                b.status === 'cancelled' ? 'bg-red-100 text-red-700' : 
                'bg-amber-100 text-amber-700'
              }`}>{b.status}</span>
            </div>
          ))
        )}
      </div>
    </div>
  </div>
);

const StatCard: React.FC<{ label: string; value: string; icon: React.ReactNode }> = ({ label, value, icon }) => (
  <div className="bg-white p-5 rounded-2xl border border-slate-200 flex justify-between items-center transition-all hover:shadow-md">
    <div><p className="text-[10px] font-black uppercase text-slate-400">{label}</p><h4 className="text-xl font-black italic">{value}</h4></div>
    <div className="p-2 bg-slate-50 rounded-lg text-amber-500">{icon}</div>
  </div>
);

const ServicesView: React.FC<{ services: Service[]; onAdd: (s: Service) => void; onEdit: (s: Service) => void; onDelete: (id: string) => void; }> = ({ services, onAdd, onEdit, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingService, setEditingService] = useState<Service | null>(null);
  const [formState, setFormState] = useState<Partial<Service>>({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
  const [isLoadingAI, setIsLoadingAI] = useState(false);

  useEffect(() => {
    if (editingService) setFormState(editingService);
    else setFormState({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
  }, [editingService, isModalOpen]);

  const handleSuggestAI = async () => {
    if (!formState.name) {
      alert("Por favor, digite o nome do serviço primeiro para a IA criar uma descrição.");
      return;
    }
    setIsLoadingAI(true);
    try {
      const desc = await generateServiceDescription(formState.name, formState.category || 'Geral');
      if (desc) {
        setFormState(prev => ({ ...prev, description: desc }));
      }
    } finally {
      setIsLoadingAI(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h2 className="text-xl font-black italic">CATÁLOGO <span className="text-amber-500">BARBER</span></h2>
        <button onClick={() => { setEditingService(null); setIsModalOpen(true); }} className="px-4 py-2 bg-slate-900 text-white rounded-lg font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 transition-all hover:bg-slate-800 shadow-lg">
          <Plus size={16} /> Adicionar Serviço
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {services.length === 0 ? (
          <p className="col-span-full text-center py-20 text-slate-400 italic">Nenhum serviço cadastrado.</p>
        ) : (
          services.map(s => (
            <div key={s.id} className="bg-white border border-slate-200 p-5 rounded-2xl shadow-sm hover:border-amber-500 transition-all group">
              <div className="flex justify-between items-start mb-3">
                <span className="text-[10px] font-black uppercase text-amber-600 bg-amber-50 px-2 py-1 rounded">{s.category}</span>
                <div className="flex gap-1">
                  <button onClick={() => { setEditingService(s); setIsModalOpen(true); }} className="p-1.5 text-slate-400 hover:text-amber-500 transition-colors"><Edit2 size={16} /></button>
                  <button onClick={() => onDelete(s.id)} className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"><Trash2 size={16} /></button>
                </div>
              </div>
              <h3 className="font-black italic mb-1 group-hover:text-amber-600 transition-colors">{s.name}</h3>
              <p className="text-xs text-slate-500 line-clamp-2 mb-4 h-8">{s.description}</p>
              <div className="flex justify-between items-center pt-3 border-t border-slate-50">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{s.duration} min</span>
                <span className="font-black text-amber-600">R$ {s.price.toFixed(2)}</span>
              </div>
            </div>
          ))
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-5 bg-slate-900 text-white flex justify-between items-center">
              <h3 className="font-black italic uppercase text-sm">{editingService ? 'Editar' : 'Novo'} Serviço</h3>
              <button onClick={() => setIsModalOpen(false)} className="hover:text-amber-500 transition-colors"><X size={20} /></button>
            </div>
            <form className="p-5 space-y-4" onSubmit={(e) => {
              e.preventDefault();
              if (editingService) onEdit({ ...formState, id: editingService.id } as Service);
              else onAdd({ ...formState, id: Date.now().toString() } as Service);
              setIsModalOpen(false);
            }}>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome do Serviço</label>
                <input value={formState.name} onChange={e => setFormState({...formState, name: e.target.value})} placeholder="Ex: Corte Degradê" required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preço (R$)</label>
                  <input type="number" step="0.01" value={formState.price} onChange={e => setFormState({...formState, price: parseFloat(e.target.value)})} placeholder="0.00" required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Duração (Min)</label>
                  <input type="number" value={formState.duration} onChange={e => setFormState({...formState, duration: parseInt(e.target.value)})} placeholder="30" required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex items-center justify-between mb-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descrição</label>
                  <button 
                    type="button" 
                    onClick={handleSuggestAI} 
                    disabled={isLoadingAI || !formState.name}
                    className="text-[10px] flex items-center gap-1 text-amber-600 font-black uppercase hover:text-amber-800 disabled:opacity-50 transition-colors"
                  >
                    <Sparkles size={12} /> {isLoadingAI ? 'Gerando...' : 'IA Otimizar Descrição'}
                  </button>
                </div>
                <textarea value={formState.description} onChange={e => setFormState({...formState, description: e.target.value})} placeholder="Descreva os benefícios do serviço..." className="w-full p-3 border border-slate-200 rounded-xl h-28 resize-none outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
              </div>
              <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black uppercase tracking-widest text-xs transition-all hover:bg-slate-800 shadow-xl">
                Salvar no Banco de Dados
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

