              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</label>
                  <input type="date" value={formState.date} onChange={e => setFormState({...formState, date: e.target.value})} required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Horário</label>
                  <input type="time" value={formState.time} onChange={e => setFormState({...formState, time: e.target.value})} required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-bold" />
                </div>
              </div>
              <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black uppercase tracking-widest text-xs transition-all hover:bg-slate-800 shadow-xl mt-4">
                Salvar Alterações
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const AIAssistantView: React.FC<{ services: Service[]; setServices: React.Dispatch<React.SetStateAction<Service[]>>; }> = ({ services, setServices }) => {
  const [prompt, setPrompt] = useState("");
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState<string | null>(null);

  const handleAskAI = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const responseText = await askExpertAssistant(prompt, services.map(s => s.name));
      setSuggestion(responseText || "Não foi possível gerar uma sugestão no momento.");
    } catch (error) {
      setSuggestion("Erro ao consultar a IA da Barbearia.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <div className="text-center space-y-2 mb-10">
        <div className="inline-flex p-4 bg-slate-900 rounded-full text-amber-500 mb-2 border-2 border-amber-500 shadow-xl shadow-amber-500/10 animate-pulse"><Sparkles size={40} /></div>
        <h2 className="text-2xl font-black italic uppercase tracking-tighter">IA Consultoria <span className="text-amber-500 italic">Negócios</span></h2>
        <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Otimize sua barbearia com inteligência artificial.</p>
      </div>

      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-xl space-y-6">
        <div className="relative">
          <textarea className="w-full p-5 pr-14 border border-slate-100 bg-slate-50 rounded-2xl focus:ring-4 focus:ring-amber-100 outline-none min-h-[140px] resize-none text-slate-900 font-medium text-sm md:text-base transition-all placeholder:italic" placeholder="Ex: Sugira uma promoção para aumentar o ticket médio dos serviços de barba..." value={prompt} onChange={e => setPrompt(e.target.value)} />
          <button onClick={handleAskAI} disabled={loading || !prompt} className="absolute bottom-5 right-5 p-3 bg-slate-900 text-amber-500 rounded-xl hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50 active:scale-90">
            {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
          </button>
        </div>

        {suggestion && (
          <div className="p-6 bg-slate-900 text-white rounded-2xl border-l-4 border-amber-500 animate-in fade-in slide-in-from-bottom-2 duration-500 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 right-0 p-3 opacity-10">
               <Sparkles size={64} />
            </div>
            <div className="flex items-center gap-2 text-amber-500 font-black mb-4 text-[10px] uppercase tracking-widest relative z-10"><Sparkles size={16} /> Insight Estratégico</div>
            <div className="text-slate-300 text-xs md:text-sm whitespace-pre-wrap font-medium italic leading-relaxed relative z-10">{suggestion}</div>
          </div>
        )}
      </div>
    </div>
  );
};

