  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('barberpro_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('barberpro_current_user', JSON.stringify(currentUser));
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('barberpro_services', JSON.stringify(services));
  }, [services]);

  useEffect(() => {
    localStorage.setItem('barberpro_bookings', JSON.stringify(bookings));
  }, [bookings]);

  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const upcomingBookings = bookings.filter(b => {
    const bookingDate = new Date(b.date);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return bookingDate >= today && b.status !== 'cancelled';
  });

  // Auth Handlers
  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const email = formData.get('email') as string;

    if (users.find(u => u.email === email)) {
      alert("Este e-mail já está cadastrado.");
      return;
    }

    const newUser: User = {
      id: `u${Date.now()}`,
      name: formData.get('name') as string,
      email: email,
      password: formData.get('password') as string,
      role: 'admin', // For simplicity in this demo, new registrations are admins
      createdAt: new Date().toISOString()
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
    setActiveView('dashboard');
  };

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const email = formData.get('email') as string;
    const password = formData.get('password') as string;

    const user = users.find(u => u.email === email && u.password === password);
    if (user) {
      setCurrentUser(user);
      setActiveView('dashboard');
    } else {
      alert("Credenciais inválidas. Verifique seu e-mail e senha.");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveView('landing');
  };

  // Service Handlers
  const addService = (newService: Service) => {
    setServices(prev => [...prev, newService]);
  };

  const updateService = (updatedService: Service) => {
    setServices(prev => prev.map(s => s.id === updatedService.id ? updatedService : s));
  };

  const deleteService = (id: string) => {
    if (window.confirm("Tem certeza que deseja excluir este serviço do catálogo?")) {
      setServices(prev => prev.filter(s => s.id !== id));
