  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X,
  ArrowLeft,
  Edit2,
  Check,
  XCircle,
  Mail,
  User as UserIcon,
  Calendar,
  ThumbsUp,
  XOctagon,
  LogOut,
  Lock,
