          <button className="lg:hidden p-2 hover:bg-slate-100 rounded-lg" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="flex-1" />
          <div className="flex items-center gap-3 md:gap-6">
            <div className="flex items-center gap-3">
              <div className="text-right hidden sm:block">
                <p className="text-xs font-black uppercase text-slate-900 italic">{currentUser?.name || 'Administrador'}</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase">{currentUser?.role === 'admin' ? 'Gestão Master' : 'Usuário'}</p>
              </div>
              <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${currentUser?.name || 'Admin'}`} alt="Avatar" className="w-9 h-9 rounded-full border-2 border-amber-500 shadow-sm" />
            </div>
            <div className="h-6 w-px bg-slate-200" />
            <button 
              onClick={handleLogout}
              title="Desligar/Sair do Sistema"
              className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
            >
              <LogOut size={22} />
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={totalRevenue} 
              upcomingCount={upcomingBookings.length} 
              recentBookings={bookings.slice(-8).reverse()} 
              services={services} 
              onConfirm={confirmBooking}
              onCancel={cancelBooking}
              onDelete={deleteBooking}
            />
          )}
          {activeView === 'services' && <ServicesView services={services} onAdd={addService} onEdit={updateService} onDelete={deleteService} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onAdd={addBooking} onEdit={updateBooking} onDelete={deleteBooking} onConfirm={confirmBooking} onCancel={cancelBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} setServices={setServices} />}
        </div>
      </main>
    </div>
  );
};

