                <select value={formState.serviceId} onChange={e => setFormState({...formState, serviceId: e.target.value})} className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 appearance-none font-black italic uppercase tracking-tighter">
