              else onAdd({ ...formState, id: `b${Date.now()}` } as Booking);
              setIsModalOpen(false);
            }}>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome do Cliente</label>
                <input value={formState.clientName} onChange={e => setFormState({...formState, clientName: e.target.value})} placeholder="Nome do Cliente" required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">E-mail</label>
                <input value={formState.clientEmail} onChange={e => setFormState({...formState, clientEmail: e.target.value})} placeholder="E-mail" required className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
