          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm">ENTRAR</button>
        </form>
        <p className="text-center text-slate-500 text-xs mt-6 uppercase">Não tem conta? <button onClick={() => setActiveView('register')} className="text-amber-500 font-bold">Cadastre-se</button></p>
      </div>
    </div>
  );

  if (activeView === 'register') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8">
        <button onClick={() => setActiveView('login')} className="flex items-center gap-2 text-slate-500 mb-8 font-bold text-xs"><ArrowLeft size={16} /> VOLTAR</button>
        <h2 className="text-2xl font-black text-white italic mb-8 uppercase">NOVO <span className="text-amber-500">Administrador</span></h2>
        <form onSubmit={handleRegister} className="space-y-4">
          <input name="name" type="text" placeholder="Nome Completo" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm">CRIAR CONTA</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-400 hover:text-amber-500 mb-8 font-bold text-sm transition-colors"><ArrowLeft size={18} /> CANCELAR</button>
        <h2 className="text-3xl font-black text-white mb-8 italic tracking-tight uppercase">AGENDE SEU <span className="text-amber-500">Novo Visual</span></h2>
        <form onSubmit={(e) => {
          e.preventDefault();
