              <p className="text-[10px] font-bold text-slate-400 uppercase">Administrador</p>
            </div>
            <div className="w-9 h-9 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950">{currentUser?.name.charAt(0)}</div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6">
          {activeView === 'dashboard' && <DashboardView revenue={totalRevenue} upcomingCount={upcomingBookings.length} recentBookings={bookings.slice(-5).reverse()} onConfirm={confirmBooking} onCancel={cancelBooking} services={services} />}
          {activeView === 'services' && <ServicesView services={services} onAdd={addService} onEdit={updateService} onDelete={deleteService} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onDelete={deleteBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} />}
        </div>
      </main>
    </div>
  );
};

