const AIAssistantView: React.FC<{ services: Service[] }> = ({ services }) => {
  const [prompt, setPrompt] = useState("");
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState<string | null>(null);

  const handleAskAI = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const response = await askExpertAssistant(prompt, services.map(s => s.name));
      setSuggestion(response);
    } finally { setLoading(false); }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-8 py-10">
      <div className="text-center space-y-2">
        <div className="inline-flex p-4 bg-slate-900 rounded-full text-amber-500 mb-2 border-2 border-amber-500 animate-pulse"><Sparkles size={32} /></div>
        <h2 className="text-2xl font-black italic uppercase">Gestão com <span className="text-amber-500 italic">IA</span></h2>
        <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Pergunte sugestões de marketing ou otimização de preços.</p>
      </div>
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-xl space-y-6">
        <div className="relative">
          <textarea className="w-full p-5 border border-slate-100 bg-slate-50 rounded-2xl focus:ring-4 focus:ring-amber-100 outline-none min-h-[140px] text-sm italic" placeholder="Ex: Como posso aumentar os agendamentos de barba no meio da semana?" value={prompt} onChange={e => setPrompt(e.target.value)} />
          <button onClick={handleAskAI} disabled={loading || !prompt} className="absolute bottom-5 right-5 p-3 bg-slate-900 text-amber-500 rounded-xl hover:bg-slate-800 disabled:opacity-50">
            {loading ? <Clock className="animate-spin" /> : <ChevronRight />}
          </button>
        </div>
        {suggestion && (
          <div className="p-6 bg-slate-900 text-white rounded-2xl border-l-4 border-amber-500 animate-in slide-in-from-bottom-2 duration-500">
            <p className="text-slate-300 text-sm whitespace-pre-wrap italic leading-relaxed">{suggestion}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X,
  ArrowLeft,
  Edit2,
  Check,
  XCircle,
  Mail,
  User as UserIcon,
  Calendar,
  ThumbsUp,
  XOctagon,
  LogOut,
  Lock,
  UserPlus,
  AlertTriangle
} from 'lucide-react';
import { Service, Booking, ViewType, User } from './types';
import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES } from './constants';
import { generateServiceDescription, askExpertAssistant } from './geminiService';
import LandingPage from './LandingPage';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');

  // 1. Initial State Loading with safer fallbacks
  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_users');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Erro ao carregar usuários:", e);
      return [];
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('barberpro_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [services, setServices] = useState<Service[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_services');
      return saved ? JSON.parse(saved) : INITIAL_SERVICES;
    } catch (e) {
      return INITIAL_SERVICES;
    }
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_bookings');
      return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
    } catch (e) {
      return INITIAL_BOOKINGS;
    }
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // 2. Persistence Synchronization
  useEffect(() => {
    localStorage.setItem('barberpro_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('barberpro_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('barberpro_current_user');
    }
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('barberpro_services', JSON.stringify(services));
  }, [services]);

  useEffect(() => {
    localStorage.setItem('barberpro_bookings', JSON.stringify(bookings));
  }, [bookings]);

  // 3. Robust Route Guarding
  useEffect(() => {
    const adminViews: ViewType[] = ['dashboard', 'services', 'bookings', 'ai-assistant'];
    if (adminViews.includes(activeView) && !currentUser) {
      setActiveView('login');
    }
  }, [activeView, currentUser]);

  // 4. Auth Handlers
  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = (formData.get('name') as string || '').trim();
    const email = (formData.get('email') as string || '').trim().toLowerCase();
    const password = (formData.get('password') as string || '').trim();

    if (!name || !email || !password) {
      alert("Por favor, preencha todos os campos.");
      return;
    }

    if (users.find(u => u.email.toLowerCase() === email)) {
      alert("Este e-mail já está em uso.");
      return;
    }

    const newUser: User = {
      id: `u${Date.now()}`,
      name,
      email,
      password,
      role: 'admin',
      createdAt: new Date().toISOString()
    };

    const newUsersList = [...users, newUser];

    // Forced immediate save to localStorage to ensure Route Guard doesn't kick us out
    localStorage.setItem('barberpro_users', JSON.stringify(newUsersList));
    localStorage.setItem('barberpro_current_user', JSON.stringify(newUser));

    setUsers(newUsersList);
    setCurrentUser(newUser);

    alert(`Bem-vindo, ${name}! Sua conta administrativa foi criada.`);
    setActiveView('dashboard');
  };

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string || '').trim().toLowerCase();
    const password = (formData.get('password') as string || '').trim();

    const user = users.find(u => u.email.toLowerCase() === email && u.password === password);
    if (user) {
      setCurrentUser(user);
      setActiveView('dashboard');
    } else {
      alert("E-mail ou senha incorretos.");
    }
  };

  const handleLogout = useCallback(() => {
    if (window.confirm("Deseja realmente sair?")) {
      setActiveView('landing');
      setCurrentUser(null);
      setIsSidebarOpen(false);
      localStorage.removeItem('barberpro_current_user');
    }
  }, []);

  // 5. Dashboard Data Calculations
  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const upcomingBookings = bookings.filter(b => {
    const bookingDate = new Date(b.date);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return bookingDate >= today && b.status !== 'cancelled';
  });

  // 6. Entity Handlers
  const addService = (newService: Service) => setServices(prev => [...prev, newService]);
  const updateService = (updated: Service) => setServices(prev => prev.map(s => s.id === updated.id ? updated : s));
  const deleteService = (id: string) => {
    if (window.confirm("Excluir este serviço permanentemente?")) {
      setServices(prev => prev.filter(s => s.id !== id));
    }
  };

  const addBooking = (newBooking: Booking) => {
    setBookings(prev => [...prev, newBooking]);
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert("Agendamento realizado! Aguardamos você.");
    }
  };

  const updateBooking = (updated: Booking) => setBookings(prev => prev.map(b => b.id === updated.id ? updated : b));
  const deleteBooking = (id: string) => setBookings(prev => prev.filter(b => b.id !== id));
  const confirmBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'confirmed' } : b));
  const cancelBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));

  // 7. View Dispatcher
  if (activeView === 'landing') return <LandingPage services={services} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => currentUser ? setActiveView('dashboard') : setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase transition-colors">
          <ArrowLeft size={16} /> VOLTAR AO INÍCIO
        </button>
        <div className="text-center mb-8">
          <div className="inline-flex p-3 bg-amber-500 rounded-xl mb-4 text-slate-950"><Lock size={24} /></div>
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">ACESSO <span className="text-amber-500">ADMIN</span></h2>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-500 block ml-1">E-mail</label>
            <input name="email" type="email" placeholder="seu@email.com" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-500 block ml-1">Senha</label>
            <input name="password" type="password" placeholder="••••••••" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 transition-all" />
          </div>
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm shadow-xl shadow-amber-500/10">ENTRAR NO PAINEL</button>
        </form>
        <p className="text-center text-slate-500 text-[10px] font-black mt-8 uppercase tracking-widest">
          Não tem conta? <button onClick={() => setActiveView('register')} className="text-amber-500 font-black hover:underline">Cadastre sua barbearia</button>
        </p>
      </div>
    </div>
  );

  if (activeView === 'register') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('login')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase transition-colors">
          <ArrowLeft size={16} /> VOLTAR AO LOGIN
        </button>
        <div className="text-center mb-8">
          <div className="inline-flex p-3 bg-amber-500 rounded-xl mb-4 text-slate-950"><UserPlus size={24} /></div>
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">NOVO <span className="text-amber-500">GESTOR</span></h2>
        </div>
        <form onSubmit={handleRegister} className="space-y-4">
          <input name="name" type="text" placeholder="Seu Nome Completo" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="email" type="email" placeholder="E-mail Administrativo" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="password" type="password" placeholder="Crie uma Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm shadow-xl mt-4">CRIAR CONTA MASTER</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-400 hover:text-amber-500 mb-8 font-black text-xs uppercase tracking-widest transition-colors"><ArrowLeft size={18} /> CANCELAR</button>
        <h2 className="text-3xl font-black text-white mb-8 italic tracking-tight uppercase">AGENDE SEU <span className="text-amber-500">NOVO VISUAL</span></h2>
        <form onSubmit={(e) => {
          e.preventDefault();
          const formData = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: formData.get('name') as string,
            clientEmail: formData.get('email') as string,
            serviceId: formData.get('service') as string,
            date: formData.get('date') as string,
            time: formData.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-4">
          <div className="space-y-1">
             <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Seu Nome</label>
             <input name="name" type="text" placeholder="Como podemos te chamar?" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Seu E-mail</label>
             <input name="email" type="email" placeholder="Para confirmação" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Serviço</label>
             <select name="service" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 appearance-none font-bold">
               {services.map(s => <option key={s.id} value={s.id} className="bg-slate-900">{s.name} - R$ {s.price.toFixed(2)}</option>)}
             </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Data</label>
              <input name="date" type="date" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Hora</label>
              <input name="time" type="time" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
            </div>
          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all text-base shadow-xl uppercase tracking-widest mt-6">FINALIZAR AGENDAMENTO</button>
        </form>
      </div>
    </div>
  );

  // Admin Dashboard Structure
  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-lg text-slate-950 shadow-lg shadow-amber-500/20"><Scissors size={20} /></div>
              <h1 className="text-lg font-black italic text-slate-900 tracking-tighter uppercase">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button className="lg:hidden text-slate-400 hover:text-slate-900" onClick={() => setIsSidebarOpen(false)}><X size={20} /></button>
          </div>

          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Início / Resumo" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={20} />} label="Catálogo / Serviços" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Gestão de Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Sparkles size={20} />} label="Consultoria IA" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-100">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all text-xs font-black uppercase tracking-widest group">
              <LogOut size={20} className="group-hover:-translate-x-1 transition-transform" /> DESCONECTAR
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-slate-200 shrink-0">
          <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-lg" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="flex-1" />
          <div className="flex items-center gap-3">
            <div className="text-right hidden sm:block">
              <p className="text-xs font-black uppercase text-slate-900 italic leading-none mb-1">{currentUser?.name}</p>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Painel Administrativo</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-900 text-amber-500 flex items-center justify-center font-black border-2 border-amber-500 shadow-sm">
              {currentUser?.name.charAt(0)}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50/50">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={totalRevenue} 
              upcomingCount={upcomingBookings.length} 
              recentBookings={bookings.slice(-8).reverse()} 
              onConfirm={confirmBooking} 
              onCancel={cancelBooking} 
              services={services} 
            />
          )}
          {activeView === 'services' && (
            <ServicesView 
              services={services} 
              onAdd={addService} 
              onEdit={updateService} 
              onDelete={deleteService} 
            />
          )}
          {activeView === 'bookings' && (
            <BookingsView 
              bookings={bookings} 
              services={services} 
              onConfirm={confirmBooking} 
              onCancel={cancelBooking} 
              onDelete={deleteBooking} 
            />
          )}
          {activeView === 'ai-assistant' && (
            <AIAssistantView services={services} />
          )}
        </div>
      </main>
    </div>
  );
};

