const ServicesView: React.FC<{ 
  services: Service[]; 
  onAdd: (s: Service) => void; 
  onEdit: (s: Service) => void; 
  onDelete: (id: string) => void; 
}> = ({ services, onAdd, onEdit, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingService, setEditingService] = useState<Service | null>(null);
  const [formState, setFormState] = useState<Partial<Service>>({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
  const [isLoadingAI, setIsLoadingAI] = useState(false);

  useEffect(() => {
    if (editingService) setFormState(editingService);
    else setFormState({ name: '', category: CATEGORIES[0], duration: 30, price: 0, description: '' });
  }, [editingService, isModalOpen]);

  const handleSuggestAI = async () => {
    if (!formState.name) return alert("Por favor, digite o nome do serviço.");
    setIsLoadingAI(true);
    try {
      const desc = await generateServiceDescription(formState.name!, formState.category || 'Geral');
      setFormState(prev => ({ ...prev, description: desc }));
    } finally { setIsLoadingAI(false); }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8">
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <h2 className="text-2xl font-black italic uppercase tracking-tighter">Gestão de <span className="text-amber-500">Catálogo</span></h2>
        <button onClick={() => { setEditingService(null); setIsModalOpen(true); }} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest flex items-center gap-2 shadow-xl hover:bg-slate-800 transition-all transform active:scale-95">
          <Plus size={18} /> CADASTRAR SERVIÇO
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {services.map(s => (
          <div key={s.id} className="bg-white border border-slate-200 p-6 md:p-8 rounded-3xl shadow-sm hover:border-amber-500 transition-all group relative overflow-hidden">
            <div className="flex justify-between items-start mb-6">
              <span className="text-[10px] font-black uppercase text-amber-600 bg-amber-50 px-3 py-1.5 rounded-full tracking-widest border border-amber-100">{s.category}</span>
              <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                <button onClick={() => { setEditingService(s); setIsModalOpen(true); }} className="p-2 text-slate-400 hover:text-amber-500 transition-colors"><Edit2 size={18} /></button>
                <button onClick={() => onDelete(s.id)} className="p-2 text-slate-400 hover:text-red-500 transition-colors"><Trash2 size={18} /></button>
              </div>
            </div>
            <h3 className="font-black italic text-xl mb-2 uppercase tracking-tight group-hover:text-amber-600 transition-colors">{s.name}</h3>
            <p className="text-xs text-slate-500 italic mb-8 h-12 overflow-hidden leading-relaxed">{s.description}</p>
            <div className="flex justify-between items-center pt-6 border-t border-slate-50">
              <span className="text-[10px] font-black uppercase text-slate-400 flex items-center gap-1.5 tracking-widest">
                <Clock size={14} className="text-amber-500" /> {s.duration} MINUTOS
              </span>
              <span className="text-xl font-black text-slate-900 italic">R$ {s.price.toFixed(2)}</span>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-slate-900 text-white flex justify-between items-center">
              <h3 className="font-black italic uppercase text-sm tracking-[0.2em]">{editingService ? 'Editar' : 'Novo'} Serviço</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:text-amber-500 transition-colors"><X size={24} /></button>
            </div>
            <form className="p-8 space-y-5" onSubmit={(e) => {
              e.preventDefault();
              if (editingService) onEdit({ ...formState, id: editingService.id } as Service);
              else onAdd({ ...formState, id: `s${Date.now()}` } as Service);
              setIsModalOpen(false);
            }}>
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome do Serviço</label>
                <input value={formState.name} onChange={e => setFormState({...formState, name: e.target.value})} placeholder="Ex: Corte Degradê" required className="w-full p-4 border border-slate-100 bg-slate-50 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-bold text-slate-900" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Preço (R$)</label>
                  <input type="number" step="0.01" value={formState.price} onChange={e => setFormState({...formState, price: parseFloat(e.target.value)})} placeholder="0,00" required className="w-full p-4 border border-slate-100 bg-slate-50 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-black text-slate-900" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Minutos</label>
                  <input type="number" value={formState.duration} onChange={e => setFormState({...formState, duration: parseInt(e.target.value)})} placeholder="45" required className="w-full p-4 border border-slate-100 bg-slate-50 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-black text-slate-900" />
                </div>
              </div>

              <div className="space-y-1 relative">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Descrição</label>
                   <button type="button" onClick={handleSuggestAI} disabled={isLoadingAI} className="text-[10px] font-black uppercase text-amber-600 flex items-center gap-1 hover:text-amber-800 transition-colors disabled:opacity-50">
                     <Sparkles size={12} /> {isLoadingAI ? 'CRIANDO...' : 'SUGERIR POR IA'}
                   </button>
                </div>
                <textarea value={formState.description} onChange={e => setFormState({...formState, description: e.target.value})} placeholder="Explique por que seu cliente deve escolher este serviço..." required className="w-full p-4 border border-slate-100 bg-slate-50 rounded-2xl h-32 resize-none outline-none focus:ring-2 focus:ring-amber-500 transition-all italic text-sm text-slate-600 leading-relaxed" />
              </div>

              <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs hover:bg-slate-800 transition-all shadow-xl mt-4 transform active:scale-95">
                SALVAR NO CATÁLOGO
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

