                      )}
                      <button onClick={() => onDelete(b.id)} className="p-2.5 text-slate-200 hover:text-red-600 transition-colors" title="Remover do Histórico">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  </div>
);

