              </div>

              <div className="space-y-2 relative">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Descrição Premium</label>
                   <button type="button" onClick={handleSuggestAI} disabled={isLoadingAI} className="text-[10px] font-black uppercase text-amber-600 flex items-center gap-1.5 hover:text-amber-800 transition-colors disabled:opacity-50">
                     <Sparkles size={14} className={isLoadingAI ? 'animate-spin' : ''} /> {isLoadingAI ? 'PROCESSANDO...' : 'SUGERIR POR IA'}
                   </button>
                </div>
                <textarea value={formState.description} onChange={e => setFormState({...formState, description: e.target.value})} placeholder="Destaque os benefícios e diferenciais deste atendimento..." required className="w-full p-6 border border-slate-100 bg-slate-50/50 rounded-3xl h-36 resize-none outline-none focus:ring-4 focus:ring-amber-500/10 transition-all italic text-sm text-slate-600 leading-relaxed font-medium" />
