        </div>
        <div className="space-y-2">
          <h2 className="text-4xl font-black italic uppercase tracking-tighter leading-none">CONSULTORIA <span className="text-amber-500">ESTRATÉGICA</span> IA</h2>
          <p className="text-slate-500 text-[11px] font-black uppercase tracking-[0.35em] max-w-xl mx-auto leading-relaxed">
            Assistência em marketing, expansão e otimização operacional.
          </p>
        </div>
      </div>

      <div className="bg-white p-8 md:p-14 rounded-[3.5rem] border border-slate-200 shadow-[0_32px_64px_-12px_rgba(0,0,0,0.05)] space-y-10 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12">
           <LayoutDashboard size={200} />
        </div>

        <div className="relative space-y-5">
          <label className="text-[10px] font-black uppercase text-slate-400 ml-3 tracking-[0.2em]">Sua Solicitação ou Dúvida:</label>
          <div className="relative">
            <textarea 
              className="w-full p-8 border border-slate-100 bg-slate-50/70 rounded-[2.5rem] focus:ring-8 focus:ring-amber-100 outline-none min-h-[180px] text-lg md:text-xl italic font-medium text-slate-800 transition-all placeholder:text-slate-300 shadow-inner leading-relaxed" 
              placeholder="Ex: Como posso estruturar um programa de fidelidade para cortes mensais?" 
              value={prompt} 
              onChange={e => setPrompt(e.target.value)} 
            />
            <button 
              onClick={handleAskAI} 
              disabled={loading || !prompt} 
              className="absolute bottom-8 right-8 p-5 bg-slate-900 text-amber-500 rounded-3xl hover:bg-slate-800 transition-all shadow-2xl disabled:opacity-50 active:scale-90 group"
            >
              {loading ? <Clock className="animate-spin" size={28} /> : <ChevronRight size={28} className="group-hover:translate-x-2 transition-transform duration-300" />}
            </button>
          </div>
        </div>

        {suggestion && (
          <div className="p-10 bg-slate-950 text-white rounded-[2.5rem] border-l-8 border-amber-500 animate-in slide-in-from-bottom-8 duration-1000 shadow-2xl relative">
            <div className="flex items-center gap-3 text-amber-500 font-black mb-8 text-[11px] uppercase tracking-[0.25em]">
               <Sparkles size={18} /> RESPOSTA DO CONSULTOR IA
            </div>
            <p className="text-slate-200 text-sm md:text-lg whitespace-pre-wrap italic leading-relaxed font-medium">
              {suggestion}
            </p>
            <div className="mt-8 pt-8 border-t border-white/5 flex justify-end">
               <span className="text-[9px] font-black text-white/20 uppercase tracking-widest italic">Análise baseada no catálogo atual</span>
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 opacity-80">
         <ExamplePrompt text="Sugerir combo promocional para o mês de aniversário." />
         <ExamplePrompt text="Como gerenciar melhor o tempo entre atendimentos?" />
         <div className="hidden lg:block">
           <ExamplePrompt text="Estratégias para aumentar o ticket médio por cliente." />
         </div>
      </div>
    </div>
  );
};

const ExamplePrompt: React.FC<{ text: string }> = ({ text }) => (
  <div className="p-6 bg-white rounded-3xl border border-slate-100 text-center hover:border-amber-200 transition-all cursor-default shadow-sm">
    <h5 className="font-black uppercase text-[9px] text-slate-400 tracking-[0.2em] mb-2.5 opacity-50">Exemplo de comando</h5>
    <p className="text-xs italic text-slate-600 font-semibold leading-relaxed">"{text}"</p>
  </div>
);

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Clock, 
  DollarSign,
  Search,
  ChevronRight,
  Menu,
  X,
  ArrowLeft,
  Edit2,
  Check,
  XCircle,
  Mail,
  User as UserIcon,
  Calendar,
  ThumbsUp,
  XOctagon,
  LogOut,
  Lock,
  UserPlus,
  AlertTriangle,
  TrendingUp,
  Users as UsersIcon
} from 'lucide-react';
import { Service, Booking, ViewType, User } from './types';
import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES } from './constants';
import { generateServiceDescription, askExpertAssistant } from './geminiService';
import LandingPage from './LandingPage';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');

  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_users');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('barberpro_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [services, setServices] = useState<Service[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_services');
      return saved ? JSON.parse(saved) : INITIAL_SERVICES;
    } catch (e) {
      return INITIAL_SERVICES;
    }
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_bookings');
      return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
    } catch (e) {
      return INITIAL_BOOKINGS;
    }
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('barberpro_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('barberpro_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('barberpro_current_user');
    }
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('barberpro_services', JSON.stringify(services));
  }, [services]);

  useEffect(() => {
    localStorage.setItem('barberpro_bookings', JSON.stringify(bookings));
  }, [bookings]);

  useEffect(() => {
    const adminViews: ViewType[] = ['dashboard', 'services', 'bookings', 'ai-assistant'];
    if (adminViews.includes(activeView) && !currentUser) {
      setActiveView('login');
    }
  }, [activeView, currentUser]);

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const name = (formData.get('name') as string || '').trim();
    const email = (formData.get('email') as string || '').trim().toLowerCase();
    const password = (formData.get('password') as string || '').trim();

    if (!name || !email || !password) {
      alert("Preencha todos os campos.");
      return;
    }

    if (users.find(u => u.email.toLowerCase() === email)) {
      alert("E-mail já cadastrado.");
      return;
    }

    const newUser: User = {
      id: `u${Date.now()}`,
      name,
      email,
      password,
      role: 'admin',
      createdAt: new Date().toISOString()
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
    setActiveView('dashboard');
  };

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const email = (formData.get('email') as string || '').trim().toLowerCase();
    const password = (formData.get('password') as string || '').trim();

    const user = users.find(u => u.email.toLowerCase() === email && u.password === password);
    if (user) {
      setCurrentUser(user);
      setActiveView('dashboard');
    } else {
      alert("Credenciais inválidas.");
    }
  };

  const handleLogout = useCallback(() => {
    if (window.confirm("Deseja sair?")) {
      setActiveView('landing');
      setCurrentUser(null);
      setIsSidebarOpen(false);
    }
  }, []);

  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const pendingCount = bookings.filter(b => b.status === 'pending').length;
  const upcomingCount = bookings.filter(b => b.status !== 'cancelled').length;

  const addService = (s: Service) => setServices(prev => [...prev, s]);
  const updateService = (updated: Service) => setServices(prev => prev.map(s => s.id === updated.id ? updated : s));
  const deleteService = (id: string) => setServices(prev => prev.filter(s => s.id !== id));

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    if (activeView === 'client-booking') setActiveView('landing');
  };

  const confirmBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'confirmed' } : b));
  const cancelBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));
  const deleteBooking = (id: string) => setBookings(prev => prev.filter(b => b.id !== id));

  if (activeView === 'landing') return <LandingPage services={services} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => currentUser ? setActiveView('dashboard') : setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase transition-colors">
          <ArrowLeft size={16} /> VOLTAR AO INÍCIO
        </button>
        <div className="text-center mb-8">
          <div className="inline-flex p-3 bg-amber-500 rounded-xl mb-4 text-slate-950"><Lock size={24} /></div>
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">ACESSO <span className="text-amber-500">ADMIN</span></h2>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm shadow-xl">ENTRAR</button>
        </form>
        <p className="text-center text-slate-500 text-[10px] font-black mt-8 uppercase tracking-widest">
          Não tem conta? <button onClick={() => setActiveView('register')} className="text-amber-500 font-black hover:underline">Cadastre-se</button>
        </p>
      </div>
    </div>
  );

  if (activeView === 'register') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('login')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase transition-colors">
          <ArrowLeft size={16} /> VOLTAR AO LOGIN
        </button>
        <div className="text-center mb-8">
          <div className="inline-flex p-3 bg-amber-500 rounded-xl mb-4 text-slate-950"><UserPlus size={24} /></div>
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">NOVO <span className="text-amber-500">GESTOR</span></h2>
        </div>
        <form onSubmit={handleRegister} className="space-y-4">
          <input name="name" type="text" placeholder="Seu Nome" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm shadow-xl">CRIAR CONTA</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-400 hover:text-amber-500 mb-8 font-black text-xs uppercase tracking-widest transition-colors"><ArrowLeft size={18} /> CANCELAR</button>
        <h2 className="text-3xl font-black text-white mb-8 italic tracking-tight uppercase">AGENDE SEU <span className="text-amber-500">NOVO VISUAL</span></h2>
        <form onSubmit={(e) => {
          e.preventDefault();
          const formData = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: formData.get('name') as string,
            clientEmail: formData.get('email') as string,
            serviceId: formData.get('service') as string,
            date: formData.get('date') as string,
            time: formData.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-4">
          <input name="name" type="text" placeholder="Nome" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <select name="service" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500">
            {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
          </select>
          <div className="grid grid-cols-2 gap-4">
            <input name="date" type="date" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
            <input name="time" type="time" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all text-base shadow-xl uppercase tracking-widest mt-6">FINALIZAR</button>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-lg text-slate-950"><Scissors size={20} /></div>
              <h1 className="text-lg font-black italic text-slate-900 tracking-tighter uppercase">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
          </div>
          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Sparkles size={20} />} label="IA Assistant" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all text-xs font-black uppercase tracking-widest">
            <LogOut size={20} /> SAIR
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-slate-200 shrink-0">
          <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="flex-1" />
          <div className="flex items-center gap-3">
            <span className="text-xs font-black uppercase italic text-slate-900">{currentUser?.name}</span>
            <div className="w-10 h-10 rounded-full bg-slate-900 text-amber-500 flex items-center justify-center font-black border-2 border-amber-500 uppercase">{currentUser?.name.charAt(0)}</div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          {activeView === 'dashboard' && <DashboardView revenue={totalRevenue} pending={pendingCount} upcoming={upcomingCount} serviceCount={services.length} recent={bookings.slice(-5).reverse()} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onNavigate={setActiveView} />}
          {activeView === 'services' && <ServicesView services={services} onAdd={addService} onEdit={updateService} onDelete={deleteService} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onDelete={deleteBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} />}
        </div>
      </main>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all text-[11px] font-black uppercase tracking-widest ${active ? 'bg-amber-500 text-slate-950 shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
    {icon} {label}
  </button>
);

const StatCard = ({ label, value, icon, color = "amber" }: any) => {
  const colors: any = {
    amber: 'text-amber-500 bg-amber-50 border-amber-100',
    green: 'text-green-500 bg-green-50 border-green-100',
    blue: 'text-blue-500 bg-blue-50 border-blue-100',
    indigo: 'text-indigo-500 bg-indigo-50 border-indigo-100'
  };
  return (
    <div className="bg-white p-6 rounded-3xl border border-slate-200 flex justify-between items-center hover:shadow-xl transition-all">
      <div>
        <p className="text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest">{label}</p>
        <h4 className="text-2xl font-black italic text-slate-900">{value}</h4>
      </div>
      <div className={`p-4 rounded-2xl border ${colors[color]}`}>{icon}</div>
    </div>
  );
};

const DashboardView = ({ revenue, pending, upcoming, serviceCount, recent, services, onConfirm, onCancel, onNavigate }: any) => (
  <div className="space-y-8 max-w-7xl mx-auto">
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
      <StatCard label="Receita Confirmada" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={22} />} color="green" />
      <StatCard label="Pendências" value={pending.toString()} icon={<TrendingUp size={22} />} color="amber" />
      <StatCard label="Agenda Ativa" value={upcoming.toString()} icon={<Calendar size={22} />} color="blue" />
      <StatCard label="Serviços" value={serviceCount.toString()} icon={<Scissors size={22} />} color="indigo" />
    </div>

    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
        <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 italic mb-8">Atividade Recente</h3>
        <div className="space-y-4">
          {recent.length === 0 ? <p className="text-center py-20 text-slate-400 font-bold uppercase italic text-sm">Nenhum registro.</p> : recent.map((b: any) => (
            <div key={b.id} className="flex items-center justify-between p-5 bg-slate-50/50 rounded-2xl border border-slate-100 hover:border-amber-300 transition-all gap-4">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-slate-900 flex items-center justify-center text-amber-500 font-black">{b.clientName.charAt(0)}</div>
                <div>
                  <span className="text-sm font-black italic block text-slate-900 uppercase">{b.clientName}</span>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{b.date.split('-').reverse().join('/')} @ {b.time}</span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {b.status === 'pending' && <button onClick={() => onConfirm(b.id)} className="p-2 bg-green-500 text-white rounded-lg"><Check size={16} /></button>}
                {b.status !== 'cancelled' && <button onClick={() => onCancel(b.id)} className="p-2 bg-slate-200 text-slate-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"><X size={16} /></button>}
                <span className={`text-[9px] font-black uppercase px-3 py-1.5 rounded-lg border ${b.status === 'confirmed' ? 'bg-green-50 text-green-700' : b.status === 'cancelled' ? 'bg-red-50 text-red-700' : 'bg-amber-50 text-amber-700'}`}>{b.status}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="bg-slate-900 p-8 rounded-[2rem] border-t-8 border-amber-500 text-white flex flex-col justify-between shadow-2xl">
        <div className="space-y-6">
          <div className="p-4 bg-amber-500 rounded-2xl text-slate-950 w-fit"><Sparkles size={32} /></div>
          <h4 className="text-2xl font-black italic uppercase tracking-tighter">Insight <span className="text-amber-500">IA</span></h4>
          <p className="text-slate-400 text-xs italic leading-relaxed">Sua agenda está com baixa ocupação nas terças. Tente lançar um desconto "Quick Fade" para este período!</p>
        </div>
        <button onClick={() => onNavigate('ai-assistant')} className="w-full py-4 mt-8 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-[11px]">SOLICITAR ANÁLISE</button>
      </div>
    </div>
  </div>
);

const ServicesView = ({ services, onAdd, onEdit, onDelete }: any) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form, setForm] = useState<any>({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    if (editing) setForm(editing);
    else setForm({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  }, [editing, isModalOpen]);

  const handleSuggest = async () => {
