          <Plus size={18} /> NOVO SERVIÇO
        </button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {services.map((s: any) => (
          <div key={s.id} className="bg-white border border-slate-200 p-8 rounded-[2rem] hover:border-amber-500 transition-all group relative">
            <div className="flex justify-between items-start mb-6">
