              <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                <button onClick={() => { setEditing(s); setIsModalOpen(true); }} className="p-2 text-slate-400 hover:text-amber-500"><Edit2 size={16} /></button>
                <button onClick={() => onDelete(s.id)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16} /></button>
              </div>
            </div>
            <h3 className="font-black italic text-xl mb-2 uppercase">{s.name}</h3>
            <p className="text-xs text-slate-400 italic mb-8 h-12 overflow-hidden">{s.description}</p>
            <div className="flex justify-between items-center pt-6 border-t border-slate-50">
              <span className="text-[10px] font-black uppercase text-slate-400 flex items-center gap-1.5 tracking-widest"><Clock size={14} className="text-amber-500" /> {s.duration} MIN</span>
              <span className="text-xl font-black text-slate-900 italic">R$ {s.price.toFixed(2)}</span>
