      </div>
      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 shadow-2xl">
            <h3 className="font-black italic uppercase text-lg mb-8 tracking-widest">{editing ? 'Editar' : 'Novo'} Serviço</h3>
            <div className="space-y-4">
              <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="Nome do Serviço" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl" />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={form.price} onChange={e => setForm({...form, price: parseFloat(e.target.value)})} placeholder="Preço" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl" />
                <input type="number" value={form.duration} onChange={e => setForm({...form, duration: parseInt(e.target.value)})} placeholder="Minutos" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl" />
              </div>
              <div className="relative">
                <textarea value={form.description} onChange={e => setForm({...form, description: e.target.value})} placeholder="Descrição" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl h-32" />
                <button onClick={handleSuggest} className="absolute top-4 right-4 text-[10px] font-black uppercase text-amber-600 flex items-center gap-1">
                  <Sparkles size={12} /> {loadingAI ? '...' : 'IA SUGGEST'}
                </button>
              </div>
              <button onClick={() => {
                if (editing) onEdit({...form, id: editing.id});
                else onAdd({...form, id: `s${Date.now()}`});
                setIsModalOpen(false);
              }} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest">SALVAR</button>
              <button onClick={() => setIsModalOpen(false)} className="w-full text-slate-400 font-black uppercase text-[10px] tracking-widest">FECHAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

