              </div>

              <button onClick={() => {
                if (editing) onEdit({...form, id: editing.id});
                else onAdd({...form, id: `s${Date.now()}`});
                setIsModalOpen(false);
              }} className="w-full py-6 bg-slate-900 text-white rounded-3xl font-black uppercase tracking-[0.3em] text-[11px] hover:bg-slate-800 transition-all shadow-2xl mt-4 transform active:scale-95">
                SALVAR ALTERAÇÕES
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
