const AIAssistantView = ({ services }: any) => {
  const [prompt, setPrompt] = useState("");
  const [res, setRes] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const data = await askExpertAssistant(prompt, services.map((s: any) => s.name));
      setRes(data);
    } catch (err) {
      alert("Erro ao consultar a IA. Verifique sua conexão.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-10 space-y-12 px-4">
      <div className="text-center space-y-4">
        <div className="inline-flex p-6 bg-slate-900 rounded-[2.5rem] text-amber-500 mb-6 border-2 border-amber-500/20 shadow-2xl animate-pulse">
          <Sparkles size={48} />
        </div>
        <h2 className="text-4xl font-black italic uppercase tracking-tighter leading-none">CONSULTORIA <span className="text-amber-500">ESTRATÉGICA</span> IA</h2>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.3em]">Otimize sua barbearia com inteligência artificial</p>
      </div>
      <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-xl space-y-8 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12">
           <LayoutDashboard size={200} />
        </div>
        <div className="relative z-10 space-y-4">
          <label className="text-[10px] font-black uppercase text-slate-400 ml-3 tracking-widest">Sua Dúvida ou Comando</label>
          <textarea 
            className="w-full p-8 bg-slate-50 border border-slate-100 rounded-[2.5rem] h-44 italic focus:ring-8 focus:ring-amber-500/5 transition-all outline-none leading-relaxed text-slate-700 shadow-inner" 
            placeholder="Ex: Como posso aumentar o ticket médio vendendo produtos pós-barba?" 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)} 
          />
        </div>
        <button 
          onClick={handleAsk} 
          disabled={loading || !prompt} 
          className="w-full py-6 bg-slate-900 text-amber-500 font-black uppercase tracking-[0.3em] text-xs rounded-3xl hover:bg-slate-800 transition-all shadow-2xl disabled:opacity-50 active:scale-95 group relative z-10"
        >
          {loading ? 'ANALISANDO DADOS...' : 'SOLICITAR CONSULTORIA ESTRATÉGICA'}
        </button>
        {res && (
          <div className="p-10 bg-slate-950 text-white rounded-[2.5rem] border-l-8 border-amber-500 animate-in slide-in-from-bottom-6 duration-1000 italic leading-relaxed whitespace-pre-wrap relative z-10 shadow-2xl">
            <div className="flex items-center gap-3 text-amber-500 font-black mb-6 text-[11px] uppercase tracking-[0.2em]">
               <Sparkles size={18} /> RELATÓRIO DO ESPECIALISTA IA
            </div>
            {res}
          </div>
        )}
      </div>
    </div>
  );
};

