const ServicesView = ({ services, onAdd, onEdit, onDelete }: any) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form, setForm] = useState<any>({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    if (editing) setForm(editing);
    else setForm({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  }, [editing, isModalOpen]);

  const handleSuggest = async () => {
    if (!form.name) {
      alert("Informe o nome do serviço para gerar uma descrição.");
      return;
    }
    setLoadingAI(true);
    try {
      const desc = await generateServiceDescription(form.name, form.category);
      setForm({ ...form, description: desc });
    } finally {
      setLoadingAI(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 text-center sm:text-left">
        <div>
          <h2 className="text-2xl font-black italic uppercase tracking-tighter">Gestão de <span className="text-amber-500">Catálogo</span></h2>
          <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mt-1 italic">Organize seus atendimentos e valores</p>
        </div>
        <button onClick={() => { setEditing(null); setIsModalOpen(true); }} className="w-full sm:w-auto px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-2xl hover:bg-slate-800 transition-all transform active:scale-95">
          <Plus size={20} /> NOVO SERVIÇO
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
        {services.map((s: any) => (
          <div key={s.id} className="bg-white border border-slate-200 p-8 rounded-[2rem] hover:border-amber-500 hover:shadow-2xl hover:shadow-amber-500/5 transition-all duration-300 group relative overflow-hidden">
            <div className="flex justify-between items-start mb-6">
              <span className="text-[10px] font-black uppercase text-amber-600 bg-amber-50 px-3 py-1.5 rounded-xl border border-amber-100 italic">{s.category}</span>
              <div className="flex gap-2 opacity-100 lg:opacity-0 group-hover:opacity-100 transition-all translate-y-2 lg:translate-y-2 group-hover:translate-y-0">
                <button onClick={() => { setEditing(s); setIsModalOpen(true); }} className="p-2.5 bg-slate-50 text-slate-400 hover:text-amber-500 hover:bg-amber-50 rounded-xl transition-all"><Edit2 size={18} /></button>
                <button onClick={() => onDelete(s.id)} className="p-2.5 bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
              </div>
            </div>
            <h3 className="font-black italic text-2xl mb-3 uppercase tracking-tight group-hover:text-amber-600 transition-colors leading-none truncate">{s.name}</h3>
            <p className="text-xs text-slate-400 italic mb-10 h-16 overflow-hidden leading-relaxed font-medium">{s.description}</p>
            <div className="flex justify-between items-center pt-8 border-t border-slate-100">
              <span className="text-[10px] font-black uppercase text-slate-400 flex items-center gap-2 tracking-[0.1em]">
                <Clock size={16} className="text-amber-500" /> {s.duration} MINUTOS
              </span>
              <span className="text-xl font-black text-slate-900 italic tracking-tighter">R$ {s.price?.toFixed(2)}</span>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-6 md:p-8 bg-slate-900 text-white flex justify-between items-center">
              <h3 className="font-black italic uppercase text-lg tracking-widest">{editing ? 'Editar' : 'Novo'} Serviço</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-3 bg-white/5 rounded-2xl hover:text-amber-500 transition-colors"><X size={24} /></button>
            </div>
            <div className="p-6 md:p-10 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Nome do Serviço</label>
                <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="Ex: Master Fade Specialist" className="w-full p-4 md:p-5 border border-slate-100 bg-slate-50/50 rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-black text-slate-900 italic" />
              </div>

              <div className="grid grid-cols-2 gap-4 md:gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Preço (R$)</label>
                  <input type="number" step="0.01" value={form.price} onChange={e => setForm({...form, price: parseFloat(e.target.value)})} placeholder="0,00" className="w-full p-4 md:p-5 border border-slate-100 bg-slate-50/50 rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-black text-slate-900" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Minutos</label>
                  <input type="number" value={form.duration} onChange={e => setForm({...form, duration: parseInt(e.target.value)})} placeholder="45" className="w-full p-4 md:p-5 border border-slate-100 bg-slate-50/50 rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-black text-slate-900" />
                </div>
              </div>

              <div className="space-y-2 relative">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Descrição Premium</label>
                   <button onClick={handleSuggest} disabled={loadingAI} className="text-[10px] font-black uppercase text-amber-600 flex items-center gap-1.5 hover:text-amber-800 transition-colors disabled:opacity-50">
                     <Sparkles size={14} className={loadingAI ? 'animate-spin' : ''} /> {loadingAI ? '...' : 'GERAR IA'}
