              )}
              {b.status !== 'cancelled' && (
                <button onClick={() => onCancel(b.id)} className="flex-1 py-3 bg-slate-50 text-slate-400 border border-slate-100 rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2">
                  <X size={14} /> CANCELAR
                </button>
              )}
