import LandingPage from './LandingPage';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');

  // Senha administrativa fixa conforme solicitado
  const ADMIN_PASSWORD = "1966";

  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_users');
      const parsed = saved ? JSON.parse(saved) : [];

      // Garantir que o administrador mestre sempre exista no "banco de dados"
      if (!parsed.find((u: User) => u.role === 'admin')) {
        const masterAdmin: User = {
          id: 'admin-master',
          name: 'Administrador',
          email: 'admin@sistema.com',
          password: ADMIN_PASSWORD,
          role: 'admin',
          createdAt: new Date().toISOString()
        };
        const newUsers = [masterAdmin, ...parsed];
        localStorage.setItem('barberpro_users', JSON.stringify(newUsers));
        return newUsers;
      }
      return parsed;
    } catch (e) {
      return [];
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('barberpro_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [services, setServices] = useState<Service[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_services');
      return saved ? JSON.parse(saved) : INITIAL_SERVICES;
    } catch (e) {
      return INITIAL_SERVICES;
    }
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_bookings');
      return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
    } catch (e) {
      return INITIAL_BOOKINGS;
    }
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('barberpro_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('barberpro_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('barberpro_current_user');
    }
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('barberpro_services', JSON.stringify(services));
  }, [services]);

  useEffect(() => {
    localStorage.setItem('barberpro_bookings', JSON.stringify(bookings));
  }, [bookings]);

  useEffect(() => {
    const adminViews: ViewType[] = ['dashboard', 'services', 'bookings', 'ai-assistant'];
    // Se o usuário tentar acessar uma view admin sem estar logado, manda para o login
    if (adminViews.includes(activeView) && !currentUser) {
      setActiveView('login');
    }
  }, [activeView, currentUser]);

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const password = (formData.get('password') as string || '').trim();

    if (password === ADMIN_PASSWORD) {
      const admin = users.find(u => u.role === 'admin') || users[0];
      setCurrentUser(admin);
      setActiveView('dashboard');
    } else {
      alert("Senha incorreta. Tente novamente.");
    }
  };

  // Função de Logout corrigida para ação imediata e segura
  const handleLogout = useCallback(() => {
    // 1. Muda a view primeiro para evitar o check do useEffect que redireciona para /login
    setActiveView('landing');
    // 2. Limpa o estado do usuário
    setCurrentUser(null);
    // 3. Limpa o storage explicitamente
    localStorage.removeItem('barberpro_current_user');
    // 4. Fecha a sidebar se estiver no mobile
    setIsSidebarOpen(false);
  }, []);

  const totalRevenue = bookings
    .filter(b => b.status === 'confirmed')
    .reduce((acc, curr) => {
      const service = services.find(s => s.id === curr.serviceId);
      return acc + (service?.price || 0);
    }, 0);

  const pendingCount = bookings.filter(b => b.status === 'pending').length;
  const upcomingCount = bookings.filter(b => b.status !== 'cancelled').length;

  const addService = (s: Service) => setServices(prev => [...prev, s]);
  const updateService = (updated: Service) => setServices(prev => prev.map(s => s.id === updated.id ? updated : s));
  const deleteService = (id: string) => setServices(prev => prev.filter(s => s.id !== id));

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert("Agendamento solicitado com sucesso!");
    }
  };

  const confirmBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'confirmed' } : b));
  const cancelBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' } : b));
  const deleteBooking = (id: string) => setBookings(prev => prev.filter(b => b.id !== id));

  if (activeView === 'landing') return <LandingPage services={services} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => currentUser ? setActiveView('dashboard') : setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase transition-colors">
          <ArrowLeft size={16} /> VOLTAR AO INÍCIO
        </button>
        <div className="text-center mb-8">
          <div className="inline-flex p-3 bg-amber-500 rounded-xl mb-4 text-slate-950"><Lock size={24} /></div>
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">ACESSO <span className="text-amber-500">RESTRITO</span></h2>
          <p className="text-slate-500 text-[10px] font-black mt-2 uppercase tracking-widest">Insira a senha de mestre para gerenciar</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <div className="relative">
             <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-500">
                <Lock size={18} />
             </div>
             <input name="password" type="password" placeholder="Senha de Acesso" required className="w-full bg-slate-800 border border-slate-700 text-white pl-12 pr-4 py-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-bold tracking-widest" />
          </div>
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400 transition-all uppercase tracking-widest text-sm shadow-xl">ENTRAR NO PAINEL</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4 md:p-8">
      <div className="w-full max-w-2xl bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 md:p-12 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-5">
          <CalendarDays size={200} className="text-white" />
        </div>

        <button 
          onClick={() => setActiveView('landing')} 
          className="relative z-10 flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-10 font-black text-xs uppercase tracking-widest transition-colors"
        >
          <ArrowLeft size={18} /> VOLTAR PARA O SITE
        </button>

        <div className="relative z-10 mb-12">
          <h2 className="text-3xl md:text-5xl font-black text-white mb-4 italic tracking-tighter uppercase leading-none">
            AGENDE SEU <br/><span className="text-amber-500">NOVO VISUAL</span>
          </h2>
          <p className="text-slate-400 text-xs md:text-sm font-medium italic">Reserve seu lugar com os mestres da navalha. Escolha o serviço e o melhor horário para você.</p>
        </div>

        <form onSubmit={(e) => {
          e.preventDefault();
          const formData = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: formData.get('name') as string,
            clientEmail: formData.get('email') as string,
            serviceId: formData.get('service') as string,
            date: formData.get('date') as string,
            time: formData.get('time') as string,
            status: 'pending'
          });
        }} className="relative z-10 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-[0.2em]">Seu Nome</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-600">
                  <UserIcon size={18} />
                </div>
                <input name="name" type="text" placeholder="Nome completo" required className="w-full bg-slate-800/50 border border-slate-700 text-white pl-12 pr-4 py-4 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-medium" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-[0.2em]">E-mail para Confirmação</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-600">
                  <Mail size={18} />
                </div>
                <input name="email" type="email" placeholder="seu@email.com" required className="w-full bg-slate-800/50 border border-slate-700 text-white pl-12 pr-4 py-4 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-medium" />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-[0.2em]">Serviço Desejado</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-600">
                <Scissors size={18} />
              </div>
              <select name="service" required className="w-full bg-slate-800/50 border border-slate-700 text-white pl-12 pr-10 py-4 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 appearance-none font-bold italic transition-all">
                {services.map(s => <option key={s.id} value={s.id} className="bg-slate-900">{s.name} — R$ {s.price.toFixed(2)}</option>)}
              </select>
              <div className="absolute inset-y-0 right-0 pr-4 flex items-center pointer-events-none text-slate-500">
                <ChevronRight size={20} className="rotate-90" />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-[0.2em]">Data</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-600">
                  <Calendar size={18} />
                </div>
                <input name="date" type="date" required className="w-full bg-slate-800/50 border border-slate-700 text-white pl-12 pr-4 py-4 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-medium [color-scheme:dark]" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-[0.2em]">Melhor Horário</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-600">
                  <Clock size={18} />
                </div>
                <input name="time" type="time" required className="w-full bg-slate-800/50 border border-slate-700 text-white pl-12 pr-4 py-4 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 transition-all font-medium [color-scheme:dark]" />
              </div>
            </div>
          </div>

          <button type="submit" className="w-full py-6 bg-amber-500 text-slate-950 font-black rounded-2xl hover:bg-amber-400 transition-all text-sm md:text-base shadow-2xl shadow-amber-500/20 uppercase tracking-[0.25em] mt-10 active:scale-95">
            SOLICITAR AGENDAMENTO
          </button>

          <p className="text-center text-slate-600 text-[9px] uppercase font-bold tracking-widest mt-6">
            Você receberá uma confirmação por e-mail após a aprovação.
          </p>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-lg text-slate-950 shadow-lg shadow-amber-500/20"><Scissors size={20} /></div>
              <h1 className="text-lg font-black italic text-slate-900 tracking-tighter uppercase">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button className="lg:hidden text-slate-400" onClick={() => setIsSidebarOpen(false)}><X size={20} /></button>
          </div>
          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Sparkles size={20} />} label="IA Assistant" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-100">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all text-xs font-black uppercase tracking-widest group">
              <LogOut size={20} className="group-hover:-translate-x-1 transition-transform" /> SAIR
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-4 md:px-6 bg-white border-b border-slate-200 shrink-0">
          <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-lg" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="flex-1" />
          <div className="flex items-center gap-3">
            <div className="text-right hidden sm:block">
              <p className="text-xs font-black uppercase italic text-slate-900 leading-none">{currentUser?.name}</p>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Administrador Master</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-900 text-amber-500 flex items-center justify-center font-black border-2 border-amber-500 uppercase shadow-sm">{currentUser?.name?.charAt(0)}</div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          {activeView === 'dashboard' && <DashboardView revenue={totalRevenue} pending={pendingCount} upcoming={upcomingCount} serviceCount={services.length} recent={bookings.slice(-8).reverse()} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onNavigate={setActiveView} />}
          {activeView === 'services' && <ServicesView services={services} onAdd={addService} onEdit={updateService} onDelete={deleteService} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onDelete={deleteBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} />}
        </div>
      </main>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all text-[11px] font-black uppercase tracking-widest ${active ? 'bg-amber-500 text-slate-950 shadow-lg shadow-amber-500/10' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
    {icon} {label}
  </button>
);

const StatCard = ({ label, value, icon, color = "amber" }: any) => {
  const colors: any = {
    amber: 'text-amber-500 bg-amber-50 border-amber-100',
    green: 'text-green-500 bg-green-50 border-green-100',
    blue: 'text-blue-500 bg-blue-50 border-blue-100',
    indigo: 'text-indigo-500 bg-indigo-50 border-indigo-100'
  };
  return (
    <div className="bg-white p-6 rounded-3xl border border-slate-200 flex justify-between items-center hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
      <div>
        <p className="text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest leading-none">{label}</p>
        <h4 className="text-xl md:text-2xl font-black italic text-slate-900">{value}</h4>
      </div>
      <div className={`p-4 rounded-2xl border ${colors[color]} shadow-sm shrink-0 ml-2`}>{icon}</div>
    </div>
  );
};

const DashboardView = ({ revenue, pending, upcoming, serviceCount, recent, services, onConfirm, onCancel, onNavigate }: any) => (
  <div className="space-y-8 max-w-7xl mx-auto">
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
      <StatCard label="Receita Confirmada" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={22} />} color="green" />
      <StatCard label="Solicitações Pendentes" value={pending.toString()} icon={<TrendingUp size={22} />} color="amber" />
      <StatCard label="Agenda Ativa" value={upcoming.toString()} icon={<Calendar size={22} />} color="blue" />
      <StatCard label="Serviços Oferecidos" value={serviceCount.toString()} icon={<Scissors size={22} />} color="indigo" />
    </div>

    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 bg-white p-6 md:p-8 rounded-[2rem] border border-slate-200 shadow-sm relative overflow-hidden">
        <div className="flex items-center justify-between mb-8">
          <h3 className="font-black text-xs uppercase tracking-[0.2em] text-slate-400 italic">Atividade Recente</h3>
          <span className="flex items-center gap-2 text-[9px] font-black bg-slate-900 text-amber-500 px-3 py-1.5 rounded-full uppercase tracking-widest">
            <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" /> Live Feed
          </span>
        </div>

        <div className="space-y-4">
          {recent.length === 0 ? (
            <div className="text-center py-20 bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-100">
               <CalendarDays className="mx-auto text-slate-200 mb-4" size={56} />
               <p className="text-slate-400 font-black italic text-sm uppercase tracking-widest">Nenhuma atividade registrada.</p>
            </div>
          ) : (
            recent.map((b: any) => (
              <div key={b.id} className="group flex flex-col sm:flex-row items-start sm:items-center justify-between p-5 bg-slate-50/50 rounded-2xl border border-slate-100 hover:border-amber-300 transition-all duration-300 gap-4">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-xl bg-slate-900 flex items-center justify-center text-amber-500 font-black shadow-lg border-2 border-amber-500/10 shrink-0">
                    {b.clientName?.charAt(0)}
                  </div>
                  <div className="min-w-0">
                    <span className="text-sm font-black italic block text-slate-900 uppercase tracking-tight truncate">{b.clientName}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex flex-wrap items-center gap-1.5">
                      <span className="text-amber-600 italic font-black">{services.find((s:any) => s.id === b.serviceId)?.name}</span>
                      <span className="opacity-20">•</span>
                      <span>{b.date.split('-').reverse().join('/')} @ {b.time}</span>
                    </span>
                  </div>
                </div>
                <div className="flex items-center gap-3 w-full sm:w-auto justify-end">
                  <div className="flex items-center gap-2">
                    {b.status === 'pending' && (
                      <button onClick={() => onConfirm(b.id)} className="p-2.5 bg-green-500 text-white rounded-xl shadow-lg shadow-green-500/20 hover:bg-green-600 transition-all transform active:scale-90">
                        <Check size={18} />
                      </button>
                    )}
                    {b.status !== 'cancelled' && (
                      <button onClick={() => onCancel(b.id)} className="p-2.5 bg-white border border-slate-200 text-slate-400 rounded-xl hover:bg-red-500 hover:text-white hover:border-red-500 transition-all transform active:scale-90">
                        <X size={18} />
                      </button>
                    )}
                  </div>
                  <span className={`text-[9px] font-black uppercase px-3.5 py-2 rounded-xl border shadow-sm ${
                    b.status === 'confirmed' ? 'bg-green-50 text-green-700 border-green-200' : 
                    b.status === 'cancelled' ? 'bg-red-50 text-red-700 border-red-200' : 
                    'bg-amber-50 text-amber-700 border-amber-200'
                  }`}>{b.status}</span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      <div className="bg-slate-900 p-8 rounded-[2rem] border-t-8 border-amber-500 text-white flex flex-col justify-between shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-4 opacity-5 translate-x-1/4 -translate-y-1/4 group-hover:translate-x-0 group-hover:translate-y-0 transition-transform duration-700">
           <Sparkles size={160} />
        </div>
        <div className="space-y-6 relative z-10">
          <div className="p-4 bg-amber-500 rounded-2xl text-slate-950 w-fit shadow-xl shadow-amber-500/20 transform -rotate-3"><Sparkles size={32} /></div>
          <h4 className="text-2xl font-black italic uppercase tracking-tighter leading-none">Insight da <br/><span className="text-amber-500">Inteligência Artificial</span></h4>
          <p className="text-slate-400 text-xs italic leading-relaxed font-medium">"Notamos que seus clientes de barbearia preferem horários matinais. Que tal um combo 'Coffee & Cut' para as segundas-feiras?"</p>
        </div>
        <button onClick={() => onNavigate('ai-assistant')} className="w-full py-5 mt-10 bg-amber-500 text-slate-950 font-black rounded-2xl hover:bg-amber-400 transition-all uppercase tracking-[0.2em] text-[11px] shadow-xl shadow-amber-500/20 active:scale-95 relative z-10">
          SOLICITAR ANÁLISE IA
        </button>
      </div>
    </div>
  </div>
);

const ServicesView = ({ services, onAdd, onEdit, onDelete }: any) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form, setForm] = useState<any>({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    if (editing) setForm(editing);
    else setForm({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  }, [editing, isModalOpen]);

  const handleSuggest = async () => {
    if (!form.name) {
      alert("Informe o nome do serviço para gerar uma descrição.");
      return;
    }
    setLoadingAI(true);
    try {
      const desc = await generateServiceDescription(form.name, form.category);
