        {services.map((s: any) => (
          <div key={s.id} className="bg-slate-900 border border-slate-800 p-8 rounded-[2rem] hover:border-amber-500 hover:shadow-2xl hover:shadow-amber-500/5 transition-all duration-300 group relative overflow-hidden">
