                <button onClick={() => onDelete(s.id)} className="p-2.5 bg-slate-800 text-slate-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all"><Trash2 size={18} /></button>
              </div>
            </div>
            <h3 className="font-black italic text-2xl mb-3 uppercase tracking-tight group-hover:text-amber-500 transition-colors leading-none truncate text-white">{s.name}</h3>
            <p className="text-xs text-slate-500 italic mb-10 h-16 overflow-hidden leading-relaxed font-medium">{s.description}</p>
            <div className="flex justify-between items-center pt-8 border-t border-slate-800">
              <span className="text-[10px] font-black uppercase text-slate-500 flex items-center gap-2 tracking-[0.1em]">
                <Clock size={16} className="text-amber-500" /> {s.duration} MINUTOS
