            </div>
            <div className="p-6 md:p-10 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-widest">Nome do Serviço BarberPro</label>
                <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="Ex: Master Fade Specialist" className="w-full p-4 md:p-5 border border-slate-800 bg-slate-950/50 rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-black text-white italic" />
