                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-500 ml-1 tracking-widest">Minutos</label>
                  <input type="number" value={form.duration} onChange={e => setForm({...form, duration: parseInt(e.target.value)})} placeholder="45" className="w-full p-4 md:p-5 border border-slate-800 bg-slate-950/50 rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-black text-white" />
