                   <button onClick={handleSuggest} disabled={loadingAI} className="text-[10px] font-black uppercase text-amber-500 flex items-center gap-1.5 hover:text-amber-400 transition-colors disabled:opacity-50">
                     <Sparkles size={14} className={loadingAI ? 'animate-spin' : ''} /> {loadingAI ? '...' : 'GERAR IA BARBERPRO'}
                   </button>
                </div>
                <textarea value={form.description} onChange={e => setForm({...form, description: e.target.value})} placeholder="Destaque seus diferenciais BarberPro..." className="w-full p-4 md:p-6 border border-slate-800 bg-slate-950/50 rounded-3xl h-32 md:h-36 resize-none outline-none focus:ring-4 focus:ring-amber-500/10 transition-all italic text-sm text-slate-400 leading-relaxed font-medium" />
              </div>

              <button onClick={() => {
                if (editing) onEdit({...form, id: editing.id});
                else onAdd({...form, id: `s${Date.now()}`});
                setIsModalOpen(false);
              }} className="w-full py-5 md:py-6 bg-amber-500 text-slate-950 rounded-3xl font-black uppercase tracking-[0.3em] text-[11px] hover:bg-amber-400 transition-all shadow-2xl mt-4 transform active:scale-95">
                SALVAR ALTERAÇÕES BARBERPRO
