const AIAssistantView = ({ services }: any) => {
  const [prompt, setPrompt] = useState("");
  const [res, setRes] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const data = await askExpertAssistant(prompt, services.map((s: any) => s.name));
      setRes(data);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-6 md:py-10 space-y-12 px-2 md:px-4">
      <div className="text-center space-y-4">
        <div className="inline-flex p-5 md:p-6 bg-slate-900 rounded-[2.5rem] text-amber-500 mb-4 md:mb-6 border-2 border-amber-500/20 shadow-2xl animate-pulse">
          <Sparkles size={40} className="md:w-12 md:h-12" />
        </div>
        <h2 className="text-3xl md:text-4xl font-black italic uppercase tracking-tighter leading-none text-white">CONSULTORIA <span className="text-amber-500">BARBERPRO</span> IA</h2>
        <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.3em] px-4">Otimize sua barbearia BarberPro com inteligência artificial</p>
      </div>
      <div className="bg-slate-900 p-6 md:p-10 rounded-[2.5rem] md:rounded-[3rem] border border-slate-800 shadow-xl space-y-8 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12 hidden md:block">
           <LayoutDashboard size={200} className="text-white" />
        </div>
        <div className="relative z-10 space-y-4">
          <label className="text-[10px] font-black uppercase text-slate-500 ml-3 tracking-widest">Sua Dúvida BarberPro</label>
          <textarea 
            className="w-full p-6 md:p-8 bg-slate-950 border border-slate-800 rounded-[2rem] md:rounded-[2.5rem] h-40 md:h-44 italic focus:ring-8 focus:ring-amber-500/5 transition-all outline-none leading-relaxed text-slate-300 shadow-inner resize-none" 
            placeholder="Ex: Como posso aumentar o ticket médio da minha BarberPro?" 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)} 
          />
        </div>
        <button 
          onClick={handleAsk} 
          disabled={loading || !prompt} 
          className="w-full py-5 md:py-6 bg-amber-500 text-slate-950 font-black uppercase tracking-[0.3em] text-[10px] md:text-xs rounded-2xl md:rounded-3xl hover:bg-amber-400 transition-all shadow-2xl disabled:opacity-50 active:scale-95 group relative z-10"
        >
          {loading ? 'ANALISANDO DADOS...' : 'SOLICITAR CONSULTORIA BARBERPRO'}
        </button>
        {res && (
          <div className="p-6 md:p-10 bg-slate-950 text-white rounded-[2rem] md:rounded-[2.5rem] border-l-8 border-amber-500 animate-in slide-in-from-bottom-6 duration-1000 italic leading-relaxed whitespace-pre-wrap relative z-10 shadow-2xl text-sm md:text-base">
            <div className="flex items-center gap-3 text-amber-500 font-black mb-6 text-[11px] uppercase tracking-[0.2em]">
               <Sparkles size={18} /> RELATÓRIO ESPECIALISTA BARBERPRO
            </div>
            {res}
          </div>
        )}
      </div>
    </div>
  );
};

