    return () => clearTimeout(timer);
  }, [onClose]);

  const isConfirmed = booking.status === 'confirmed';
  const title = isConfirmed ? 'Agendamento Confirmado!' : 'Novo Agendamento!';
  const Icon = isConfirmed ? CheckCircle2 : Bell;
  const colorClass = isConfirmed ? 'text-green-500 border-green-500' : 'text-amber-500 border-amber-500';
  const bgClass = isConfirmed ? 'bg-green-500' : 'bg-amber-500';

  return (
    <div className="fixed top-20 right-4 z-[100] animate-in slide-in-from-right-full duration-500">
      <div className={`bg-slate-900 border-2 ${colorClass} shadow-2xl p-6 rounded-2xl max-w-sm flex items-start gap-4 backdrop-blur-md`}>
        <div className={`p-3 ${bgClass} rounded-xl text-slate-950 shrink-0 animate-bounce`}>
          <Icon size={24} />
