const AIAssistantView = ({ services }: any) => {
  const [prompt, setPrompt] = useState("");
  const [res, setRes] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const data = await askExpertAssistant(prompt, services.map((s: any) => s.name));
      setRes(data);
    } catch (e) {
      alert("Erro ao consultar a IA.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-6 md:py-10 space-y-12 px-2 md:px-4">
      <div className="text-center space-y-4">
        <div className="inline-flex p-5 md:p-6 bg-slate-900 rounded-[2.5rem] text-amber-500 mb-4 md:mb-6 border-2 border-amber-500/20 shadow-2xl animate-pulse">
          <Sparkles size={40} className="md:w-12 md:h-12" />
        </div>
        <h2 className="text-3xl md:text-4xl font-black italic uppercase tracking-tighter leading-none text-white">CONSULTORIA <span className="text-amber-500">BARBERPRO</span> IA</h2>
      </div>
      <div className="bg-slate-900 p-6 md:p-10 rounded-[2.5rem] border border-slate-800 shadow-xl space-y-8">
        <textarea 
          className="w-full p-6 md:p-8 bg-slate-950 border border-slate-800 rounded-[2rem] h-40 italic focus:ring-8 focus:ring-amber-500/5 transition-all outline-none text-slate-300 resize-none" 
          placeholder="Como posso melhorar meu lucro?" 
          value={prompt} 
          onChange={e => setPrompt(e.target.value)} 
        />
        <button 
          onClick={handleAsk} 
          disabled={loading || !prompt} 
          className="w-full py-5 md:py-6 bg-amber-500 text-slate-950 font-black uppercase tracking-[0.3em] rounded-2xl md:rounded-3xl hover:bg-amber-400 transition-all shadow-2xl disabled:opacity-50"
        >
          {loading ? 'ANALISANDO...' : 'SOLICITAR CONSULTORIA'}
        </button>
        {res && (
          <div className="p-6 md:p-10 bg-slate-950 text-white rounded-[2rem] border-l-8 border-amber-500 animate-in slide-in-from-bottom-6 italic leading-relaxed whitespace-pre-wrap">
            {res}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const ADMIN_PASSWORD = "1966";

  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_users');
      const parsed = saved ? JSON.parse(saved) : [];
      const userList = Array.isArray(parsed) ? parsed : [];
      if (!userList.find((u: User) => u.role === 'admin')) {
        const masterAdmin: User = {
          id: 'admin-master',
          name: 'Administrador',
          email: 'admin@sistema.com',
          password: ADMIN_PASSWORD,
          role: 'admin',
          createdAt: new Date().toISOString()
        };
        const newUsers = [masterAdmin, ...userList];
        localStorage.setItem('barberpro_users', JSON.stringify(newUsers));
        return newUsers;
      }
      return userList;
    } catch (e) { return []; }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('barberpro_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [services, setServices] = useState<Service[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_services');
      const parsed = saved ? JSON.parse(saved) : INITIAL_SERVICES;
      return Array.isArray(parsed) ? parsed : INITIAL_SERVICES;
    } catch (e) { return INITIAL_SERVICES; }
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_bookings');
      const parsed = saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
      return Array.isArray(parsed) ? parsed : INITIAL_BOOKINGS;
    } catch (e) { return INITIAL_BOOKINGS; }
  });

  const [team, setTeam] = useState<TeamMember[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_team');
      const parsed = saved ? JSON.parse(saved) : INITIAL_TEAM;
      return Array.isArray(parsed) ? parsed : INITIAL_TEAM;
    } catch (e) { return INITIAL_TEAM; }
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [lastNotification, setLastNotification] = useState<Booking | null>(null);

  useEffect(() => { localStorage.setItem('barberpro_users', JSON.stringify(users)); }, [users]);
  useEffect(() => { 
    if (currentUser) localStorage.setItem('barberpro_current_user', JSON.stringify(currentUser));
    else localStorage.removeItem('barberpro_current_user');
  }, [currentUser]);
  useEffect(() => { localStorage.setItem('barberpro_services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)); }, [bookings]);
  useEffect(() => { localStorage.setItem('barberpro_team', JSON.stringify(team)); }, [team]);

  useEffect(() => {
    const adminViews: ViewType[] = ['dashboard', 'services', 'bookings', 'ai-assistant'];
    if (adminViews.includes(activeView) && !currentUser) setActiveView('login');
  }, [activeView, currentUser]);

  const playNotification = useCallback(() => {
    try {
      const audio = new Audio(NOTIFICATION_SOUND_URL);
      audio.play().catch(e => console.warn("Audio error", e));
    } catch (error) { console.error("Sound error", error); }
  }, []);

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    playNotification();
    setLastNotification(b);
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert(`Agendamento realizado para ${b.clientName}!`);
    }
  };

  const confirmBooking = (id: string) => {
    setBookings(prev => {
      const updated = prev.map(b => b.id === id ? { ...b, status: 'confirmed' as const } : b);
      const confirmedOne = updated.find(b => b.id === id);
      if (confirmedOne) {
        playNotification();
        setLastNotification(confirmedOne);
      }
      return updated;
    });
  };

  const cancelBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' as const } : b));
  const deleteBooking = (id: string) => setBookings(prev => prev.filter(b => b.id !== id));

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if ((formData.get('password') as string) === ADMIN_PASSWORD) {
      setCurrentUser(users[0]);
      setActiveView('dashboard');
    } else alert("Senha incorreta.");
  };

  if (activeView === 'landing') return <LandingPage services={services} team={team} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => currentUser ? setActiveView('dashboard') : setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-8 font-black text-[10px] tracking-widest uppercase">
          <ArrowLeft size={16} /> VOLTAR
        </button>
        <h2 className="text-2xl font-black text-white italic text-center uppercase mb-8">ACESSO ADMIN</h2>
        <form onSubmit={handleLogin} className="space-y-4">
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400">ENTRAR</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-screen flex items-center justify-center p-4 md:p-8">
      <div className="w-full max-w-2xl bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="flex items-center gap-2 text-slate-500 hover:text-amber-500 mb-10 font-black text-xs uppercase">
          <ArrowLeft size={18} /> VOLTAR
        </button>
        <h2 className="text-3xl font-black text-white mb-8 italic uppercase leading-none">NOVO AGENDAMENTO</h2>
        <form onSubmit={(e) => {
          e.preventDefault();
          const fd = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: fd.get('name') as string,
            clientEmail: fd.get('email') as string,
            serviceId: fd.get('service') as string,
            date: fd.get('date') as string,
            time: fd.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-6">
          <input name="name" type="text" placeholder="Nome" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none" />
          <select name="service" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none">
            {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
          </select>
          <div className="grid grid-cols-2 gap-4">
            <input name="date" type="date" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none" />
            <input name="time" type="time" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none" />
          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest mt-6">RESERVAR AGORA</button>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-slate-950 overflow-hidden relative">
      {lastNotification && (
        <BookingToast 
          booking={lastNotification} 
          service={services.find(s => s.id === lastNotification.serviceId)} 
          onClose={() => setLastNotification(null)} 
        />
      )}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 border-r border-slate-800 transform lg:translate-x-0 lg:static transition-transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-lg text-slate-950"><Scissors size={20} /></div>
              <h1 className="text-lg font-black italic text-white uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
          </div>
          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => setActiveView('services')} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda" active={activeView === 'bookings'} onClick={() => setActiveView('bookings')} />
            <SidebarLink icon={<Sparkles size={20} />} label="Consultoria IA" active={activeView === 'ai-assistant'} onClick={() => setActiveView('ai-assistant')} />
          </nav>
          <button onClick={() => { setCurrentUser(null); setActiveView('landing'); }} className="flex items-center gap-3 p-3 text-slate-400 hover:text-red-500 uppercase font-black text-[11px] tracking-widest"><LogOut size={20} /> SAIR</button>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 bg-slate-900 border-b border-slate-800 shrink-0">
          <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="hidden lg:flex items-center gap-2 text-slate-500">
            <Bell size={18} className="text-amber-500 animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-widest">Painel Administrativo Ativo</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="text-right hidden sm:block">
              <p className="text-xs font-black uppercase italic text-white leading-none">Admin</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-800 text-amber-500 flex items-center justify-center font-black border-2 border-amber-500">A</div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-950">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={bookings.filter(b => b.status === 'confirmed').reduce((acc, curr) => acc + (services.find(s => s.id === curr.serviceId)?.price || 0), 0)} 
              pending={bookings.filter(b => b.status === 'pending').length} 
              upcoming={bookings.filter(b => b.status !== 'cancelled').length} 
              serviceCount={services.length} 
              recent={bookings.slice(-8).reverse()} 
              services={services} 
              onConfirm={confirmBooking} 
              onCancel={cancelBooking} 
              onNavigate={setActiveView} 
            />
          )}
          {activeView === 'services' && <ServicesView services={services} onAdd={(s: Service) => setServices(p => [...p, s])} onEdit={(up: Service) => setServices(p => p.map(s => s.id === up.id ? up : s))} onDelete={(id: string) => setServices(p => p.filter(s => s.id !== id))} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onDelete={deleteBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} />}
        </div>
      </main>
    </div>
  );
};

export default App;

