const BookingToast = ({ booking, service, onClose }: { booking: Booking, service?: Service, onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 6000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const isConfirmed = booking.status === 'confirmed';
  const Icon = isConfirmed ? CheckCircle2 : Bell;

  return (
    <div className="fixed top-20 right-4 z-[100] animate-in slide-in-from-right-full duration-500">
      <div className={`bg-slate-900 border-2 ${isConfirmed ? 'border-green-500' : 'border-amber-500'} shadow-2xl p-6 rounded-2xl max-w-sm flex items-start gap-4 backdrop-blur-md`}>
        <div className={`p-3 ${isConfirmed ? 'bg-green-500' : 'bg-amber-500'} rounded-xl text-slate-950 shrink-0 animate-bounce`}>
          <Icon size={24} />
        </div>
        <div className="flex-1">
          <div className="flex justify-between items-start mb-1">
            <h4 className={`${isConfirmed ? 'text-green-500' : 'text-amber-500'} font-black italic uppercase text-[10px] tracking-widest`}>
              {isConfirmed ? 'AGENDAMENTO CONFIRMADO' : 'NOVA SOLICITAÇÃO'}
            </h4>
            <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors"><X size={16} /></button>
          </div>
          <p className="text-white font-bold text-sm mb-1">{booking.clientName}</p>
          <p className="text-slate-400 text-[10px] uppercase font-black tracking-wider mb-3 italic">
            {service?.name || 'Serviço'}
          </p>
          <div className="flex items-center justify-between bg-slate-950 p-3 rounded-xl border border-slate-800">
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Valor:</span>
            <span className={`${isConfirmed ? 'text-green-500' : 'text-amber-500'} font-black italic text-lg`}>
              R$ {(service?.price || 0).toFixed(2)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

