    if (editing) setForm(editing);
    else setForm({ name: '', price: 0, duration: 30, description: '', category: CATEGORIES[0] });
  }, [editing, isModalOpen]);

  const handleSuggest = async () => {
    if (!form.name) return;
    setLoadingAI(true);
    try {
      const desc = await generateServiceDescription(form.name, form.category);
      setForm({ ...form, description: desc });
    } finally {
      setLoadingAI(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-2xl font-black italic uppercase tracking-tighter text-white">Catálogo de <span className="text-amber-500">Serviços</span></h2>
        <button onClick={() => { setEditing(null); setIsModalOpen(true); }} className="px-8 py-4 bg-amber-500 text-slate-950 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-2xl hover:bg-amber-400 transition-all transform active:scale-95">
          <Plus size={20} /> NOVO SERVIÇO
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
        {services.map((s: any) => (
          <div key={s.id} className="bg-slate-900 border border-slate-800 p-8 rounded-[2rem] hover:border-amber-500 transition-all duration-300 group">
            <div className="flex justify-between items-start mb-6">
              <span className="text-[10px] font-black uppercase text-amber-500 bg-amber-500/10 px-3 py-1.5 rounded-xl border border-amber-500/20 italic">{s.category}</span>
              <div className="flex gap-2">
                <button onClick={() => { setEditing(s); setIsModalOpen(true); }} className="p-2.5 bg-slate-800 text-slate-500 hover:text-amber-500 rounded-xl transition-all"><Edit2 size={18} /></button>
                <button onClick={() => onDelete(s.id)} className="p-2.5 bg-slate-800 text-slate-500 hover:text-red-500 rounded-xl transition-all"><Trash2 size={18} /></button>
              </div>
            </div>
            <h3 className="font-black italic text-2xl mb-3 uppercase text-white truncate">{s.name}</h3>
