            <div className="flex justify-between items-center pt-8 border-t border-slate-800">
              <span className="text-[10px] font-black uppercase text-slate-500 flex items-center gap-2 tracking-[0.1em]">
                <Clock size={16} className="text-amber-500" /> {s.duration} MIN
              </span>
              <span className="text-xl font-black text-amber-500 italic">R$ {s.price?.toFixed(2)}</span>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md">
          <div className="bg-slate-900 w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-800">
            <div className="p-6 md:p-8 bg-slate-950 text-white flex justify-between items-center border-b border-slate-800">
              <h3 className="font-black italic uppercase text-lg tracking-widest">{editing ? 'Editar' : 'Novo'} Serviço</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-3 bg-white/5 rounded-2xl hover:text-amber-500 transition-colors text-slate-400"><X size={24} /></button>
            </div>
            <div className="p-6 md:p-10 space-y-6">
