const AIAssistantView = ({ services }: any) => {
  const [prompt, setPrompt] = useState("");
  const [res, setRes] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const data = await askExpertAssistant(prompt, services.map((s: any) => s.name));
      setRes(data);
    } catch (e) {
      alert("Erro ao consultar a IA.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-10 space-y-12">
      <div className="text-center space-y-4">
        <div className="inline-flex p-6 bg-slate-900 rounded-[2.5rem] text-amber-500 mb-6 border-2 border-amber-500/20 shadow-2xl animate-pulse">
          <Sparkles size={40} />
        </div>
        <h2 className="text-4xl font-black italic uppercase tracking-tighter leading-none text-white">CONSULTORIA <span className="text-amber-500">BARBERPRO</span> IA</h2>
      </div>
      <div className="bg-slate-900 p-10 rounded-[2.5rem] border border-slate-800 shadow-xl space-y-8">
        <textarea 
          className="w-full p-8 bg-slate-950 border border-slate-800 rounded-[2rem] h-40 italic focus:ring-8 focus:ring-amber-500/5 transition-all outline-none text-slate-300 resize-none" 
          placeholder="Como posso melhorar o ticket médio da minha barbearia?" 
          value={prompt} 
          onChange={e => setPrompt(e.target.value)} 
        />
        <button 
          onClick={handleAsk} 
          disabled={loading || !prompt} 
          className="w-full py-6 bg-amber-500 text-slate-950 font-black uppercase tracking-[0.3em] rounded-3xl hover:bg-amber-400 transition-all shadow-2xl disabled:opacity-50"
        >
          {loading ? 'ANALISANDO...' : 'SOLICITAR CONSULTORIA'}
        </button>
        {res && (
          <div className="p-10 bg-slate-950 text-white rounded-[2rem] border-l-8 border-amber-500 animate-in slide-in-from-bottom-6 italic leading-relaxed whitespace-pre-wrap">
            {res}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const ADMIN_PASSWORD = "1966";

  const [services, setServices] = useState<Service[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_services');
      return saved ? JSON.parse(saved) : INITIAL_SERVICES;
    } catch (e) { return INITIAL_SERVICES; }
  });

  const [bookings, setBookings] = useState<Booking[]>(() => {
    try {
      const saved = localStorage.getItem('barberpro_bookings');
      return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
    } catch (e) { return INITIAL_BOOKINGS; }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [lastNotification, setLastNotification] = useState<Booking | null>(null);

  useEffect(() => { localStorage.setItem('barberpro_services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)); }, [bookings]);

  const playNotification = useCallback(() => {
    try {
      const audio = new Audio(NOTIFICATION_SOUND_URL);
      audio.play().catch(() => {});
    } catch (e) {}
  }, []);

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    playNotification();
    setLastNotification(b);
    if (activeView === 'client-booking') {
      setActiveView('landing');
      alert(`Obrigado, ${b.clientName}! Seu agendamento foi solicitado.`);
    }
  };

  const confirmBooking = (id: string) => {
    setBookings(prev => {
      const updated = prev.map(b => b.id === id ? { ...b, status: 'confirmed' as const } : b);
      const confirmedOne = updated.find(b => b.id === id);
      if (confirmedOne) {
        playNotification();
        setLastNotification(confirmedOne);
      }
      return updated;
    });
  };

  const cancelBooking = (id: string) => setBookings(prev => prev.map(b => b.id === id ? { ...b, status: 'cancelled' as const } : b));
  const deleteBooking = (id: string) => setBookings(prev => prev.filter(b => b.id !== id));

