          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest mt-6">FINALIZAR AGENDAMENTO</button>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-slate-950 overflow-hidden relative">
      {lastNotification && (
        <BookingToast 
          booking={lastNotification} 
          service={services.find(s => s.id === lastNotification.serviceId)} 
          onClose={() => setLastNotification(null)} 
        />
      )}
