          </div>
          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => setActiveView('services')} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda" active={activeView === 'bookings'} onClick={() => setActiveView('bookings')} />
            <SidebarLink icon={<Sparkles size={20} />} label="Consultoria IA" active={activeView === 'ai-assistant'} onClick={() => setActiveView('ai-assistant')} />
          </nav>
          <button onClick={() => { setCurrentUser(null); setActiveView('landing'); }} className="flex items-center gap-3 p-3 text-slate-400 hover:text-red-500 uppercase font-black text-[11px] tracking-widest"><LogOut size={20} /> SAIR</button>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 bg-slate-900 border-b border-slate-800 shrink-0">
          <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="hidden lg:flex items-center gap-2 text-slate-500">
            <Bell size={18} className="text-amber-500 animate-pulse" />
            <span className="text-[10px] font-black uppercase tracking-widest">Painel Administrativo Ativo</span>
          </div>
          <div className="w-10 h-10 rounded-full bg-slate-800 text-amber-500 flex items-center justify-center font-black border-2 border-amber-500">A</div>
        </header>
        <div className="flex-1 overflow-y-auto p-8 bg-slate-950">
          {activeView === 'dashboard' && (
            <DashboardView 
              revenue={bookings.filter(b => b.status === 'confirmed').reduce((acc, curr) => acc + (services.find(s => s.id === curr.serviceId)?.price || 0), 0)} 
              pending={bookings.filter(b => b.status === 'pending').length} 
              upcoming={bookings.filter(b => b.status !== 'cancelled').length} 
              serviceCount={services.length} 
              recent={bookings.slice(-8).reverse()} 
              services={services} 
              onConfirm={confirmBooking} 
              onCancel={cancelBooking} 
              onNavigate={setActiveView} 
            />
          )}
          {activeView === 'services' && <ServicesView services={services} onAdd={(s: Service) => setServices(p => [...p, s])} onEdit={(up: Service) => setServices(p => p.map(s => s.id === up.id ? up : s))} onDelete={(id: string) => setServices(p => p.filter(s => s.id !== id))} />}
          {activeView === 'bookings' && <BookingsView bookings={bookings} services={services} onConfirm={confirmBooking} onCancel={cancelBooking} onDelete={deleteBooking} />}
          {activeView === 'ai-assistant' && <AIAssistantView services={services} />}
        </div>
      </main>
    </div>
  );
};

export default App;

