        <form onSubmit={(e) => {
          e.preventDefault();
          const pass = new FormData(e.currentTarget).get('password');
          if (pass === ADMIN_PASSWORD) {
            setCurrentUser({ id: '1', name: 'Admin', email: 'admin@barber.pro', role: 'admin', createdAt: '' });
            setActiveView('dashboard');
          } else alert("Senha incorreta");
        }} className="space-y-4">
          <div className="relative">
            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input name="password" type="password" placeholder="Senha Administrativa" required className="w-full bg-slate-800 border border-slate-700 text-white pl-12 p-4 rounded-xl outline-none focus:ring-2 focus:ring-amber-500" />
          </div>
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl hover:bg-amber-400">ENTRAR NO PAINEL</button>
        </form>
      </div>
    </div>
  );

