          <ArrowLeft size={18} /> VOLTAR
        </button>
        <h2 className="text-3xl font-black text-white mb-8 italic uppercase leading-none">RESERVE SEU HORÁRIO</h2>
        <form onSubmit={(e) => {
          e.preventDefault();
          const fd = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: fd.get('name') as string,
            clientEmail: fd.get('email') as string,
            serviceId: fd.get('service') as string,
            date: fd.get('date') as string,
            time: fd.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-6">
          <input name="name" type="text" placeholder="Seu Nome Completo" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-xl outline-none" />
