        </form>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-slate-950 overflow-hidden relative">
      {lastNotification && (
        <BookingToast 
          booking={lastNotification} 
          service={services.find(s => s.id === lastNotification.serviceId)} 
          onClose={() => setLastNotification(null)} 
        />
      )}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 border-r border-slate-800 transform lg:translate-x-0 lg:static transition-transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-2 mb-10 cursor-pointer" onClick={() => setActiveView('landing')}>
            <div className="p-2 bg-amber-500 rounded-lg text-slate-950"><Scissors size={20} /></div>
            <h1 className="text-lg font-black italic text-white uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
          </div>
          <nav className="flex-1 space-y-2">
            <SidebarLink icon={<LayoutDashboard size={20} />} label="Dashboard" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
            <SidebarLink icon={<Scissors size={20} />} label="Serviços" active={activeView === 'services'} onClick={() => setActiveView('services')} />
            <SidebarLink icon={<CalendarDays size={20} />} label="Agenda" active={activeView === 'bookings'} onClick={() => setActiveView('bookings')} />
            <SidebarLink icon={<Sparkles size={20} />} label="Consultoria IA" active={activeView === 'ai-assistant'} onClick={() => setActiveView('ai-assistant')} />
          </nav>
          <button onClick={() => { setCurrentUser(null); setActiveView('landing'); }} className="flex items-center gap-3 p-3 text-slate-400 hover:text-red-500 uppercase font-black text-[11px] tracking-widest"><LogOut size={20} /> SAIR</button>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 bg-slate-900 border-b border-slate-800 shrink-0">
          <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(true)}><Menu size={24} /></button>
          <div className="hidden lg:flex items-center gap-2 text-slate-500">
