  const [activeView, setActiveView] = useState<ViewType>('landing');
  const [services, setServices] = useState<Service[]>(() => {
    const s = localStorage.getItem('barberpro_services');
    return s ? JSON.parse(s) : INITIAL_SERVICES;
  });
  const [bookings, setBookings] = useState<Booking[]>(() => {
    const b = localStorage.getItem('barberpro_bookings');
    return b ? JSON.parse(b) : INITIAL_BOOKINGS;
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiChat, setAiChat] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [aiInput, setAiInput] = useState("");

  // Form states for adding service
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCategory, setNewServiceCategory] = useState(CATEGORIES[0]);
  const [newServicePrice, setNewServicePrice] = useState("50");
  const [newServiceDuration, setNewServiceDuration] = useState("45");
  const [newServiceDesc, setNewServiceDesc] = useState("");

  useEffect(() => localStorage.setItem('barberpro_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)), [bookings]);

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    setActiveView('landing');
    alert("Agendamento realizado com sucesso! Aguarde a confirmação via e-mail.");
  };

  const confirmBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'confirmed'} : b));
  const cancelBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'cancelled'} : b));
  const deleteBooking = (id: string) => setBookings(p => p.filter(b => b.id !== id));

  const handleAddService = (e: React.FormEvent) => {
    e.preventDefault();
    const service: Service = {
      id: `s${Date.now()}`,
      name: newServiceName,
      category: newServiceCategory,
      price: parseFloat(newServicePrice),
      duration: parseInt(newServiceDuration),
      description: newServiceDesc
    };
    setServices(prev => [...prev, service]);
    setNewServiceName("");
    setNewServiceDesc("");
    alert("Serviço adicionado ao catálogo!");
  };

  const deleteService = (id: string) => {
    if (confirm("Deseja realmente remover este serviço do catálogo?")) {
      setServices(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleGenerateAIDescription = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço para que a IA possa trabalhar!");
    setIsGeneratingDescription(true);
    const desc = await generateServiceDescription(newServiceName, newServiceCategory);
    setNewServiceDesc(desc);
    setIsGeneratingDescription(false);
  };

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!aiInput.trim()) return;
    const userMsg = aiInput;
    setAiInput("");
    setAiChat(p => [...p, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);
    const response = await askExpertAssistant(userMsg, services.map(s => s.name));
    setAiChat(p => [...p, { role: 'ai', content: response }]);
    setIsAiLoading(false);
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // Layout switcher
  if (activeView === 'landing') return <LandingPage services={services} team={INITIAL_TEAM} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-[2rem] p-8 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Voltar ao site
        </button>
        <div className="text-center mb-8">
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter">Login <span className="text-amber-500">Master</span></h2>
          <p className="text-slate-500 text-[10px] uppercase font-bold tracking-widest mt-2">Área Restrita Administrativa</p>
        </div>
        <form onSubmit={e => {
          e.preventDefault();
          const pass = new FormData(e.currentTarget).get('password');
          if (pass === "1966") setActiveView('dashboard');
          else alert("Acesso Negado: Senha Incorreta.");
        }} className="space-y-4">
          <input name="password" type="password" placeholder="Chave de Acesso" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-2xl outline-none focus:border-amber-500 transition-all placeholder:text-slate-600" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest shadow-xl shadow-amber-500/20 hover:bg-amber-400 transition-all flex items-center justify-center gap-2">
            Autenticar <ChevronRight size={18} />
          </button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Cancelar e Voltar
        </button>
        <h2 className="text-3xl font-black text-white italic uppercase mb-8 tracking-tighter leading-none">Reservar <span className="text-amber-500">Horário</span></h2>
        <form onSubmit={e => {
          e.preventDefault();
          const fd = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: fd.get('name') as string,
            clientEmail: fd.get('email') as string,
            serviceId: fd.get('service') as string,
            date: fd.get('date') as string,
            time: fd.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-5">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Nome Completo</label>
            <input name="name" placeholder="Como devemos te chamar?" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">E-mail para confirmação</label>
            <input name="email" type="email" placeholder="seu@email.com" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Escolha o Serviço</label>
            <select name="service" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all appearance-none">
              <option value="">Selecione...</option>
              {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Data</label>
              <input name="date" type="date" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Horário</label>
              <input name="time" type="time" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
            </div>
          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest shadow-xl hover:bg-amber-400 transition-all transform active:scale-95 mt-4">
            Solicitar Reserva
          </button>
        </form>
      </div>
    </div>
  );

  const revenue = bookings.filter(b => b.status === 'confirmed').reduce((a, c) => a + (services.find(s => s.id === c.serviceId)?.price || 0), 0);

  return (
    <div className="flex h-[100dvh] bg-slate-950 text-white overflow-hidden">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[60] lg:hidden"
          onClick={toggleSidebar}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-[70] w-72 bg-slate-900 border-r border-slate-800 
        lg:static lg:translate-x-0 transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-xl shadow-lg shadow-amber-500/20"><Scissors size={20} className="text-slate-950" /></div>
              <h1 className="text-xl font-black italic uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button onClick={toggleSidebar} className="lg:hidden p-2 text-slate-400"><X size={20}/></button>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18} />} label="Painel Inicial" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={18} />} label="Catálogo" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={18} />} label="Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Bot size={18} />} label="Consultor IA" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="pt-6 border-t border-slate-800">
            <button onClick={() => setActiveView('landing')} className="flex items-center gap-3 p-4 text-slate-500 hover:text-red-500 uppercase font-black text-[10px] tracking-widest transition-colors w-full rounded-xl">
              <LogOut size={18} /> Encerrar Sessão
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto relative">
        <header className="flex items-center justify-between lg:hidden p-4 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40 border-b border-slate-900">
          <button onClick={toggleSidebar} className="p-2 bg-slate-900 rounded-xl text-white"><Menu size={24}/></button>
          <h1 className="text-sm font-black italic uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
          <div className="w-10"></div> {/* Spacer for alignment */}
        </header>

        <div className="p-4 md:p-8 lg:p-12 max-w-7xl mx-auto">
          {activeView === 'dashboard' && (
            <div className="space-y-8 md:space-y-12">
              <div className="flex justify-between items-end">
                <div>
                  <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Administração</p>
                  <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter leading-none">PULSO DO <span className="text-amber-500">NEGÓCIO</span></h2>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                <StatCard label="Receita Bruta" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={20} />} color="green" />
                <StatCard label="Pendências" value={bookings.filter(b => b.status === 'pending').length.toString()} icon={<TrendingUp size={20} />} color="amber" />
                <StatCard label="Agendamentos" value={bookings.length.toString()} icon={<Calendar size={20} />} color="blue" />
                <StatCard label="Serviços" value={services.length.toString()} icon={<Scissors size={20} />} color="indigo" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8">
                <div className="bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-800 shadow-xl">
                  <h3 className="font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 mb-6 border-b border-slate-800 pb-4">Acesso Rápido</h3>
                  <div className="grid grid-cols-2 gap-3 md:gap-4">
                    <button onClick={() => setActiveView('services')} className="p-5 md:p-6 bg-slate-950 rounded-2xl border border-slate-800 hover:border-amber-500 transition-all text-center group">
                      <Plus className="mx-auto mb-2 text-amber-500 group-hover:scale-110 transition-transform" />
                      <span className="text-[9px] font-black uppercase tracking-widest block">Novo Serviço</span>
                    </button>
                    <button onClick={() => setActiveView('bookings')} className="p-5 md:p-6 bg-slate-950 rounded-2xl border border-slate-800 hover:border-amber-500 transition-all text-center group">
                      <CalendarDays className="mx-auto mb-2 text-blue-500 group-hover:scale-110 transition-transform" />
                      <span className="text-[9px] font-black uppercase tracking-widest block">Minha Agenda</span>
                    </button>
                  </div>
                </div>

                <div className="bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-800 shadow-xl">
                  <h3 className="font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 mb-6 border-b border-slate-800 pb-4">Próximas Solicitações</h3>
                  <div className="space-y-3">
                    {bookings.filter(b => b.status === 'pending').slice(0, 4).map(b => (
                      <div key={b.id} className="flex flex-wrap items-center justify-between p-4 bg-slate-950/50 rounded-2xl border border-slate-800 gap-3">
                        <div className="flex-1 min-w-[150px]">
                          <p className="font-bold text-sm uppercase italic leading-tight">{b.clientName}</p>
                          <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest mt-1">{services.find(s => s.id === b.serviceId)?.name} @ {b.time}</p>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => confirmBooking(b.id)} className="p-2.5 bg-green-500/10 text-green-500 rounded-xl hover:bg-green-500 hover:text-slate-950 transition-all"><Check size={16} /></button>
                          <button onClick={() => cancelBooking(b.id)} className="p-2.5 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><X size={16} /></button>
                        </div>
                      </div>
                    ))}
                    {bookings.filter(b => b.status === 'pending').length === 0 && (
                      <div className="text-center py-8 text-slate-600">
                        <Calendar size={32} className="mx-auto mb-3 opacity-20" />
                        <p className="text-[10px] font-black uppercase tracking-widest italic">Nenhum pendente agora.</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeView === 'services' && (
            <div className="space-y-10">
              <div>
                <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Gestão</p>
                <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">MEUS <span className="text-amber-500">SERVIÇOS</span></h2>
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Form to add service */}
                <div className="xl:col-span-1 bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-800 shadow-xl h-fit">
                  <h3 className="font-black text-[10px] uppercase tracking-[0.2em] text-slate-500 mb-8 border-b border-slate-800 pb-4">Adicionar Serviço</h3>
                  <form onSubmit={handleAddService} className="space-y-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Nome do Serviço</label>
                      <input value={newServiceName} onChange={e => setNewServiceName(e.target.value)} placeholder="Ex: Barboterapia" required className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Categoria</label>
                      <select value={newServiceCategory} onChange={e => setNewServiceCategory(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all appearance-none">
                        {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Valor (R$)</label>
                        <input type="number" value={newServicePrice} onChange={e => setNewServicePrice(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Duração (min)</label>
                        <input type="number" value={newServiceDuration} onChange={e => setNewServiceDuration(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <div className="flex justify-between items-center mb-1 px-1">
                        <label className="text-[10px] font-black uppercase text-slate-500">Descrição</label>
                        <button type="button" onClick={handleGenerateAIDescription} disabled={isGeneratingDescription} className="text-[9px] font-black uppercase text-amber-500 flex items-center gap-1 hover:text-amber-400 disabled:opacity-50">
                          {isGeneratingDescription ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />}
                          Gerar com IA
                        </button>
                      </div>
                      <textarea value={newServiceDesc} onChange={e => setNewServiceDesc(e.target.value)} rows={3} placeholder="Descreva o serviço..." className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all resize-none" />
                    </div>
                    <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl uppercase tracking-widest shadow-lg hover:bg-amber-400 transition-all">Salvar no Catálogo</button>
                  </form>
                </div>

                {/* Service List */}
                <div className="xl:col-span-2 space-y-4">
                  {services.map(s => (
                    <div key={s.id} className="bg-slate-900 p-5 md:p-6 rounded-2xl border border-slate-800 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 group hover:border-amber-500 transition-all">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                          <span className="text-[8px] font-black uppercase px-1.5 py-0.5 bg-slate-800 text-amber-500 rounded border border-slate-700">{s.category}</span>
                          <h4 className="text-lg font-black italic uppercase tracking-tight text-white group-hover:text-amber-500 transition-colors leading-none">{s.name}</h4>
                        </div>
                        <p className="text-slate-500 text-xs italic line-clamp-2 md:line-clamp-1">{s.description}</p>
                      </div>
                      <div className="flex items-center gap-6 w-full md:w-auto border-t md:border-t-0 border-slate-800 pt-4 md:pt-0">
                        <div className="text-left md:text-right flex-1 md:flex-none">
                          <p className="text-xl font-black italic text-white leading-none">R$ {s.price.toFixed(2)}</p>
                          <p className="text-[10px] text-slate-600 font-bold uppercase tracking-widest mt-1">{s.duration} MIN</p>
                        </div>
                        <button onClick={() => deleteService(s.id)} className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={18}/></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeView === 'bookings' && (
            <div className="space-y-10">
              <div>
                <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Operação</p>
                <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">AGENDA DE <span className="text-amber-500">TRABALHO</span></h2>
              </div>

              <div className="bg-slate-900 rounded-[2rem] border border-slate-800 shadow-xl">
                <div className="overflow-x-auto">
                  <table className="w-full min-w-[800px] text-left">
                    <thead className="bg-slate-950/50 border-b border-slate-800">
                      <tr>
                        <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Cliente</th>
                        <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Serviço</th>
                        <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Data/Hora</th>
                        <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Status</th>
                        <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/50">
                      {bookings.map(b => {
                        const service = services.find(s => s.id === b.serviceId);
                        return (
                          <tr key={b.id} className="hover:bg-slate-800/20 transition-colors">
                            <td className="p-6">
                              <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-amber-500/10 flex items-center justify-center text-amber-500 border border-amber-500/20 font-black italic text-lg shadow-inner">
                                  {b.clientName.charAt(0)}
                                </div>
                                <div>
                                  <p className="text-sm font-bold uppercase italic leading-none">{b.clientName}</p>
                                  <p className="text-[10px] text-slate-600 font-medium mt-1 lowercase">{b.clientEmail}</p>
                                </div>
                              </div>
                            </td>
                            <td className="p-6">
                              <p className="text-xs font-black uppercase text-amber-500">{service?.name || '---'}</p>
                              <p className="text-[10px] text-slate-500 mt-0.5">R$ {service?.price.toFixed(2)}</p>
                            </td>
                            <td className="p-6">
                              <p className="text-xs font-bold text-white uppercase">{b.date}</p>
                              <p className="text-[10px] text-slate-500 uppercase font-black mt-0.5 tracking-tighter">{b.time}</p>
                            </td>
                            <td className="p-6">
                              <span className={`text-[9px] font-black uppercase tracking-widest px-2.5 py-1 rounded-lg border ${
                                b.status === 'confirmed' ? 'text-green-500 border-green-500/20 bg-green-500/5' : 
                                b.status === 'pending' ? 'text-amber-500 border-amber-500/20 bg-amber-500/5' : 
                                'text-red-500 border-red-500/20 bg-red-500/5'
                              }`}>
                                {b.status === 'confirmed' ? 'Confirmado' : b.status === 'pending' ? 'Pendente' : 'Cancelado'}
                              </span>
                            </td>
                            <td className="p-6 text-right">
                              <div className="flex justify-end gap-2">
                                {b.status === 'pending' && (
                                  <button onClick={() => confirmBooking(b.id)} className="p-2.5 bg-green-500 text-slate-950 rounded-xl hover:bg-green-400 transition-all"><Check size={14} /></button>
                                )}
                                <button onClick={() => deleteBooking(b.id)} className="p-2.5 bg-slate-800 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={14} /></button>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                  {bookings.length === 0 && (
                    <div className="p-20 text-center text-slate-600">
                      <p className="italic text-sm">Nenhum registro encontrado na agenda.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeView === 'ai-assistant' && (
            <div className="h-[calc(100dvh-120px)] md:h-[calc(100vh-160px)] flex flex-col space-y-8">
              <div className="flex justify-between items-center shrink-0">
                <div>
                  <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Estratégia</p>
                  <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter leading-none">CONSULTORIA <span className="text-amber-500">IA</span></h2>
                </div>
                <div className="p-4 bg-amber-500 text-slate-950 rounded-2xl shadow-lg shadow-amber-500/20"><Bot size={28} /></div>
              </div>

              <div className="flex-1 bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-xl overflow-hidden flex flex-col min-h-0">
                <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
                  {aiChat.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-30 px-6">
                      <Sparkles size={60} className="text-amber-500" />
                      <p className="text-xs md:text-sm font-black uppercase tracking-widest italic leading-relaxed">Olá, Comandante! Sou seu estrategista BarberPro. Como posso ajudar a escalar seus lucros hoje?</p>
                    </div>
                  )}
                  {aiChat.map((msg, i) => (
                    <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] md:max-w-[70%] p-4 md:p-6 rounded-2xl shadow-sm ${
                        msg.role === 'user' 
                        ? 'bg-amber-500 text-slate-950 rounded-tr-none font-bold italic' 
                        : 'bg-slate-800 text-slate-200 rounded-tl-none border border-slate-700 leading-relaxed text-sm'
                      }`}>
                        {msg.content}
                      </div>
                    </div>
                  ))}
                  {isAiLoading && (
                    <div className="flex justify-start">
                      <div className="bg-slate-800 p-5 rounded-2xl rounded-tl-none border border-slate-700 flex items-center gap-3">
                        <Loader2 size={16} className="animate-spin text-amber-500" />
                        <span className="text-[10px] font-black uppercase tracking-widest italic text-slate-400">Processando inteligência de mercado...</span>
                      </div>
                    </div>
                  )}
                </div>
                <form onSubmit={handleAiAsk} className="p-4 md:p-6 bg-slate-950/50 border-t border-slate-800 flex gap-3 shrink-0">
                  <input value={aiInput} onChange={e => setAiInput(e.target.value)} placeholder="Pergunte sobre tendências, preços ou marketing..." className="flex-1 bg-slate-800 border border-slate-700 rounded-2xl px-5 text-sm text-white outline-none focus:border-amber-500 transition-all placeholder:text-slate-600" />
                  <button type="submit" disabled={isAiLoading || !aiInput.trim()} className="p-4 md:p-5 bg-amber-500 text-slate-950 rounded-2xl hover:bg-amber-400 disabled:opacity-50 transition-all shadow-lg shadow-amber-500/10">
                    <Send size={20} />
                  </button>
                </form>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Scissors, 
  CalendarDays, 
  Sparkles, 
  Plus, 
  Trash2, 
  Clock, 
  DollarSign,
  Menu,
  X,
  ArrowLeft,
  Check,
  Calendar,
  LogOut,
  TrendingUp,
  Bot,
  Send,
  Loader2,
  User as UserIcon,
  ChevronRight,
  Pencil,
  RotateCcw
} from 'lucide-react';
