import { INITIAL_SERVICES, INITIAL_BOOKINGS, CATEGORIES, INITIAL_TEAM } from './constants.tsx';
import { generateServiceDescription, askExpertAssistant } from './geminiService.ts';
import LandingPage from './LandingPage.tsx';

// --- Sub-components ---

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button 
    onClick={onClick} 
    className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all text-[11px] font-black uppercase tracking-widest ${
      active 
      ? 'bg-amber-500 text-slate-950 shadow-lg shadow-amber-500/20' 
      : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    {icon} {label}
  </button>
);

const StatCard = ({ label, value, icon, color = "amber" }: any) => {
  const colors: any = {
    amber: 'text-amber-500 bg-amber-500/10 border-amber-500/20',
    green: 'text-green-500 bg-green-500/10 border-green-500/20',
    blue: 'text-blue-500 bg-blue-500/10 border-blue-500/20',
    indigo: 'text-indigo-500 bg-indigo-500/10 border-indigo-500/20'
  };
  return (
    <div className="bg-slate-900 p-5 md:p-6 rounded-3xl border border-slate-800 flex justify-between items-center shadow-xl">
      <div>
        <p className="text-[9px] md:text-[10px] font-black uppercase text-slate-500 mb-1 tracking-widest">{label}</p>
        <h4 className="text-lg md:text-xl font-black italic text-white leading-none">{value}</h4>
      </div>
      <div className={`p-3 md:p-4 rounded-2xl border ${colors[color]}`}>{icon}</div>
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const [services, setServices] = useState<Service[]>(() => {
    const s = localStorage.getItem('barberpro_services');
    return s ? JSON.parse(s) : INITIAL_SERVICES;
  });
  const [bookings, setBookings] = useState<Booking[]>(() => {
    const b = localStorage.getItem('barberpro_bookings');
    return b ? JSON.parse(b) : INITIAL_BOOKINGS;
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiChat, setAiChat] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [aiInput, setAiInput] = useState("");

  // Form states for adding/editing service
  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCategory, setNewServiceCategory] = useState(CATEGORIES[0]);
  const [newServicePrice, setNewServicePrice] = useState("50");
  const [newServiceDuration, setNewServiceDuration] = useState("45");
  const [newServiceDesc, setNewServiceDesc] = useState("");

  useEffect(() => localStorage.setItem('barberpro_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)), [bookings]);

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    setActiveView('landing');
    alert("Agendamento realizado com sucesso! Aguarde a confirmação via e-mail.");
  };

  const confirmBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'confirmed'} : b));
  const cancelBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'cancelled'} : b));
  const deleteBooking = (id: string) => setBookings(p => p.filter(b => b.id !== id));

  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingServiceId) {
      setServices(prev => prev.map(s => s.id === editingServiceId ? {
        ...s,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      } : s));
      setEditingServiceId(null);
      alert("Serviço atualizado!");
    } else {
      const service: Service = {
        id: `s${Date.now()}`,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      };
      setServices(prev => [...prev, service]);
      alert("Serviço adicionado ao catálogo!");
    }
    resetForm();
  };

  const resetForm = () => {
    setEditingServiceId(null);
    setNewServiceName("");
    setNewServiceCategory(CATEGORIES[0]);
    setNewServicePrice("50");
    setNewServiceDuration("45");
    setNewServiceDesc("");
  };

  const startEditing = (s: Service) => {
    setEditingServiceId(s.id);
    setNewServiceName(s.name);
    setNewServiceCategory(s.category);
    setNewServicePrice(s.price.toString());
    setNewServiceDuration(s.duration.toString());
    setNewServiceDesc(s.description);
    // Scroll to form on mobile
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const deleteService = (id: string) => {
    if (confirm("Deseja realmente remover este serviço do catálogo?")) {
      setServices(prev => prev.filter(s => s.id !== id));
      if (editingServiceId === id) resetForm();
    }
  };

  const handleGenerateAIDescription = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço para que a IA possa trabalhar!");
    setIsGeneratingDescription(true);
