      ? 'bg-amber-500 text-slate-950 shadow-lg shadow-amber-500/20' 
      : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    {icon} {label}
  </button>
);

const StatCard = ({ label, value, icon, color = "amber" }: any) => {
  const colors: any = {
    amber: 'text-amber-500 bg-amber-500/10 border-amber-500/20',
    green: 'text-green-500 bg-green-500/10 border-green-500/20',
    blue: 'text-blue-500 bg-blue-500/10 border-blue-500/20',
    indigo: 'text-indigo-500 bg-indigo-500/10 border-indigo-500/20'
  };
  return (
    <div className="bg-slate-900 p-5 md:p-6 rounded-3xl border border-slate-800 flex justify-between items-center shadow-xl">
      <div>
        <p className="text-[9px] md:text-[10px] font-black uppercase text-slate-500 mb-1 tracking-widest">{label}</p>
        <h4 className="text-lg md:text-xl font-black italic text-white leading-none">{value}</h4>
      </div>
      <div className={`p-3 md:p-4 rounded-2xl border ${colors[color]}`}>{icon}</div>
    </div>
  );
};

