  const [aiChat, setAiChat] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [aiInput, setAiInput] = useState("");

  // Form states for adding/editing service
  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCategory, setNewServiceCategory] = useState(CATEGORIES[0]);
  const [newServicePrice, setNewServicePrice] = useState("50");
  const [newServiceDuration, setNewServiceDuration] = useState("45");
  const [newServiceDesc, setNewServiceDesc] = useState("");

  useEffect(() => localStorage.setItem('barberpro_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)), [bookings]);

  const addBooking = (b: Booking) => {
    setBookings(prev => [...prev, b]);
    setActiveView('landing');
    alert("Agendamento realizado com sucesso! Verifique seu e-mail.");
  };

  const confirmBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'confirmed'} : b));
  const cancelBooking = (id: string) => setBookings(p => p.map(b => b.id === id ? {...b, status: 'cancelled'} : b));
  const deleteBooking = (id: string) => setBookings(p => p.filter(b => b.id !== id));

  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingServiceId) {
      setServices(prev => prev.map(s => s.id === editingServiceId ? {
        ...s,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      } : s));
      alert("Serviço atualizado com sucesso!");
    } else {
      const service: Service = {
        id: `s${Date.now()}`,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      };
      setServices(prev => [...prev, service]);
      alert("Novo serviço adicionado!");
    }
    resetForm();
  };

  const resetForm = () => {
    setEditingServiceId(null);
    setNewServiceName("");
    setNewServiceCategory(CATEGORIES[0]);
    setNewServicePrice("50");
    setNewServiceDuration("45");
    setNewServiceDesc("");
  };

  const startEditing = (s: Service) => {
    setEditingServiceId(s.id);
    setNewServiceName(s.name);
    setNewServiceCategory(s.category);
    setNewServicePrice(s.price.toString());
    setNewServiceDuration(s.duration.toString());
    setNewServiceDesc(s.description);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setIsSidebarOpen(false); // Close sidebar on mobile if open
  };

  const deleteService = (id: string) => {
    if (window.confirm("Deseja realmente excluir este serviço? Esta ação não pode ser desfeita.")) {
      setServices(prev => {
        const updated = prev.filter(s => s.id !== id);
        return updated;
      });
      if (editingServiceId === id) resetForm();
    }
  };

  const handleGenerateAIDescription = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço primeiro.");
    setIsGeneratingDescription(true);
    const desc = await generateServiceDescription(newServiceName, newServiceCategory);
    setNewServiceDesc(desc);
    setIsGeneratingDescription(false);
  };

  const handleSuggestPrice = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço primeiro.");
    setIsSuggestingPrice(true);
    const suggested = await suggestPricing(newServiceName, parseInt(newServiceDuration));
    if (suggested) setNewServicePrice(suggested.toString());
    setIsSuggestingPrice(false);
  };

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!aiInput.trim()) return;
    const userMsg = aiInput;
    setAiInput("");
    setAiChat(p => [...p, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);
    const response = await askExpertAssistant(userMsg, services.map(s => s.name));
    setAiChat(p => [...p, { role: 'ai', content: response }]);
    setIsAiLoading(false);
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // View Render Logic
  if (activeView === 'landing') return <LandingPage services={services} team={INITIAL_TEAM} onBookNow={() => setActiveView('client-booking')} onAdminAccess={() => setActiveView('login')} />;

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-[2rem] p-8 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Sair
        </button>
        <div className="text-center mb-8">
          <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter leading-none">Acesso <span className="text-amber-500">Master</span></h2>
        </div>
        <form onSubmit={e => {
          e.preventDefault();
          const pass = new FormData(e.currentTarget).get('password');
          if (pass === "1966") setActiveView('dashboard');
          else alert("Senha incorreta.");
        }} className="space-y-4">
          <input name="password" type="password" placeholder="Chave de Acesso" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-2xl outline-none focus:border-amber-500 transition-all placeholder:text-slate-600" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest shadow-xl hover:bg-amber-400 transition-all">
            Entrar no Painel
          </button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Voltar
        </button>
        <h2 className="text-3xl font-black text-white italic uppercase mb-8 tracking-tighter leading-none">Sua <span className="text-amber-500">Reserva</span></h2>
        <form onSubmit={e => {
          e.preventDefault();
          const fd = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: fd.get('name') as string,
            clientEmail: fd.get('email') as string,
            serviceId: fd.get('service') as string,
            date: fd.get('date') as string,
            time: fd.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-5">
          <input name="name" placeholder="Nome Completo" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          <select name="service" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all appearance-none">
            <option value="">Escolha o serviço...</option>
            {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
