              <h1 className="text-xl font-black italic uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button onClick={toggleSidebar} className="lg:hidden p-2 text-slate-400"><X size={24}/></button>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18} />} label="Início" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={18} />} label="Catálogo" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={18} />} label="Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Bot size={18} />} label="Consultor IA" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
