              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                <StatCard label="Faturamento" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={20} />} color="green" />
                <StatCard label="Aguardando" value={bookings.filter(b => b.status === 'pending').length.toString()} icon={<TrendingUp size={20} />} color="amber" />
                <StatCard label="Agendas" value={bookings.length.toString()} icon={<Calendar size={20} />} color="blue" />
                <StatCard label="Catálogo" value={services.length.toString()} icon={<Scissors size={20} />} color="indigo" />
              </div>
            </div>
