              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Configurações</p>
                  <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">MEU <span className="text-amber-500">CATÁLOGO</span></h2>
                </div>
                {editingServiceId && (
                  <button onClick={resetForm} className="flex items-center gap-2 px-4 py-3 bg-slate-800 text-slate-400 rounded-xl hover:bg-slate-700 transition-all uppercase font-black text-[10px] tracking-widest border border-slate-700 w-full md:w-auto justify-center">
                    <RotateCcw size={14} /> Novo Cadastro
                  </button>
                )}
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* FORM PANEL - Full Width on Mobile */}
                <div className={`xl:col-span-1 p-6 md:p-8 rounded-[2rem] border transition-all shadow-xl h-fit lg:sticky lg:top-4 ${editingServiceId ? 'bg-amber-500/5 border-amber-500/40' : 'bg-slate-900 border-slate-800'}`}>
                  <div className="flex items-center gap-3 mb-8 border-b border-slate-800 pb-4">
                    {editingServiceId ? <Pencil className="text-amber-500" size={18} /> : <Plus className="text-amber-500" size={18} />}
                    <h3 className="font-black text-[10px] uppercase tracking-[0.2em] text-slate-500">
                      {editingServiceId ? 'Editar Serviço' : 'Novo Serviço'}
                    </h3>
                  </div>
                  <form onSubmit={handleSaveService} className="space-y-5">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Nome do Serviço</label>
                      <input value={newServiceName} onChange={e => setNewServiceName(e.target.value)} placeholder="Ex: Barba Terapia" required className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Categoria</label>
                      <select value={newServiceCategory} onChange={e => setNewServiceCategory(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all">
                        {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <div className="flex justify-between items-center mb-1 px-1">
                          <label className="text-[10px] font-black uppercase text-slate-500">Preço</label>
                          <button type="button" onClick={handleSuggestPrice} disabled={isSuggestingPrice} className="text-[8px] font-black text-amber-500 hover:underline uppercase tracking-tighter">Sugerir</button>
                        </div>
                        <input type="number" step="0.01" value={newServicePrice} onChange={e => setNewServicePrice(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Minutos</label>
                        <input type="number" value={newServiceDuration} onChange={e => setNewServiceDuration(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <div className="flex justify-between items-center mb-1 px-1">
                        <label className="text-[10px] font-black uppercase text-slate-500">Descrição</label>
                        <button type="button" onClick={handleGenerateAIDescription} disabled={isGeneratingDescription} className="text-[8px] font-black text-amber-500 hover:underline uppercase tracking-tighter">IA Assist</button>
                      </div>
                      <textarea value={newServiceDesc} onChange={e => setNewServiceDesc(e.target.value)} rows={3} placeholder="Destaque os diferenciais..." className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500 transition-all resize-none" />
                    </div>
                    <button type="submit" className={`w-full py-5 font-black rounded-xl uppercase tracking-widest shadow-lg transition-all ${editingServiceId ? 'bg-amber-500 text-slate-950 hover:bg-amber-400' : 'bg-slate-700 text-white hover:bg-slate-600'}`}>
                      {editingServiceId ? 'Atualizar Dados' : 'Cadastrar Serviço'}
                    </button>
                  </form>
                </div>

                {/* LIST PANEL - Mobile Optimized Actions */}
                <div className="xl:col-span-2 space-y-4">
                  {services.map(s => (
                    <div key={s.id} className={`p-5 md:p-6 rounded-[1.5rem] border transition-all flex flex-col md:flex-row justify-between items-start md:items-center gap-4 ${editingServiceId === s.id ? 'bg-amber-500/10 border-amber-500 shadow-lg shadow-amber-500/5 ring-1 ring-amber-500' : 'bg-slate-900 border-slate-800 hover:border-slate-700'}`}>
                      <div className="flex-1 w-full">
                        <div className="flex items-center gap-2 mb-2 flex-wrap">
                          <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded border ${editingServiceId === s.id ? 'bg-amber-500 text-slate-950 border-amber-500' : 'bg-slate-800 text-amber-500 border-slate-700'}`}>{s.category}</span>
                          <h4 className={`text-xl font-black italic uppercase tracking-tight leading-none ${editingServiceId === s.id ? 'text-amber-500' : 'text-white'}`}>{s.name}</h4>
                        </div>
                        <p className="text-slate-500 text-xs italic leading-relaxed line-clamp-2 md:line-clamp-1">{s.description}</p>
                      </div>
                      <div className="flex items-center gap-4 w-full md:w-auto border-t md:border-t-0 border-slate-800/50 pt-4 md:pt-0">
                        <div className="text-left md:text-right flex-1 md:flex-none">
                          <p className="text-xl md:text-2xl font-black italic text-white leading-none">R$ {s.price.toFixed(2)}</p>
                          <p className="text-[10px] text-slate-600 font-bold uppercase tracking-widest mt-1">{s.duration} MIN</p>
                        </div>
                        <div className="flex gap-2">
                          <button 
                            onClick={(e) => { e.stopPropagation(); startEditing(s); }} 
                            className={`p-4 rounded-xl transition-all shadow-sm ${editingServiceId === s.id ? 'bg-amber-500 text-slate-950' : 'bg-slate-800 text-slate-400 active:bg-amber-500/30'}`}
                            title="Editar"
                          >
                            <Pencil size={20}/>
                          </button>
                          <button 
                            onClick={(e) => { e.stopPropagation(); deleteService(s.id); }} 
                            className="p-4 bg-red-500/10 text-red-500 rounded-xl active:bg-red-500 active:text-white transition-all border border-red-500/20"
                            title="Excluir"
                          >
                            <Trash2 size={20}/>
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeView === 'bookings' && (
            <div className="space-y-10">
              <div>
                <p className="text-amber-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Operação</p>
                <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter leading-none">AGENDA DE <span className="text-amber-500">TRABALHO</span></h2>
