                <div className="overflow-x-auto">
                  <table className="w-full min-w-[700px] text-left">
                    <thead className="bg-slate-950/50 border-b border-slate-800">
                      <tr>
                        <th className="p-5 text-[10px] font-black uppercase tracking-widest text-slate-500">Cliente</th>
                        <th className="p-5 text-[10px] font-black uppercase tracking-widest text-slate-500">Serviço</th>
                        <th className="p-5 text-[10px] font-black uppercase tracking-widest text-slate-500">Data/Hora</th>
                        <th className="p-5 text-[10px] font-black uppercase tracking-widest text-slate-500">Status</th>
                        <th className="p-5 text-[10px] font-black uppercase tracking-widest text-slate-500 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/50">
                      {bookings.map(b => (
                        <tr key={b.id} className="hover:bg-slate-800/20 transition-colors">
