      const service: Service = {
        id: `s${Date.now()}`,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      };
      setServices(prev => [...prev, service]);
      alert("Serviço adicionado!");
