const TeamCard: React.FC<{ name: string; role: string; specialty: string; image: string }> = ({ name, role, specialty, image }) => {
  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const response = await fetch(image);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `mestre_${name.toLowerCase().replace(/\s+/g, '_')}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      window.open(image, '_blank');
    }
  };

  return (
    <div className="group relative overflow-hidden rounded-[2.5rem] bg-slate-900 border border-slate-800 transition-all hover:border-amber-500">
      <div className="aspect-[4/5] overflow-hidden relative">
