const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const [services, setServices] = useState<Service[]>(() => {
    const s = localStorage.getItem('barberpro_services');
    return s ? JSON.parse(s) : INITIAL_SERVICES;
  });
  const [team, setTeam] = useState<TeamMember[]>(() => {
    const t = localStorage.getItem('barberpro_team');
    return t ? JSON.parse(t) : INITIAL_TEAM;
  });
  const [bookings, setBookings] = useState<Booking[]>(() => {
    const b = localStorage.getItem('barberpro_bookings');
    return b ? JSON.parse(b) : INITIAL_BOOKINGS;
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isSuggestingPrice, setIsSuggestingPrice] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiChat, setAiChat] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [aiInput, setAiInput] = useState("");

  const [preselectedMember, setPreselectedMember] = useState<TeamMember | null>(null);

  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCategory, setNewServiceCategory] = useState(CATEGORIES[0]);
  const [newServicePrice, setNewServicePrice] = useState("50");
  const [newServiceDuration, setNewServiceDuration] = useState("45");
  const [newServiceDesc, setNewServiceDesc] = useState("");

  const [editingMemberId, setEditingMemberId] = useState<string | null>(null);
  const [newMemberName, setNewMemberName] = useState("");
  const [newMemberImage, setNewMemberImage] = useState("");
  const [newMemberRole, setNewMemberRole] = useState("");
  const [newMemberSpecialty, setNewMemberSpecialty] = useState("");

  useEffect(() => localStorage.setItem('barberpro_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('barberpro_team', JSON.stringify(team)), [team]);
  useEffect(() => localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)), [bookings]);

  const addBooking = (b: Booking) => {
    const service = services.find(s => s.id === b.serviceId);
    playSuccessSound();
    setBookings(prev => [...prev, b]);
    setActiveView('landing');
    setPreselectedMember(null);
    alert(`Agendamento realizado com sucesso!\n\nServiço: ${service?.name}\nValor: R$ ${service?.price.toFixed(2)}\nHorário: ${b.date} às ${b.time}`);
  };

  const deleteBooking = (id: string) => setBookings(p => p.filter(b => b.id !== id));

  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingServiceId) {
      setServices(prev => prev.map(s => s.id === editingServiceId ? {
        ...s,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      } : s));
      alert("Serviço atualizado!");
    } else {
      const service: Service = {
        id: `s${Date.now()}`,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      };
      setServices(prev => [...prev, service]);
      alert("Serviço adicionado!");
    }
    resetForm();
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMemberImage) return alert("Selecione uma foto para o mestre.");

    if (editingMemberId) {
      setTeam(prev => prev.map(m => m.id === editingMemberId ? {
        ...m,
        name: newMemberName,
        image: newMemberImage,
        role: newMemberRole,
        specialty: newMemberSpecialty
      } : m));
      alert("Mestre atualizado!");
    } else {
      const member: TeamMember = {
        id: `t${Date.now()}`,
        name: newMemberName,
        image: newMemberImage,
        role: newMemberRole || "Barbeiro",
        specialty: newMemberSpecialty || "Cortes Modernos"
      };
      setTeam(prev => [...prev, member]);
      alert("Novo mestre adicionado!");
    }
    resetMemberForm();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewMemberImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetForm = () => {
    setEditingServiceId(null);
    setNewServiceName("");
    setNewServiceCategory(CATEGORIES[0]);
    setNewServicePrice("50");
    setNewServiceDuration("45");
    setNewServiceDesc("");
  };

  const resetMemberForm = () => {
    setEditingMemberId(null);
    setNewMemberName("");
    setNewMemberImage("");
    setNewMemberRole("");
    setNewMemberSpecialty("");
  };

  const startEditing = (s: Service) => {
    setEditingServiceId(s.id);
    setNewServiceName(s.name);
    setNewServiceCategory(s.category);
    setNewServicePrice(s.price.toString());
    setNewServiceDuration(s.duration.toString());
    setNewServiceDesc(s.description);
    window.scrollTo({ top: 0, behavior: 'smooth' });
