      setTeam(prev => prev.filter(m => m.id !== id));
      if (editingMemberId === id) resetMemberForm();
    }
  };

  const handleDownloadPhoto = async (member: TeamMember) => {
    try {
      // Se for Base64, podemos baixar direto, se for URL fazemos fetch
      if (member.image.startsWith('data:')) {
        const link = document.createElement('a');
        link.href = member.image;
        link.download = `barberpro_${member.name.toLowerCase().replace(/\s+/g, '_')}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } else {
        const response = await fetch(member.image);
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `barberpro_${member.name.toLowerCase().replace(/\s+/g, '_')}.jpg`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      }
    } catch (err) {
      window.open(member.image, '_blank');
    }
  };

  const handleGenerateAIDescription = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço.");
    setIsGeneratingDescription(true);
    const desc = await generateServiceDescription(newServiceName, newServiceCategory);
    setNewServiceDesc(desc);
    setIsGeneratingDescription(false);
  };

  const handleSuggestPrice = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço.");
    setIsSuggestingPrice(true);
    const suggested = await suggestPricing(newServiceName, parseInt(newServiceDuration));
    if (suggested) setNewServicePrice(suggested.toString());
