  };

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!aiInput.trim()) return;
    const userMsg = aiInput;
    setAiInput("");
    setAiChat(p => [...p, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);
    const response = await askExpertAssistant(userMsg, services.map(s => s.name));
    setAiChat(p => [...p, { role: 'ai', content: response }]);
    setIsAiLoading(false);
    playAiSound();
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const getPreselectedServiceId = () => {
    if (!preselectedMember) return "";
    const found = services.find(s => 
      s.name.toLowerCase().includes(preselectedMember.specialty.toLowerCase()) ||
      preselectedMember.specialty.toLowerCase().includes(s.name.toLowerCase())
    );
    return found ? found.id : "";
