      : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    {icon} {label}
  </button>
);

const StatCard = ({ label, value, icon, color = "amber" }: any) => {
  const colors: any = {
    amber: 'text-amber-500 bg-amber-500/10 border-amber-500/20',
    green: 'text-green-500 bg-green-500/10 border-green-500/20',
    blue: 'text-blue-500 bg-blue-500/10 border-blue-500/20',
    indigo: 'text-indigo-500 bg-indigo-500/10 border-indigo-500/20'
  };
  return (
    <div className="bg-slate-900 p-5 md:p-6 rounded-3xl border border-slate-800 flex justify-between items-center shadow-xl">
      <div>
        <p className="text-[9px] md:text-[10px] font-black uppercase text-slate-500 mb-1 tracking-widest">{label}</p>
        <h4 className="text-lg md:text-xl font-black italic text-white leading-none">{value}</h4>
      </div>
      <div className={`p-3 md:p-4 rounded-2xl border ${colors[color]}`}>{icon}</div>
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('landing');
  const [services, setServices] = useState<Service[]>(() => {
    const s = localStorage.getItem('barberpro_services');
    return s ? JSON.parse(s) : INITIAL_SERVICES;
  });
  const [team, setTeam] = useState<TeamMember[]>(() => {
    const t = localStorage.getItem('barberpro_team');
    return t ? JSON.parse(t) : INITIAL_TEAM;
  });
  const [bookings, setBookings] = useState<Booking[]>(() => {
    const b = localStorage.getItem('barberpro_bookings');
    return b ? JSON.parse(b) : INITIAL_BOOKINGS;
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isSuggestingPrice, setIsSuggestingPrice] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiChat, setAiChat] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [aiInput, setAiInput] = useState("");

  const [preselectedMember, setPreselectedMember] = useState<TeamMember | null>(null);

  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCategory, setNewServiceCategory] = useState(CATEGORIES[0]);
  const [newServicePrice, setNewServicePrice] = useState("50");
  const [newServiceDuration, setNewServiceDuration] = useState("45");
  const [newServiceDesc, setNewServiceDesc] = useState("");

  const [editingMemberId, setEditingMemberId] = useState<string | null>(null);
  const [newMemberName, setNewMemberName] = useState("");
  const [newMemberImage, setNewMemberImage] = useState("");
  const [newMemberRole, setNewMemberRole] = useState("");
  const [newMemberSpecialty, setNewMemberSpecialty] = useState("");

  useEffect(() => localStorage.setItem('barberpro_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('barberpro_team', JSON.stringify(team)), [team]);
  useEffect(() => localStorage.setItem('barberpro_bookings', JSON.stringify(bookings)), [bookings]);

  const addBooking = (b: Booking) => {
    const service = services.find(s => s.id === b.serviceId);
    playSuccessSound();
    setBookings(prev => [...prev, b]);

    // Preparação da mensagem para WhatsApp/SMS
    const message = `💈 *Novo Agendamento BarberPro!*%0A%0A👤 *Cliente:* ${b.clientName}%0A✂️ *Serviço:* ${service?.name}%0A📅 *Data:* ${b.date}%0A⏰ *Horário:* ${b.time}%0A💰 *Valor:* R$ ${service?.price.toFixed(2)}`;

    // Número para WhatsApp informado: 11984937529
    const whatsappUrl = `https://api.whatsapp.com/send?phone=5511984937529&text=${message}`;

    setActiveView('landing');
    setPreselectedMember(null);

    alert(`Agendamento realizado com sucesso!\n\nServiço: ${service?.name}\nValor: R$ ${service?.price.toFixed(2)}\nHorário: ${b.date} às ${b.time}\n\nUma notificação será enviada via WhatsApp.`);

    // Redireciona para o WhatsApp após o alerta
    window.open(whatsappUrl, '_blank');
  };

  const deleteBooking = (id: string) => setBookings(p => p.filter(b => b.id !== id));

  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingServiceId) {
      setServices(prev => prev.map(s => s.id === editingServiceId ? {
        ...s,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      } : s));
      alert("Serviço atualizado!");
    } else {
      const service: Service = {
        id: `s${Date.now()}`,
        name: newServiceName,
        category: newServiceCategory,
        price: parseFloat(newServicePrice),
        duration: parseInt(newServiceDuration),
        description: newServiceDesc
      };
      setServices(prev => [...prev, service]);
      alert("Serviço adicionado!");
    }
    resetForm();
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMemberImage) return alert("Selecione uma foto para o mestre.");

    if (editingMemberId) {
      setTeam(prev => prev.map(m => m.id === editingMemberId ? {
        ...m,
        name: newMemberName,
        image: newMemberImage,
        role: newMemberRole,
        specialty: newMemberSpecialty
      } : m));
      alert("Mestre atualizado!");
    } else {
      const member: TeamMember = {
        id: `t${Date.now()}`,
        name: newMemberName,
        image: newMemberImage,
        role: newMemberRole || "Barbeiro",
        specialty: newMemberSpecialty || "Cortes Modernos"
      };
      setTeam(prev => [...prev, member]);
      alert("Novo mestre adicionado!");
    }
    resetMemberForm();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewMemberImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetForm = () => {
    setEditingServiceId(null);
    setNewServiceName("");
    setNewServiceCategory(CATEGORIES[0]);
    setNewServicePrice("50");
    setNewServiceDuration("45");
    setNewServiceDesc("");
  };

  const resetMemberForm = () => {
    setEditingMemberId(null);
    setNewMemberName("");
    setNewMemberImage("");
    setNewMemberRole("");
    setNewMemberSpecialty("");
  };

  const startEditing = (s: Service) => {
    setEditingServiceId(s.id);
    setNewServiceName(s.name);
    setNewServiceCategory(s.category);
    setNewServicePrice(s.price.toString());
    setNewServiceDuration(s.duration.toString());
    setNewServiceDesc(s.description);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const startEditingMember = (m: TeamMember) => {
    setEditingMemberId(m.id);
    setNewMemberName(m.name);
    setNewMemberImage(m.image);
    setNewMemberRole(m.role);
    setNewMemberSpecialty(m.specialty);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const deleteService = (id: string) => {
    if (window.confirm("Deseja realmente excluir este serviço?")) {
      setServices(prev => prev.filter(s => s.id !== id));
      if (editingServiceId === id) resetForm();
    }
  };

  const deleteMember = (id: string) => {
    if (window.confirm("Deseja realmente excluir este mestre da equipe?")) {
      setTeam(prev => prev.filter(m => m.id !== id));
      if (editingMemberId === id) resetMemberForm();
    }
  };

  const handleDownloadPhoto = async (member: TeamMember) => {
    try {
      if (member.image.startsWith('data:')) {
        const link = document.createElement('a');
        link.href = member.image;
        link.download = `barberpro_${member.name.toLowerCase().replace(/\s+/g, '_')}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } else {
        const response = await fetch(member.image);
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `barberpro_${member.name.toLowerCase().replace(/\s+/g, '_')}.jpg`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      }
    } catch (err) {
      window.open(member.image, '_blank');
    }
  };

  const handleGenerateAIDescription = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço.");
    setIsGeneratingDescription(true);
    const desc = await generateServiceDescription(newServiceName, newServiceCategory);
    setNewServiceDesc(desc);
    setIsGeneratingDescription(false);
  };

  const handleSuggestPrice = async () => {
    if (!newServiceName) return alert("Digite o nome do serviço.");
    setIsSuggestingPrice(true);
    const suggested = await suggestPricing(newServiceName, parseInt(newServiceDuration));
    if (suggested) setNewServicePrice(suggested.toString());
    setIsSuggestingPrice(false);
  };

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!aiInput.trim()) return;
    const userMsg = aiInput;
    setAiInput("");
    setAiChat(p => [...p, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);
    const response = await askExpertAssistant(userMsg, services.map(s => s.name));
    setAiChat(p => [...p, { role: 'ai', content: response }]);
    setIsAiLoading(false);
    playAiSound();
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const getPreselectedServiceId = () => {
    if (!preselectedMember) return "";
    const found = services.find(s => 
      s.name.toLowerCase().includes(preselectedMember.specialty.toLowerCase()) ||
      preselectedMember.specialty.toLowerCase().includes(s.name.toLowerCase())
    );
    return found ? found.id : "";
  };

  if (activeView === 'landing') return (
    <LandingPage 
      services={services} 
      team={team} 
      onBookNow={() => { setPreselectedMember(null); setActiveView('client-booking'); }} 
      onBookWithMember={(member) => { setPreselectedMember(member); setActiveView('client-booking'); }}
      onAdminAccess={() => setActiveView('login')} 
    />
  );

  if (activeView === 'login') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-[2rem] p-8 md:p-12 shadow-2xl">
        <button onClick={() => setActiveView('landing')} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Sair
        </button>
        <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter text-center mb-8 leading-none">Acesso <span className="text-amber-500">Master</span></h2>
        <form onSubmit={e => {
          e.preventDefault();
          const pass = new FormData(e.currentTarget).get('password');
          if (pass === "1966") setActiveView('dashboard');
          else alert("Senha incorreta.");
        }} className="space-y-4">
          <input name="password" type="password" placeholder="Senha" required className="w-full bg-slate-800 border border-slate-700 text-white p-4 rounded-2xl outline-none focus:border-amber-500 transition-all" />
          <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest shadow-xl hover:bg-amber-400">Entrar</button>
        </form>
      </div>
    </div>
  );

  if (activeView === 'client-booking') return (
    <div className="bg-slate-950 min-h-[100dvh] flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 md:p-12 shadow-2xl">
        <button onClick={() => { setActiveView('landing'); setPreselectedMember(null); }} className="text-slate-500 mb-8 flex items-center gap-2 uppercase font-black text-[10px] tracking-widest hover:text-white transition-colors">
          <ArrowLeft size={16}/> Voltar
        </button>
        <h2 className="text-3xl font-black text-white italic uppercase mb-2 tracking-tighter leading-none">Agendar <span className="text-amber-500">Horário</span></h2>
        {preselectedMember && (
          <p className="text-amber-500/80 text-[10px] font-black uppercase tracking-widest mb-8 italic flex items-center gap-2">
            <Check size={14} /> Atendimento com Mestre {preselectedMember.name}
          </p>
        )}
        <form onSubmit={e => {
          e.preventDefault();
          const fd = new FormData(e.currentTarget);
          addBooking({
            id: `b${Date.now()}`,
            clientName: fd.get('name') as string,
            clientEmail: fd.get('email') as string,
            serviceId: fd.get('service') as string,
            date: fd.get('date') as string,
            time: fd.get('time') as string,
            status: 'pending'
          });
        }} className="space-y-5">
          <input name="name" placeholder="Nome" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          <input name="email" type="email" placeholder="E-mail" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          <select 
            name="service" 
            required 
            defaultValue={getPreselectedServiceId()}
            className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all"
          >
            <option value="">Selecione o Serviço...</option>
            {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
          </select>
          <div className="grid grid-cols-2 gap-4">
            <input name="date" type="date" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
            <input name="time" type="time" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none border border-transparent focus:border-amber-500 transition-all" />
          </div>
          <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest shadow-xl transform active:scale-95 transition-transform">Confirmar Agendamento</button>
        </form>
      </div>
    </div>
  );

  const revenue = bookings.reduce((a, c) => a + (services.find(s => s.id === c.serviceId)?.price || 0), 0);

  return (
    <div className="flex h-[100dvh] bg-slate-950 text-white overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[60] lg:hidden" onClick={toggleSidebar} />}

      <aside className={`fixed inset-y-0 left-0 z-[70] w-72 bg-slate-900 border-r border-slate-800 lg:static lg:translate-x-0 transition-transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setActiveView('landing')}>
              <div className="p-2 bg-amber-500 rounded-xl"><Scissors size={20} className="text-slate-950" /></div>
              <h1 className="text-xl font-black italic uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
            </div>
            <button onClick={toggleSidebar} className="lg:hidden text-slate-400"><X size={24}/></button>
          </div>
          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18} />} label="Painel" active={activeView === 'dashboard'} onClick={() => { setActiveView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Scissors size={18} />} label="Serviços" active={activeView === 'services'} onClick={() => { setActiveView('services'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18} />} label="Equipe" active={activeView === 'team'} onClick={() => { setActiveView('team'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<CalendarDays size={18} />} label="Agenda" active={activeView === 'bookings'} onClick={() => { setActiveView('bookings'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Bot size={18} />} label="IA" active={activeView === 'ai-assistant'} onClick={() => { setActiveView('ai-assistant'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="pt-6 border-t border-slate-800">
            <button onClick={() => setActiveView('landing')} className="flex items-center gap-3 p-4 text-slate-500 hover:text-red-500 uppercase font-black text-[10px] tracking-widest w-full">
              <LogOut size={18} /> Logout
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto">
        <header className="flex items-center justify-between lg:hidden p-4 sticky top-0 bg-slate-950/90 backdrop-blur-md z-40 border-b border-slate-900">
          <button onClick={toggleSidebar} className="p-2 bg-slate-900 rounded-xl text-white"><Menu size={24}/></button>
          <h1 className="text-sm font-black italic uppercase tracking-tighter">BARBER<span className="text-amber-500">PRO</span></h1>
          <div className="w-10"></div>
        </header>

        <div className="p-4 md:p-8 max-w-7xl mx-auto">
          {activeView === 'dashboard' && (
            <div className="space-y-8">
              <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">ESTATÍSTICAS</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Receita Estimada" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={20} />} color="green" />
                <StatCard label="Pendentes" value={bookings.filter(b => b.status === 'pending').length.toString()} icon={<TrendingUp size={20} />} color="amber" />
                <StatCard label="Agendas" value={bookings.length.toString()} icon={<Calendar size={20} />} color="blue" />
                <StatCard label="Serviços" value={services.length.toString()} icon={<Scissors size={20} />} color="indigo" />
              </div>
            </div>
          )}

          {activeView === 'services' && (
            <div className="space-y-8">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">CATÁLOGO</h2>
                {editingServiceId && (
                  <button onClick={resetForm} className="px-4 py-2 bg-slate-800 text-slate-400 rounded-xl text-[10px] font-black uppercase tracking-widest">
                    <RotateCcw size={14} className="inline mr-1" /> Novo Cadastro
                  </button>
                )}
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                <div className={`p-6 md:p-8 rounded-[2rem] border transition-all h-fit ${editingServiceId ? 'bg-amber-500/5 border-amber-500/40' : 'bg-slate-900 border-slate-800'}`}>
                  <h3 className="text-[10px] font-black uppercase text-slate-500 mb-6">{editingServiceId ? 'Editar Serviço' : 'Novo Serviço'}</h3>
                  <form onSubmit={handleSaveService} className="space-y-5">
                    <input value={newServiceName} onChange={e => setNewServiceName(e.target.value)} placeholder="Nome" required className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none focus:border-amber-500 border border-transparent transition-all" />
                    <select value={newServiceCategory} onChange={e => setNewServiceCategory(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none focus:border-amber-500 border border-transparent transition-all">
                      {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <button type="button" onClick={handleSuggestPrice} className="text-[8px] text-amber-500 uppercase font-black mb-1 hover:underline">Sugerir IA</button>
                        <input type="number" step="0.01" value={newServicePrice} onChange={e => setNewServicePrice(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none focus:border-amber-500 border border-transparent" />
                      </div>
                      <div className="space-y-1">
                        <span className="text-[8px] text-slate-500 uppercase font-black mb-1 block">Minutos</span>
                        <input type="number" value={newServiceDuration} onChange={e => setNewServiceDuration(e.target.value)} className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none focus:border-amber-500 border border-transparent" />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <button type="button" onClick={handleGenerateAIDescription} className="text-[8px] text-amber-500 uppercase font-black mb-1 hover:underline">Gerar Descrição IA</button>
                      <textarea value={newServiceDesc} onChange={e => setNewServiceDesc(e.target.value)} rows={3} placeholder="Descrição..." className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none focus:border-amber-500 border border-transparent resize-none" />
                    </div>
                    <button type="submit" className={`w-full py-4 font-black rounded-xl uppercase tracking-widest ${editingServiceId ? 'bg-amber-500 text-slate-950' : 'bg-slate-700 text-white'}`}>
                      {editingServiceId ? 'Atualizar' : 'Cadastrar'}
                    </button>
                  </form>
                </div>

                <div className="xl:col-span-2 space-y-4">
                  {services.map(s => (
                    <div key={s.id} className={`p-5 rounded-2xl border transition-all flex justify-between items-center gap-4 ${editingServiceId === s.id ? 'border-amber-500 bg-amber-500/5' : 'bg-slate-900 border-slate-800'}`}>
                      <div className="flex-1">
                        <span className="text-[8px] font-black uppercase text-amber-500">{s.category}</span>
                        <h4 className="text-xl font-black italic uppercase tracking-tight leading-none text-white">{s.name}</h4>
                        <p className="text-slate-500 text-xs mt-1 line-clamp-1 italic">{s.description}</p>
                      </div>
                      <div className="text-right flex items-center gap-6">
                        <div>
                          <p className="text-xl font-black text-white italic">R$ {s.price.toFixed(2)}</p>
                          <p className="text-[10px] text-slate-600 font-bold uppercase">{s.duration} MIN</p>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => startEditing(s)} className={`p-3 rounded-xl ${editingServiceId === s.id ? 'bg-amber-500 text-slate-950' : 'bg-slate-800 text-slate-400'}`}><Pencil size={18}/></button>
                          <button onClick={() => deleteService(s.id)} className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={18}/></button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeView === 'team' && (
            <div className="space-y-8">
              <div className="flex justify-between items-center">
                <h2 className="text-2xl md:text-4xl font-black italic uppercase tracking-tighter">EQUIPE</h2>
                {editingMemberId && (
                  <button onClick={resetMemberForm} className="px-4 py-2 bg-slate-800 text-slate-400 rounded-xl text-[10px] font-black uppercase tracking-widest">
                    <RotateCcw size={14} className="inline mr-1" /> Novo Mestre
                  </button>
                )}
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
