          {activeView === 'bookings' && (
            <div className="space-y-10">
              <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">AGENDA</h2>
              <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left min-w-[600px]">
                    <thead className="bg-slate-950/50 border-b border-slate-800">
                      <tr>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500">Cliente</th>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500">Serviço</th>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500">Data & Hora</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/50">
                      {bookings.map(b => (
                        <tr key={b.id}>
                          <td className="p-8 font-bold uppercase italic text-white">{b.clientName}</td>
                          <td className="p-8 text-amber-500 font-black uppercase">{services.find(s => s.id === b.serviceId)?.name || 'Outro'}</td>
                          <td className="p-8 text-slate-400 font-medium italic">{b.date.split('-').reverse().join('/')} às {b.time}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

