          {activeView === 'dashboard' && (
            <div className="space-y-10 animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">GESTÃO <span className="text-amber-500">PRO</span></h2>
                <div className="flex items-center gap-3 text-green-500 bg-green-500/10 px-6 py-3 rounded-2xl border border-green-500/20">
                  <Database size={16} /> <span className="text-[10px] font-black uppercase tracking-widest">Base Ativa</span>
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard label="Faturamento" value={`R$ ${revenue.toFixed(2)}`} icon={<DollarSign size={24} />} color="green" />
                <StatCard label="Agendas" value={bookings.length.toString()} icon={<TrendingUp size={24} />} color="amber" />
                <StatCard label="Time" value={team.length.toString()} icon={<Users size={24} />} color="blue" />
                <StatCard label="Serviços" value={services.length.toString()} icon={<Scissors size={24} />} color="indigo" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                {/* Quick Agenda View */}
                <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] p-8 space-y-6">
                  <h3 className="text-lg font-black uppercase italic flex items-center gap-2 text-white">
                    <CalendarDays size={20} className="text-amber-500" /> Próximos Atendimentos
                  </h3>
                  <div className="grid gap-4">
                    {bookings.slice(0, 5).map(b => {
                      const s = services.find(srv => srv.id === b.serviceId);
                      return (
                        <div key={b.id} className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-transparent hover:border-amber-500/30 transition-all">
                          <div>
                              <p className="text-sm font-bold text-white uppercase italic">{b.clientName}</p>
                              <p className="text-[10px] text-amber-500 font-black uppercase">{s?.name} — R$ {s?.price.toFixed(2)}</p>
                          </div>
                          <div className="text-right">
                              <p className="text-sm font-black text-white italic">{b.time}</p>
                              <p className="text-[10px] text-slate-500 uppercase">{b.date.split('-').reverse().join('/')}</p>
                          </div>
                        </div>
                      );
                    })}
                    {bookings.length === 0 && <p className="text-slate-600 text-center py-10 uppercase font-black text-xs italic">Nenhum agendamento futuro</p>}
                  </div>
                </div>

                {/* Dashboard Services List (Catálogo) */}
                <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] p-8 space-y-6">
                  <h3 className="text-lg font-black uppercase italic flex items-center gap-2 text-white">
                    <Scissors size={20} className="text-amber-500" /> Catálogo BarberPro
                  </h3>
                  <div className="grid gap-4">
                    {services.slice(0, 6).map(s => (
                      <div key={s.id} className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-transparent hover:border-slate-700 transition-all group">
                         <div>
                            <p className="text-sm font-bold text-white uppercase italic group-hover:text-amber-500 transition-colors">{s.name}</p>
                            <p className="text-[10px] text-slate-500 font-black uppercase">{s.category}</p>
                         </div>
                         <div className="text-right">
                            <p className="text-sm font-black text-white italic">R$ {s.price.toFixed(2)}</p>
                            <p className="text-[10px] text-amber-500 font-bold uppercase">{s.duration} min</p>
                         </div>
                      </div>
                    ))}
                    <button onClick={() => setActiveView('services')} className="w-full py-3 border border-slate-800 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-800 hover:text-white transition-all">
                      Gerenciar Catálogo Completo
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeView === 'team' && (
            <div className="space-y-10">
              <div className="flex items-center justify-between">
                <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">EQUIPE</h2>
                <button onClick={resetMemberForm} className="px-6 py-3 bg-amber-500 text-slate-950 rounded-xl text-[10px] font-black uppercase tracking-widest">Novo Mestre</button>
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                <div className="p-8 bg-slate-900 border border-slate-800 rounded-[2.5rem] h-fit">
                  <form onSubmit={handleSaveMember} className="space-y-5">
                    <input value={newMemberName} onChange={e => setNewMemberName(e.target.value)} placeholder="Nome" required className="w-full bg-slate-800 p-4 rounded-xl text-white outline-none border border-transparent focus:border-amber-500" />
                    <label className="w-full bg-slate-800 p-4 rounded-xl text-slate-400 border border-dashed border-slate-700 hover:border-amber-500 cursor-pointer flex items-center justify-center gap-2">
                      <Upload size={18} /> <span className="text-[10px] font-black uppercase">FOTO</span>
                      <input type="file" accept="image/*" onChange={handleFileChange} className="hidden" />
                    </label>
                    <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 font-black rounded-xl uppercase tracking-widest hover:bg-amber-400">Gravar Mestre</button>
                  </form>
                </div>
                <div className="xl:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-6">
                  {team.map(m => (
                    <div key={m.id} className="p-6 bg-slate-900 border border-slate-800 rounded-[2.5rem] flex items-center gap-6 group">
                      <div className="w-20 h-20 rounded-2xl overflow-hidden bg-slate-800 border border-slate-700 shrink-0">
                        {m.image ? <img src={m.image} className="w-full h-full object-cover grayscale group-hover:grayscale-0" alt={m.name} /> : <ImageIcon size={24} className="text-slate-600 m-auto" />}
                      </div>
                      <div className="flex-1">
                        <h4 className="text-xl font-black italic uppercase text-white">{m.name}</h4>
                        <p className="text-amber-500 text-[10px] font-black mb-4 uppercase">{m.role}</p>
                        <div className="flex gap-2">
                          <button onClick={() => startEditingMember(m)} className="p-2 bg-slate-800 text-slate-400 rounded-lg hover:text-white transition-all"><Pencil size={14}/></button>
                          <button onClick={() => deleteMember(m.id)} className="p-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"><Trash2 size={14}/></button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeView === 'services' && (
            <div className="space-y-10 animate-in slide-in-from-bottom-4 duration-500">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter leading-none">CATÁLOGO <span className="text-amber-500">EXCLUSIVO</span></h2>
                <button onClick={resetForm} className="w-fit px-8 py-4 bg-amber-500 text-slate-950 rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-amber-400 shadow-xl active:scale-95 transition-all flex items-center gap-2">
                  <Plus size={18} /> Novo Serviço
                </button>
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Form Col */}
                <div className="p-8 rounded-[2.5rem] border bg-slate-900 border-slate-800 h-fit sticky top-10">
                  <h3 className="text-[11px] font-black uppercase text-slate-500 mb-8 tracking-widest flex items-center gap-2">
                    <Database size={14} className="text-amber-500" /> {editingServiceId ? 'Editar Serviço' : 'Cadastrar Serviço'}
                  </h3>
                  <form onSubmit={handleSaveService} className="space-y-5">
                    <div className="space-y-1.5">
                      <span className="text-[10px] text-slate-500 uppercase font-black px-2">Nome</span>
                      <input value={newServiceName} onChange={e => setNewServiceName(e.target.value)} placeholder="Ex: Corte Premium" required className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none focus:border-amber-500 border border-transparent transition-all" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1.5">
                        <span className="text-[10px] text-slate-500 uppercase font-black px-2">Preço (R$)</span>
                        <input type="number" step="0.01" value={newServicePrice} onChange={e => setNewServicePrice(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none focus:border-amber-500 border border-transparent transition-all" />
                      </div>
                      <div className="space-y-1.5">
                        <span className="text-[10px] text-slate-500 uppercase font-black px-2">Duração (Min)</span>
                        <input type="number" value={newServiceDuration} onChange={e => setNewServiceDuration(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none focus:border-amber-500 border border-transparent transition-all" />
                      </div>
                    </div>
                    <div className="space-y-1.5">
                      <span className="text-[10px] text-slate-500 uppercase font-black px-2">Descrição</span>
                      <textarea value={newServiceDesc} onChange={e => setNewServiceDesc(e.target.value)} rows={3} placeholder="Breve resumo do serviço..." className="w-full bg-slate-800 p-4 rounded-2xl text-white outline-none focus:border-amber-500 border border-transparent transition-all resize-none" />
                    </div>
                    <button type="submit" className="w-full py-5 bg-amber-500 text-slate-950 font-black rounded-2xl uppercase tracking-widest hover:bg-amber-400 shadow-xl active:scale-95 transition-all text-sm">
                      {editingServiceId ? 'Salvar Alterações' : 'Gravar Catálogo'}
                    </button>
                  </form>
                </div>

                {/* List Col */}
                <div className="xl:col-span-2 space-y-4">
                  {services.map(s => (
                    <div key={s.id} className="p-6 rounded-[2rem] border bg-slate-900 border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-6 hover:border-slate-700 transition-all group animate-in slide-in-from-right-4 duration-500">
                      <div className="flex-1 min-w-0">
                        <span className="text-[10px] font-black uppercase text-amber-500 tracking-widest mb-1 block">{s.category}</span>
                        <h4 className="text-2xl font-black italic uppercase tracking-tighter text-white mb-2 group-hover:text-amber-500 transition-colors">{s.name}</h4>
                        <p className="text-slate-500 text-sm leading-relaxed line-clamp-1">{s.description}</p>
                      </div>
                      <div className="flex items-center justify-between md:justify-end gap-10">
                        <div className="text-right shrink-0">
                          <p className="text-2xl font-black text-white italic leading-none mb-1">R$ {s.price.toFixed(2)}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest flex items-center justify-end gap-1.5">
                            <Clock size={12} className="text-amber-500" /> {s.duration} MIN
                          </p>
                        </div>
                        <div className="flex items-center gap-2">
                          <button onClick={() => startEditingService(s)} className="p-3.5 rounded-xl bg-slate-800 text-slate-400 hover:text-white transition-all"><Pencil size={18}/></button>
                          <button onClick={() => deleteService(s.id)} className="p-3.5 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={18}/></button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeView === 'bookings' && (
            <div className="space-y-10">
              <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">AGENDA <span className="text-amber-500">PRO</span></h2>
              <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 overflow-hidden shadow-2xl">
                <div className="overflow-x-auto">
                  <table className="w-full text-left min-w-[700px]">
                    <thead className="bg-slate-950/50 border-b border-slate-800">
                      <tr>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500 tracking-widest">Cliente</th>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500 tracking-widest">Serviço</th>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500 tracking-widest">Valor</th>
                        <th className="p-8 text-[11px] font-black uppercase text-slate-500 tracking-widest">Data & Hora</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/50">
                      {bookings.map(b => {
                        const s = services.find(srv => srv.id === b.serviceId);
                        return (
                          <tr key={b.id} className="hover:bg-slate-800/30 transition-colors">
                            <td className="p-8 font-bold uppercase italic text-white">{b.clientName}</td>
                            <td className="p-8 text-amber-500 font-black uppercase">{s?.name || 'Outro'}</td>
                            <td className="p-8 text-white font-black italic">R$ {s?.price.toFixed(2) || '0.00'}</td>
                            <td className="p-8 text-slate-400 font-medium italic">{b.date.split('-').reverse().join('/')} às {b.time}</td>
                          </tr>
                        );
                      })}
                      {bookings.length === 0 && (
                        <tr>
                           <td colSpan={4} className="p-20 text-center text-slate-600 font-black uppercase italic tracking-widest">Nenhum agendamento encontrado</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;
